func (s *protocolFeeStore) getTokenAccrualBucketTree(accrualBuckets *bptree.BPTree, tokenPath string) *bptree.BPTree {
	result := accrualBuckets.Get(tokenPath)
	if result == nil {
		return nil
	}

	tokenBuckets, ok := result.(*bptree.BPTree)
	if !ok {
		panic(ufmt.Errorf("failed to cast result to *bptree.BPTree: %T", result))
	}

	return tokenBuckets
}

// GetAccrualBuckets returns up to limit of the oldest pending buckets of tokenPath in
// epoch order. A limit of zero or less returns every pending bucket.
//
// Parameters:
//   - tokenPath: Token path whose pending Gov/Staker accrual buckets should be read.
//   - limit: Maximum number of buckets to return; zero or a negative value returns all pending buckets.
//
// Returns:
//   - epochs: Epoch numbers for the returned buckets, in ascending BP-tree iteration order.
//   - amounts: Gov/Staker amounts for the returned epochs; amounts[i] corresponds to epochs[i].
func (s *protocolFeeStore) GetAccrualBuckets(tokenPath string, limit int) ([]int64, []int64) {
	epochs := []int64{}
	amounts := []int64{}

	tokenBuckets := s.getTokenAccrualBucketTree(s.getAccrualBucketTree(), tokenPath)
	if tokenBuckets == nil {
		return epochs, amounts
	}

	tokenBuckets.Iterate("", "", func(key string, value any) bool {
		if limit > 0 && len(epochs) >= limit {
			return true
		}

		amount, ok := value.(int64)
		if !ok {
			panic(ufmt.Errorf("failed to cast result to int64: %T", value))
		}

		epochs = append(epochs, decodeEpochKey(key))
		amounts = append(amounts, amount)

		return false
	})

	return epochs, amounts
}

// AddAccrualBucket adds amount to the bucket of tokenPath at epoch.
//
// Parameters:
//   - _: Crossing discriminator for the store operation; pass 0.
//   - rlm: Propagated realm context for this store write; it must be current (`rlm.IsCurrent()`).
//   - tokenPath: Token path whose Gov/Staker accrual bucket is updated.
//   - epoch: Non-negative accrual epoch identifying the bucket; negative epochs panic during key encoding.
//   - amount: Amount to add to the existing bucket value.
//
// Returns:
//   - err: Nil when the bucket tree is persisted; otherwise the current-realm or KV-store write error.
func (s *protocolFeeStore) AddAccrualBucket(_ int, rlm realm, tokenPath string, epoch int64, amount int64) error {
	if !rlm.IsCurrent() {
		return errors.New(errSpoofedRealm)
	}

	accrualBuckets := s.getAccrualBucketTree()
	tokenBuckets := s.getTokenAccrualBucketTree(accrualBuckets, tokenPath)
	if tokenBuckets == nil {
		tokenBuckets = NewBPTreeN(16)
		accrualBuckets.Set(tokenPath, tokenBuckets)
	}

	key := encodeEpochKey(epoch)
	existing := int64(0)
	if result := tokenBuckets.Get(key); result != nil {
		current, ok := result.(int64)
		if !ok {
			panic(ufmt.Errorf("failed to cast result to int64: %T", result))
		}
		existing = current
	}

	tokenBuckets.Set(key, gnsmath.SafeAddInt64(existing, amount))

	return s.kvStore.Set(0, rlm, StoreKeyAccrualBuckets.String(), accrualBuckets)
}

// RemoveAccrualBuckets drops the buckets of tokenPath at the given epochs. The token's
// tree is dropped as well once no bucket remains.
//
// Parameters:
//   - _: Crossing discriminator for the store operation; pass 0.
//   - rlm: Propagated realm context for this store write; it must be current (`rlm.IsCurrent()`).
//   - tokenPath: Token path whose selected accrual buckets are removed.
//   - epochs: Epoch numbers whose buckets should be deleted; an absent token or epoch is ignored.
//
// Returns:
//   - err: Nil when removals are applied (including an absent token); otherwise the current-realm or KV-store write error.
func (s *protocolFeeStore) RemoveAccrualBuckets(_ int, rlm realm, tokenPath string, epochs []int64) error {
	if !rlm.IsCurrent() {
		return errors.New(errSpoofedRealm)
	}

	accrualBuckets := s.getAccrualBucketTree()
	tokenBuckets := s.getTokenAccrualBucketTree(accrualBuckets, tokenPath)
	if tokenBuckets == nil {
		return nil
	}

	for _, epoch := range epochs {
		tokenBuckets.Remove(encodeEpochKey(epoch))
	}

	if tokenBuckets.Size() == 0 {
		accrualBuckets.Remove(tokenPath)
	}

	return s.kvStore.Set(0, rlm, StoreKeyAccrualBuckets.String(), accrualBuckets)
}

// handle accrualPendingTokens store data
//
// accrualPendingTokens is the set of token paths that still own at least one accrual
// bucket, so gov/staker can enumerate what it has to fold without scanning every token.
//
// Returns:
//   - exists: True when the pending-token index key is present in the KV store.
func (s *protocolFeeStore) HasAccrualPendingTokensStoreKey() bool {
	return s.kvStore.Has(StoreKeyAccrualPendingTokens.String())
}

// InitializeAccrualPendingTokens creates the index of tokens with pending accrual buckets.
//
// Parameters:
//   - _: Crossing discriminator for the store operation; pass 0.
//   - rlm: Propagated realm context for this store write; it must be current (`rlm.IsCurrent()`).
//
// Returns:
//   - err: Nil when the pending-token index is initialized; otherwise the current-realm or KV-store write error.
func (s *protocolFeeStore) InitializeAccrualPendingTokens(_ int, rlm realm) error {
	if !rlm.IsCurrent() {
		return errors.New(errSpoofedRealm)
	}

	return s.kvStore.Set(0, rlm, StoreKeyAccrualPendingTokens.String(), NewBPTreeN(16))
}

func (s *protocolFeeStore) getAccrualPendingTokenTree() *bptree.BPTree {
	accrualPendingTokens, err := s.kvStore.GetBPTree(StoreKeyAccrualPendingTokens.String())
	if err != nil {
		panic(err)
	}

	return accrualPendingTokens
}

// GetAccrualPendingTokens returns token paths that still own accrual buckets.
//
// Returns:
//   - tokenPaths: Token paths in the pending-accrual index, in BP-tree iteration order.
func (s *protocolFeeStore) GetAccrualPendingTokens() []string {
	return collectTreeKeys(s.getAccrualPendingTokenTree())
}

// AddAccrualPendingToken adds tokenPath to the pending-accrual index.
//
// Parameters:
//   - _: Crossing discriminator for the store operation; pass 0.
//   - rlm: Propagated realm context for this store write; it must be current (`rlm.IsCurrent()`).
//   - tokenPath: Token path with at least one accrual bucket pending.
//
// Returns:
//   - err: Nil when tokenPath is already present or has been added; otherwise the current-realm or KV-store write error.
func (s *protocolFeeStore) AddAccrualPendingToken(_ int, rlm realm, tokenPath string) error {
	if !rlm.IsCurrent() {
		return errors.New(errSpoofedRealm)
	}

	accrualPendingTokens := s.getAccrualPendingTokenTree()
	if accrualPendingTokens.Has(tokenPath) {
		return nil
	}

	accrualPendingTokens.Set(tokenPath, true)

	return s.kvStore.Set(0, rlm, StoreKeyAccrualPendingTokens.String(), accrualPendingTokens)
}

// RemoveAccrualPendingToken drops one token from the set. It writes only when the
// token was listed.
//
// Parameters:
//   - _: Crossing discriminator for the store operation; pass 0.
//   - rlm: Propagated realm context for this store write; it must be current (`rlm.IsCurrent()`).
//   - tokenPath: Token path to remove from the pending-accrual index.
//
// Returns:
//   - err: Nil when tokenPath is absent or has been removed; otherwise the current-realm or KV-store write error.
func (s *protocolFeeStore) RemoveAccrualPendingToken(_ int, rlm realm, tokenPath string) error {
	if !rlm.IsCurrent() {
		return errors.New(errSpoofedRealm)
	}

	accrualPendingTokens := s.getAccrualPendingTokenTree()
	if _, removed := accrualPendingTokens.Remove(tokenPath); !removed {
		return nil
	}

	return s.kvStore.Set(0, rlm, StoreKeyAccrualPendingTokens.String(), accrualPendingTokens)
}

func collectTreeKeys(tree *bptree.BPTree) []string {
	keys := make([]string, 0, tree.Size())
	tree.Iterate("", "", func(key string, _ any) bool {
		keys = append(keys, key)
		return false
	})

	return keys
}

func encodeEpochKey(epoch int64) string {
	if epoch < 0 {
		panic(ufmt.Sprintf("negative epoch not supported: %d", epoch))
	}

	return utils.EncodeUint64(uint64(epoch))
}

func decodeEpochKey(key string) int64 {
	return gnsmath.SafeUint64ToInt64(utils.DecodeUint64(key))
}

// NewProtocolFeeStore creates a protocol-fee store backed by the provided KV store.
// This function is used by the upgrade system to create storage instances for each implementation.
//
// Parameters:
//   - kvStore: Domain KV store used to persist protocol-fee state.
//
// Returns:
//   - protocolFeeStore: An IProtocolFeeStore implementation backed by kvStore.
func NewProtocolFeeStore(kvStore store.KVStore) IProtocolFeeStore {
	return &protocolFeeStore{
		kvStore: kvStore,
	}
}

package protocol_fee

import bptree "gno.land/p/nt/bptree/v0"

type IProtocolFee interface {
	IProtocolFeeManager
	IProtocolFeeGetter
	Render(path string) string
}

type IProtocolFeeManager interface {
	// Mutating methods take `_ int, rlm realm` so a leading integer discriminator
	// (callers pass 0) and the current protocol_fee realm context are threaded
	// from proxy entry points down to cross-realm token transfers and store writes
	// performed inside each implementation. The discriminator is explicit at every
	// call site, making the realm threading visible to readers.
	// DistributeProtocolFee distributes all reserved protocol fees to DevOps and
	// GovStaker according to the configured allocation percentages.
	//
	// Parameters:
	//   - _: cross-call discriminator; callers pass 0
	//   - rlm: propagated protocol_fee realm context; implementation validates it as current
	DistributeProtocolFee(_ int, rlm realm)

	// DistributeProtocolFeeByTokenPath distributes the reserved fee for one token path.
	//
	// Parameters:
	//   - _: cross-call discriminator; callers pass 0
	//   - rlm: propagated protocol_fee realm context; implementation validates it as current
	//   - tokenPath: token contract path whose reserved fee should be distributed
	DistributeProtocolFeeByTokenPath(_ int, rlm realm, tokenPath string)

	// SetDevOpsPct updates the DevOps share; the GovStaker share becomes 10000 minus pct.
	//
	// Parameters:
	//   - _: cross-call discriminator; callers pass 0
	//   - rlm: propagated protocol_fee realm context; implementation validates it as current
	//   - pct: DevOps allocation in basis-point units, from 0 through 10000 inclusive
	SetDevOpsPct(_ int, rlm realm, pct int64)

	// SetGovStakerPct updates the GovStaker share; the DevOps share becomes 10000 minus pct.
	//
	// Parameters:
	//   - _: cross-call discriminator; callers pass 0
	//   - rlm: propagated protocol_fee realm context; implementation validates it as current
	//   - pct: GovStaker allocation in basis-point units, from 0 through 10000 inclusive
	SetGovStakerPct(_ int, rlm realm, pct int64)

	// AddToProtocolFee records and pulls an approved fee from an authorized protocol caller.
	//
	// Parameters:
	//   - _: cross-call discriminator; callers pass 0
	//   - rlm: propagated protocol_fee realm context; implementation rejects a non-current value
	//   - tokenPath: token contract path from which the approved fee is pulled
	//   - amount: non-negative fee amount in token base units; zero is a successful no-op
	//
	// Returns:
	//   - err: nil after accounting and transfer succeed; an error when realm validation, halt checks, or storage/transfer operations fail
	AddToProtocolFee(_ int, rlm realm, tokenPath string, amount int64) error

	// AdvanceAccrualEpoch closes the current epoch and selects the next epoch for new fees.
	//
	// Parameters:
	//   - _: cross-call discriminator; callers pass 0
	//   - rlm: propagated protocol_fee realm context; implementation validates it as current
	//
	// Returns:
	//   - epoch: newly stored non-negative accrual epoch
	AdvanceAccrualEpoch(_ int, rlm realm) int64

	// ConsumeAccrualBuckets removes pending buckets for one token in epoch order.
	//
	// Parameters:
	//   - _: cross-call discriminator; callers pass 0
	//   - rlm: propagated protocol_fee realm context; implementation validates it as current
	//   - tokenPath: token contract path whose pending GovStaker buckets are consumed
	//   - limit: maximum number of oldest buckets; zero or negative consumes all pending buckets
	//
	// Returns:
	//   - epochs: consumed epoch numbers in ascending order
	//   - amounts: fee amounts corresponding positionally to epochs, in token base units
	ConsumeAccrualBuckets(_ int, rlm realm, tokenPath string, limit int) ([]int64, []int64)
}

type IProtocolFeeGetter interface {
	// GetDevOpsPct returns the configured DevOps allocation.
	//
	// Returns:
	//   - pct: DevOps fee allocation in basis-point units, from 0 through 10000
	GetDevOpsPct() int64

	// GetGovStakerPct returns the configured GovStaker allocation.
	//
	// Returns:
	//   - pct: GovStaker fee allocation in basis-point units, from 0 through 10000
	GetGovStakerPct() int64

	// GetReservedTokens returns token paths whose collected fees await distribution.
	//
	// Returns:
	//   - tokenPaths: token contract paths in the reserved-token index
	GetReservedTokens() []string

	// GetAccuTransfersToGovStaker returns cumulative allocations assigned to GovStaker.
	//
	// Returns:
	//   - transfers: map from token contract path to cumulative allocated amount in base units
	GetAccuTransfersToGovStaker() map[string]int64

	// GetAccuTransfersToDevOps returns cumulative allocations assigned to DevOps.
	//
	// Returns:
	//   - transfers: map from token contract path to cumulative allocated amount in base units
	GetAccuTransfersToDevOps() map[string]int64

	// GetAccuTransferToGovStakerByTokenPath returns the GovStaker allocation for one token.
	//
	// Parameters:
	//   - path: token contract path whose cumulative GovStaker allocation is queried
	//
	// Returns:
	//   - amount: cumulative GovStaker allocation for path in token base units, or zero if absent
	GetAccuTransferToGovStakerByTokenPath(path string) int64

	// GetAccuTransferToDevOpsByTokenPath returns the DevOps allocation for one token.
	//
	// Parameters:
	//   - path: token contract path whose cumulative DevOps allocation is queried
	//
	// Returns:
	//   - amount: cumulative DevOps allocation for path in token base units, or zero if absent
	GetAccuTransferToDevOpsByTokenPath(path string) int64

	// GetActualDistributedToGovStaker returns cumulative amounts transferred to GovStaker.
	//
	// Returns:
	//   - transfers: map from token contract path to cumulative amount actually transferred in base units
	GetActualDistributedToGovStaker() map[string]int64

	// GetActualDistributedToDevOps returns cumulative amounts transferred to DevOps.
	//
	// Returns:
	//   - transfers: map from token contract path to cumulative amount actually transferred in base units
	GetActualDistributedToDevOps() map[string]int64

	// GetActualDistributedToGovStakerByTokenPath returns the completed GovStaker transfer for one token.
	//
	// Parameters:
	//   - path: token contract path whose completed GovStaker transfer is queried
	//
	// Returns:
	//   - amount: cumulative GovStaker amount actually transferred for path in base units, or zero if absent
	GetActualDistributedToGovStakerByTokenPath(path string) int64

	// GetActualDistributedToDevOpsByTokenPath returns the completed DevOps transfer for one token.
	//
	// Parameters:
	//   - path: token contract path whose completed DevOps transfer is queried
	//
	// Returns:
	//   - amount: cumulative DevOps amount actually transferred for path in base units, or zero if absent
	GetActualDistributedToDevOpsByTokenPath(path string) int64

	// GetAccrualEpoch returns the epoch assigned to newly collected GovStaker fees.
	//
	// Returns:
	//   - epoch: current non-negative accrual epoch
	GetAccrualEpoch() int64

	// GetAccrualPendingTokens returns token paths that still have pending accrual buckets.
	//
	// Returns:
	//   - tokenPaths: token contract paths with at least one pending GovStaker accrual bucket
	GetAccrualPendingTokens() []string

	// GetAccrualBuckets reads pending token buckets without removing them.
	//
	// Parameters:
	//   - tokenPath: token contract path whose GovStaker accrual buckets are queried
	//   - limit: maximum number of oldest buckets; zero or negative returns all pending buckets
	//
	// Returns:
	//   - epochs: selected accrual epoch numbers in ascending order
	//   - amounts: fee amounts corresponding positionally to epochs, in token base units
	GetAccrualBuckets(tokenPath string, limit int) ([]int64, []int64)
}

