	//
	// Parameters:
	//   - tokenPath: token contract path whose accrual buckets are queried
	//   - limit: maximum number of oldest buckets; zero or negative returns all pending buckets
	//
	// Returns:
	//   - epochs: selected accrual epoch numbers in ascending order
	//   - amounts: bucket amounts corresponding positionally to epochs, in token base units
	GetAccrualBuckets(tokenPath string, limit int) ([]int64, []int64)

	// AddAccrualBucket adds amount to one token's bucket for an accrual epoch.
	//
	// Parameters:
	//   - _: cross-call discriminator; callers pass 0
	//   - rlm: propagated protocol_fee realm context required for the authorized store write
	//   - tokenPath: token contract path whose accrual bucket is updated
	//   - epoch: accrual epoch receiving the fee amount
	//   - amount: fee amount in token base units to add to that epoch bucket
	//
	// Returns:
	//   - err: nil when the bucket is stored; an error for invalid realm context or KV-store failure
	AddAccrualBucket(_ int, rlm realm, tokenPath string, epoch int64, amount int64) error

	// RemoveAccrualBuckets removes specified epoch buckets for one token.
	//
	// Parameters:
	//   - _: cross-call discriminator; callers pass 0
	//   - rlm: propagated protocol_fee realm context required for the authorized store write
	//   - tokenPath: token contract path whose buckets are removed
	//   - epochs: accrual epoch numbers to remove; an empty result removes no buckets
	//
	// Returns:
	//   - err: nil when removal succeeds; an error for invalid realm context or KV-store failure
	RemoveAccrualBuckets(_ int, rlm realm, tokenPath string, epochs []int64) error

	// HasAccrualPendingTokensStoreKey reports whether the pending-token index key exists.
	//
	// Returns:
	//   - exists: true when the index of tokens with pending buckets is present
	HasAccrualPendingTokensStoreKey() bool

	// InitializeAccrualPendingTokens creates the empty pending-token index.
	//
	// Parameters:
	//   - _: cross-call discriminator; callers pass 0
	//   - rlm: propagated protocol_fee realm context required for the authorized store write
	//
	// Returns:
	//   - err: nil when initialization succeeds; an error for invalid realm context or KV-store failure
	InitializeAccrualPendingTokens(_ int, rlm realm) error

	// GetAccrualPendingTokens returns token paths indexed as owning pending buckets.
	//
	// Returns:
	//   - tokenPaths: token contract paths present in the pending-token index
	GetAccrualPendingTokens() []string

	// AddAccrualPendingToken marks a token path as owning at least one pending bucket.
	//
	// Parameters:
	//   - _: cross-call discriminator; callers pass 0
	//   - rlm: propagated protocol_fee realm context required for the authorized store write
	//   - tokenPath: token contract path to add to the pending-token index
	//
	// Returns:
	//   - err: nil when added or already present; an error for invalid realm context or KV-store failure
	AddAccrualPendingToken(_ int, rlm realm, tokenPath string) error

	// RemoveAccrualPendingToken removes a token path from the pending-token index when present.
	//
	// Parameters:
	//   - _: cross-call discriminator; callers pass 0
	//   - rlm: propagated protocol_fee realm context required for the authorized store write
	//   - tokenPath: token contract path to remove after its pending buckets are consumed
	//
	// Returns:
	//   - err: nil when removed or already absent; an error for invalid realm context or KV-store failure
	RemoveAccrualPendingToken(_ int, rlm realm, tokenPath string) error
}

package protocol_fee

import (
	"gno.land/r/gnoswap/access/v1"
)

// RegisterInitializer registers a new protocol fee implementation version.
// This function is called by each version (v1, v2, etc.) during initialization
// to register their implementation with the proxy system.
//
// The initializer function creates a new instance of the implementation
// using the provided protocolFeeStore interface. It receives a realm value
// that resolves to the protocol_fee proxy realm — the only address with
// write permission on the shared KV store — so any per-version store
// bootstrapping performed inside the initializer passes the proxy's
// authorization check.
//
// Security: Only contracts within the domain path can register initializers.
// Each package path can only register once to prevent duplicate registrations.
//
// Parameters:
//   - cur: Current realm context; callers use cross(cur) when crossing into this realm.
//   - initializer: callback that receives the proxy realm context and protocol-fee store, initializes version-specific state, and returns the implementation instance
func RegisterInitializer(cur realm, initializer func(_ int, rlm realm, protocolFeeStore IProtocolFeeStore) IProtocolFee) {
	// `cur` captured here is the protocol_fee crossing frame. The wrapping
	// closure forwards it to the v1 initializer so any store writes the
	// initializer performs run under the proxy's identity rather than the
	// version package's, which would fail the kvStore ACL.
	initializerFunc := func(_ int, rlm realm, domainStore any) any {
		access.AssertIsRlmCurrent(0, rlm)

		currentProtocolFeeStore, ok := domainStore.(IProtocolFeeStore)
		if !ok {
			panic("domainStore is not an IProtocolFeeStore")
		}

		return initializer(0, rlm, currentProtocolFeeStore)
	}

	err := versionManager.RegisterInitializer(0, cur, initializerFunc)
	if err != nil {
		panic(err)
	}

	err = updateImplementation()
	if err != nil {
		panic(err)
	}
}

// UpgradeImpl switches the active protocol fee implementation to a different version.
// This function allows seamless upgrades from one version to another without
// data migration or downtime.
//
// Security: Only admin or governance can perform upgrades.
// The new implementation must have been previously registered via RegisterInitializer.
//
// Parameters:
//   - cur: Current realm context; callers use cross(cur) when crossing into this realm.
//   - packagePath: registered implementation package path to activate
func UpgradeImpl(cur realm, packagePath string) {
	// Ensure only admin or governance can perform upgrades
	prev := cur.Previous()
	access.AssertIsAdminOrGovernance(prev.Address())

	err := versionManager.ChangeImplementation(0, cur, packagePath)
	if err != nil {
		panic(err)
	}

	err = updateImplementation()
	if err != nil {
		panic(err)
	}
}

// GetImplementationPackagePath returns the package path of the currently active implementation.
//
// Returns:
//   - packagePath: package path of the active implementation
func GetImplementationPackagePath() string {
	return versionManager.GetCurrentPackagePath()
}

package emission

import (
	ufmt "gno.land/p/nt/ufmt/v0"
)

func assertDefaultInitialPoolExists() {
	if defaultInitialPoolChecker == nil {
		panic(makeErrorWithDetails(errInvalidEmissionStart, "default initial pool checker is not registered"))
	}

	if !defaultInitialPoolChecker(DefaultInitialPoolTierPath) {
		panic(makeErrorWithDetails(errInvalidEmissionStart, "default initial pool does not exist: "+DefaultInitialPoolTierPath))
	}
}

// validateDistributionTarget returns an error if the given distribution target is invalid.
func validateDistributionTarget(target int) error {
	validTargets := map[int]bool{
		LIQUIDITY_STAKER: false,
		DEVOPS:           false,
		COMMUNITY_POOL:   false,
		GOV_STAKER:       false,
	}

	if _, ok := validTargets[target]; !ok {
		return makeErrorWithDetails(
			errInvalidEmissionTarget,
			ufmt.Sprintf("invalid target(%d)", target),
		)
	}

	return nil
}

// assertValidDistributionTarget panics if the given distribution target is invalid.
// Kept for internal invariant checks.
func assertValidDistributionTarget(target int) {
	if err := validateDistributionTarget(target); err != nil {
		panic(err)
	}
}

// assertValidDistributionPct ensures the sum of all distribution percentages equals 10000 (100%).
// Panics if the sum does not equal exactly 10000 basis points.
func assertValidDistributionPct(liquidityStakerPct, devOpsPct, communityPoolPct, govStakerPct int64) {
	// Validate individual percentages are non-negative and reasonable
	percentages := []int64{liquidityStakerPct, devOpsPct, communityPoolPct, govStakerPct}
	for i, pct := range percentages {
		if pct < 0 {
			panic(makeErrorWithDetails(
				errInvalidEmissionPct,
				ufmt.Sprintf("percentage %d cannot be negative: %d", i+1, pct),
			))
		}

		if pct > 10000 {
			panic(makeErrorWithDetails(
				errInvalidEmissionPct,
				ufmt.Sprintf("percentage %d cannot exceed 100%%: %d", i+1, pct),
			))
		}
	}

	sum := liquidityStakerPct + devOpsPct + communityPoolPct + govStakerPct
	if sum != 10000 {
		panic(makeErrorWithDetails(
			errInvalidEmissionPct,
			ufmt.Sprintf("sum of percentages must be 10000, got %d", sum),
		))
	}
}

package emission

import (
	"chain"
	"time"

	ufmt "gno.land/p/nt/ufmt/v0"

	gnsmath "gno.land/p/gnoswap/gnsmath/v1"
	prbac "gno.land/p/gnoswap/rbac/v1"
	"gno.land/p/gnoswap/utils/v1"

	"gno.land/r/gnoswap/access/v1"
	"gno.land/r/gnoswap/gns"
	"gno.land/r/gnoswap/halt/v1"
)

const (
	_ int = iota
	LIQUIDITY_STAKER
	DEVOPS
	COMMUNITY_POOL
	GOV_STAKER
)

var (
	// Stores the percentage (in basis points) for each distribution target
	// 1 basis point = 0.01%
	// These percentages can be modified by admin or governance.
	distributionBpsPct map[int]int64

	distributedToStaker        int64 // can be cleared by staker contract
	distributedToDevOps        int64
	distributedToCommunityPool int64
	distributedToGovStaker     int64 // can be cleared by governance staker

	// Historical total distributions (never reset)
	accuDistributedToStaker        int64
	accuDistributedToDevOps        int64
	accuDistributedToCommunityPool int64
	accuDistributedToGovStaker     int64
)

// Initialize default distribution percentages:
// - Liquidity Stakers: 75%
// - DevOps: 20%
// - Community Pool: 5%
// - Governance Stakers: 0%
//
// ref: https://docs.gnoswap.io/gnoswap-token/emission
func init() {
	distributionBpsPct = map[int]int64{
		LIQUIDITY_STAKER: 7500,
		DEVOPS:           2000,
		COMMUNITY_POOL:   500,
		GOV_STAKER:       0,
	}
}

// ChangeDistributionPct changes distribution percentages for emission targets.
//
// This function redistributes how newly minted GNS tokens are allocated across
// protocol components. Before applying new ratios, it distributes any accumulated
// emissions using the current ratios, ensuring emissions are distributed according
// to the ratios in effect when they were generated. This prevents retroactive
// application of new ratios to past emissions.
//
// Parameters:
//   - cur: Current realm context; callers use cross(cur) when crossing into this realm.
//   - liquidityStakerPct: percentage for liquidity stakers in basis points (100 = 1%, 10000 = 100%).
//   - devOpsPct: percentage for DevOps in basis points (100 = 1%, 10000 = 100%).
//   - communityPoolPct: percentage for the community pool in basis points (100 = 1%, 10000 = 100%).
//   - govStakerPct: percentage for governance stakers in basis points (100 = 1%, 10000 = 100%).
//
// Requirements:
//   - Percentages must sum to exactly 10000 (100%).
//   - Each percentage must be between 0 and 10000 inclusive.
//
// Example:
//
//	ChangeDistributionPct(
//	  7000,  // 70% to liquidity stakers
//	  2000,  // 20% to devops
//	  1000,  // 10% to community pool
//	  0,     // 0% to governance stakers
//	)
//
// Only callable by admin or governance.
func ChangeDistributionPct(
	cur realm,
	liquidityStakerPct int64,
	devOpsPct int64,
	communityPoolPct int64,
	govStakerPct int64,
) {
	halt.AssertIsNotHaltedEmission()

	caller := cur.Previous().Address()
	access.AssertIsAdminOrGovernance(caller)

	assertValidDistributionPct(liquidityStakerPct, devOpsPct, communityPoolPct, govStakerPct)

	// Distribute accumulated emissions with current ratios before changing ratios.
	// This prevents retroactive application of new ratios to emissions that occurred
	// under previous ratio configurations.
	MintAndDistributeGns(cur)

	currentTimestamp := time.Now().Unix()
	stakerRewardPerSecond := GetEmissionAmountPerSecondBy(currentTimestamp, liquidityStakerPct)
	govStakerRewardPerSecond := GetEmissionAmountPerSecondBy(currentTimestamp, govStakerPct)

	if onDistributionPctChangeCallback != nil {
		onDistributionPctChangeCallback(cross(cur), stakerRewardPerSecond)
	}

	changeDistributionPcts(liquidityStakerPct, devOpsPct, communityPoolPct, govStakerPct)

	previousRealm := cur.Previous()
	chain.Emit(
		"ChangeDistributionPct",
		"prevAddr", previousRealm.Address().String(),
		"prevRealm", previousRealm.PkgPath(),
		"liquidityStakerPct", utils.FormatInt(liquidityStakerPct),
		"devOpsPct", utils.FormatInt(devOpsPct),
		"communityPoolPct", utils.FormatInt(communityPoolPct),
		"govStakerPct", utils.FormatInt(govStakerPct),
		"stakerRewardPerSecond", utils.FormatInt(stakerRewardPerSecond),
		"govStakerRewardPerSecond", utils.FormatInt(govStakerRewardPerSecond),
	)
}

// changeDistributionPcts updates the distribution percentages for all targets.
func changeDistributionPcts(liquidityStakerPct, devOpsPct, communityPoolPct, govStakerPct int64) {
	setDistributionBpsPct(LIQUIDITY_STAKER, liquidityStakerPct)
	setDistributionBpsPct(DEVOPS, devOpsPct)
	setDistributionBpsPct(COMMUNITY_POOL, communityPoolPct)
	setDistributionBpsPct(GOV_STAKER, govStakerPct)
}

func calculateDistributableAmounts(amount int64) (map[int]int64, int64) {
	distributable := make(map[int]int64, 0)
	totalSent := int64(0)

	for target, pct := range distributionBpsPct {
		distAmount := calculateAmount(amount, pct)
		if distAmount == 0 {
			continue
		}

		distributable[target] = distAmount
		totalSent = gnsmath.SafeAddInt64(totalSent, distAmount)
	}

	leftAmount := gnsmath.SafeSubInt64(amount, totalSent)
	return distributable, leftAmount
}

// calculateAmount converts basis points to actual token amount.
func calculateAmount(amount, bptPct int64) int64 {
	if amount < 0 || bptPct < 0 || bptPct > 10000 {
		panic("invalid amount or bptPct")
	}

	// More precise overflow prevention
	const maxInt64 = 9223372036854775807
	if amount > maxInt64/10000 {
		panic("amount too large, would cause overflow")
	}

	// Additional safety check for zero division
	if bptPct == 0 {
		return 0
	}

	return amount * bptPct / 10000
}

func applyDistribution(targets map[int]int64) (map[address]int64, error) {
	amountByAddress := make(map[address]int64, 0)

	for target, amount := range targets {
		var addr address

		switch target {
		case LIQUIDITY_STAKER:
			distributedToStaker = gnsmath.SafeAddInt64(distributedToStaker, amount)
			accuDistributedToStaker = gnsmath.SafeAddInt64(accuDistributedToStaker, amount)
			addr = access.MustGetAddress(prbac.ROLE_STAKER.String())

		case DEVOPS:
			distributedToDevOps = gnsmath.SafeAddInt64(distributedToDevOps, amount)
			accuDistributedToDevOps = gnsmath.SafeAddInt64(accuDistributedToDevOps, amount)
			addr = access.MustGetAddress(prbac.ROLE_DEVOPS.String())

		case COMMUNITY_POOL:
			distributedToCommunityPool = gnsmath.SafeAddInt64(distributedToCommunityPool, amount)
			accuDistributedToCommunityPool = gnsmath.SafeAddInt64(accuDistributedToCommunityPool, amount)
			addr = access.MustGetAddress(prbac.ROLE_COMMUNITY_POOL.String())

		case GOV_STAKER:
			distributedToGovStaker = gnsmath.SafeAddInt64(distributedToGovStaker, amount)
			accuDistributedToGovStaker = gnsmath.SafeAddInt64(accuDistributedToGovStaker, amount)
			addr = access.MustGetAddress(prbac.ROLE_GOV_STAKER.String())

		default:
			return nil, makeErrorWithDetails(
				errInvalidEmissionTarget,
				ufmt.Sprintf("invalid target(%d)", target),
			)
		}

		amountByAddress[addr] = gnsmath.SafeAddInt64(amountByAddress[addr], amount)
	}

	return amountByAddress, nil
}

func transferToTarget(_ int, rlm realm, targets map[address]int64) error {
	for address, amount := range targets {
		gns.Transfer(cross(rlm), address, amount)
	}

	return nil
}

// GetDistributionBpsPct returns the configured distribution percentage in basis points for a target.
//
// Parameters:
//   - target: distribution target constant whose configured share is queried.
//
// Returns:
//   - pct: configured target share in basis points (100 = 1%, 10000 = 100%).
//   - error: nil when the target exists in the initialized map; otherwise an invalid-target error.
func GetDistributionBpsPct(target int) (int64, error) {
	if err := validateDistributionTarget(target); err != nil {
		return 0, err
	}

	if distributionBpsPct == nil {
		return 0, makeErrorWithDetails(
			errInvalidEmissionTarget,
			ufmt.Sprintf("distributionBpsPct is nil"),
		)
	}

	pct, exist := distributionBpsPct[target]
	if !exist {
		return 0, makeErrorWithDetails(
			errInvalidEmissionTarget,
			ufmt.Sprintf("invalid target(%d)", target),
		)
	}

	return pct, nil
}

// GetDistributedToStaker returns the pending GNS amount allocated to liquidity stakers.
//
// Returns:
//   - amount: pending liquidity-staker allocation in GNS base units since the last clear.
func GetDistributedToStaker() int64 {
	return distributedToStaker
}

// GetDistributedToDevOps returns the GNS amount currently accumulated for DevOps.
//
// Returns:
//   - amount: accumulated DevOps allocation in GNS base units.
func GetDistributedToDevOps() int64 {
	return distributedToDevOps
}

// GetDistributedToCommunityPool returns the GNS amount currently accumulated for the community pool.
//
// Returns:
//   - amount: accumulated community-pool allocation in GNS base units.
func GetDistributedToCommunityPool() int64 {
	return distributedToCommunityPool
}

// GetDistributedToGovStaker returns the pending GNS amount allocated to governance stakers.
//
// Returns:
//   - amount: pending governance-staker allocation in GNS base units since the last clear.
func GetDistributedToGovStaker() int64 {
	return distributedToGovStaker
}

// AccumulateDistributedInfo returns the current pending allocation for every distribution target.
//
// Returns:
//   - toStaker: pending GNS allocation for liquidity stakers, in token base units.
//   - toDevOps: accumulated GNS allocation for DevOps, in token base units.
//   - toCommunityPool: accumulated GNS allocation for the community pool, in token base units.
//   - toGovStaker: pending GNS allocation for governance stakers, in token base units.
func AccumulateDistributedInfo() (toStaker, toDevOps, toCommunityPool, toGovStaker int64) {
	toStaker = GetDistributedToStaker()
	toDevOps = GetDistributedToDevOps()
	toCommunityPool = GetDistributedToCommunityPool()
	toGovStaker = GetDistributedToGovStaker()
	return
}

// GetAccuDistributedToStaker returns the total historical GNS amount allocated to liquidity stakers.
//
// Returns:
//   - amount: cumulative liquidity-staker allocation in GNS base units; this value is not cleared.
func GetAccuDistributedToStaker() int64 {
	return accuDistributedToStaker
}

// GetAccuDistributedToDevOps returns the total historical GNS amount allocated to DevOps.
//
// Returns:
//   - amount: cumulative DevOps allocation in GNS base units; this value is not cleared.
func GetAccuDistributedToDevOps() int64 {
	return accuDistributedToDevOps
}

// GetAccuDistributedToCommunityPool returns the total historical GNS amount allocated to the community pool.
//
// Returns:
//   - amount: cumulative community-pool allocation in GNS base units; this value is not cleared.
func GetAccuDistributedToCommunityPool() int64 {
	return accuDistributedToCommunityPool
}

// GetAccuDistributedToGovStaker returns the total historical GNS amount allocated to governance stakers.
//
// Returns:
//   - amount: cumulative governance-staker allocation in GNS base units; this value is not cleared.
func GetAccuDistributedToGovStaker() int64 {
	return accuDistributedToGovStaker
}

// GetEmissionAmountPerSecondBy returns the GNS emission rate per second for a timestamp and target share.
//
// Parameters:
//   - timestamp: Unix timestamp at which the base emission rate is queried.
//   - distributionPct: target share in basis points, from 0 through 10000 inclusive.
//
// Returns:
//   - amountPerSecond: target's GNS emission rate in token base units per second, or zero outside the schedule.
func GetEmissionAmountPerSecondBy(timestamp, distributionPct int64) int64 {
	return calculateAmount(gns.GetEmissionAmountPerSecondByTimestamp(timestamp), distributionPct)
}

// GetStakerEmissionAmountPerSecond returns the current GNS emission rate allocated to liquidity stakers.
//
// Returns:
//   - amountPerSecond: current liquidity-staker emission rate in GNS base units per second.
//   - error: nil when the liquidity-staker distribution share is available; otherwise the target lookup error.
func GetStakerEmissionAmountPerSecond() (int64, error) {
	currentTimestamp := time.Now().Unix()
	pct, err := GetDistributionBpsPct(LIQUIDITY_STAKER)
	if err != nil {
		return 0, err
	}
	return GetEmissionAmountPerSecondBy(currentTimestamp, pct), nil
}

// GetStakerEmissionAmountPerSecondInRange returns liquidity-staker emission-rate change points in a time range.
//
// Parameters:
//   - start: inclusive start Unix timestamp for the range.
//   - end: inclusive end Unix timestamp for the range.
//
// Returns:
//   - timestamps: ordered timestamps in the range where the base emission rate changes.
//   - amountsPerSecond: liquidity-staker GNS rates corresponding to timestamps, in token base units per second.
//   - error: nil when the liquidity-staker distribution share is available; otherwise the target lookup error.
func GetStakerEmissionAmountPerSecondInRange(start, end int64) ([]int64, []int64, error) {
	gnsHalvingBlocks, gnsHalvingEmissions := gns.GetEmissionAmountPerSecondInRange(start, end)
	halvingBlocks := make([]int64, len(gnsHalvingBlocks))
	halvingEmissions := make([]int64, len(gnsHalvingEmissions))

	pct, err := GetDistributionBpsPct(LIQUIDITY_STAKER)
	if err != nil {
		return nil, nil, err
	}

	for i := range halvingBlocks {
		halvingBlocks[i] = gnsHalvingBlocks[i]
		// Applying staker ratio for past halving blocks
		halvingEmissions[i] = calculateAmount(gnsHalvingEmissions[i], pct)
	}

	return halvingBlocks, halvingEmissions, nil
}

// ClearDistributedToStaker resets the pending distribution amount for liquidity stakers.
//
// Parameters:
//   - cur: Current realm context; callers use cross(cur) when crossing into this realm.
//
// Only callable by staker contract.
func ClearDistributedToStaker(cur realm) {
	caller := cur.Previous().Address()
	access.AssertIsStaker(caller)

	distributedToStaker = 0
}

// ClearDistributedToGovStaker resets the pending distribution amount for governance stakers.
//
// Parameters:
//   - cur: Current realm context; callers use cross(cur) when crossing into this realm.
//
// Only callable by governance staker contract.
func ClearDistributedToGovStaker(cur realm) {
	caller := cur.Previous().Address()
	access.AssertIsGovStaker(caller)
	distributedToGovStaker = 0
}

// setDistributionBpsPct changes percentage of each target for how much GNS it will get by emission.
// Creates new map if nil.
func setDistributionBpsPct(target int, pct int64) {
	if distributionBpsPct == nil {
		distributionBpsPct = make(map[int]int64)
	}

	distributionBpsPct[target] = pct
}

// targetToStr converts target constant to string representation.
func targetToStr(target int) string {
	switch target {
	case LIQUIDITY_STAKER:
		return "LIQUIDITY_STAKER"
	case DEVOPS:
		return "DEVOPS"
	case COMMUNITY_POOL:
		return "COMMUNITY_POOL"
	case GOV_STAKER:
		return "GOV_STAKER"
	default:
		return "UNKNOWN"
	}
}

// Package emission manages GNS token emission and distribution for GnoSwap.
//
// The emission system controls creation and distribution of new GNS tokens
// with a deflationary model featuring periodic halvings over 12 years.
//
// Emission Schedule:
//   - Year 1-2:  100% emission rate (225,000,000 GNS/year)
//   - Year 3-4:   50% emission rate (112,500,000 GNS/year)
//   - Year 5-6:   25% emission rate  (56,250,000 GNS/year)
//   - Year 7-8:  12.5% emission rate (28,125,000 GNS/year)
//   - Year 9-12:  6.25% emission rate (14,062,500 GNS/year)
//
// Distribution Targets (configurable via admin or governance):
//   - LIQUIDITY_STAKER: Rewards for LP providers (default 75%)
//   - DEVOPS: Development and operations fund (default 20%)
//   - COMMUNITY_POOL: Community treasury (default 5%)
//   - GOV_STAKER: GNS staking rewards (default 0%)
//
// Key Functions:
//   - MintAndDistributeGns: Mints and distributes GNS per emission schedule;
//     returns false only when emission is halted.
//   - SetDistributionStartTime: Sets or reschedules the start timestamp while
//     it is still in the future; the timestamp is immutable once active.
//   - ChangeDistributionPct: Updates distribution percentages
//   - ClearDistributedToStaker/GovStaker: Resets pending distribution amounts
package emission

package emission

import (
	"chain"
	"chain/runtime"
	"math"
	"time"

	gnsmath "gno.land/p/gnoswap/gnsmath/v1"
	"gno.land/p/gnoswap/utils/v1"

	"gno.land/r/gnoswap/access/v1"
	"gno.land/r/gnoswap/gns"
	"gno.land/r/gnoswap/halt/v1"
)

const (
	totalDistributionDuration = 12 * 365 * 24 * 60 * 60 // 12 years

	// DefaultInitialPoolTierPath is the canonical default initial pool that must
	// exist before emission distribution can start. The pool contract registers a
	// checker (SetDefaultInitialPoolChecker) that verifies this pool exists.
	DefaultInitialPoolTierPath = "gno.land/r/gnoland/wugnot.wugnot:gno.land/r/gnoswap/gns.GNS:3000"
)

var (
	// leftGNSAmount tracks undistributed GNS tokens from previous distributions
	leftGNSAmount int64

	// lastExecutedTimestamp stores the last timestamp when distribution was executed
	lastExecutedTimestamp int64

	// emissionAddr is the address of the emission realm
	emissionAddr address

	// distributionStartTimestamp is the timestamp from which emission distribution starts
	// Default is 0, meaning distribution is not started until explicitly set
	distributionStartTimestamp int64

	// onDistributionPctChangeCallback is called when distribution percentages change
	// This allows external contracts (like staker) to update their caches
	onDistributionPctChangeCallback func(cur realm, emissionAmountPerSecond int64)

	// defaultInitialPoolChecker verifies the canonical default initial pool exists.
	// It is registered by pool/v1 at initialization time so that emission does not
	// need a compile-time dependency on the pool realm.
	defaultInitialPoolChecker func(poolPath string) bool
)

func init(cur realm) {
	emissionAddr = cur.Address()
}

// setLeftGNSAmount updates the undistributed GNS token amount
func setLeftGNSAmount(amount int64) {
	if amount < 0 {
		panic("left GNS amount cannot be negative")
	}

	leftGNSAmount = amount
}

// setLastExecutedTimestamp updates the timestamp of the last emission distribution execution.
func setLastExecutedTimestamp(timestamp int64) {
	if timestamp < 0 {
		panic("last executed timestamp cannot be negative")
	}

	lastExecutedTimestamp = timestamp
}

// MintAndDistributeGns mints and distributes GNS tokens according to the emission schedule.
//
// This function is called automatically by protocol contracts during user interactions
// to trigger periodic GNS emission. It mints new tokens based on elapsed time since
// last distribution and distributes them to predefined targets (staker, devops, etc.).
//
// Parameters:
//   - cur: Current realm context; callers use cross(cur) when crossing into this realm.
//
// Returns:
//   - distributedAmount: total amount of GNS distributed in this call
//   - success: false only when emission is halted; true when processing completes, even if no tokens are distributed
//
// Note: Distribution only occurs if start timestamp is set and reached.
// Any undistributed tokens from previous calls are carried forward.
func MintAndDistributeGns(cur realm) (int64, bool) {
	if halt.IsHaltedEmission() {
		return 0, false
	}

	currentHeight := runtime.ChainHeight()
	currentTimestamp := time.Now().Unix()

	// Check if distribution start timestamp is set and if current timestamp has reached it
	// If distributionStartTimestamp is 0 (default), skip distribution to prevent immediate start
	// If current timestamp is below start timestamp, skip distribution
	if distributionStartTimestamp == 0 || currentTimestamp < distributionStartTimestamp {
		return 0, true
	}

	// Skip if we've already minted tokens at this timestamp
	lastMintedTimestamp := gns.LastMintedTimestamp()
	if currentTimestamp <= lastMintedTimestamp {
		return 0, true
	}

	// Additional check to prevent re-entrancy
	if lastExecutedTimestamp >= currentTimestamp {
		// Skip if we've already processed this height in emission
		return 0, true
	}

	// Mint new tokens and add any leftover amounts from previous distribution
	mintedEmissionRewardAmount := gns.MintGns(cross(cur), emissionAddr)

	// Validate minted amount
	if mintedEmissionRewardAmount < 0 {
		panic("minted emission reward amount cannot be negative")
	}

	distributableAmount := mintedEmissionRewardAmount
	prevLeftAmount := GetLeftGNSAmount()

	if leftGNSAmount > 0 {
		// Check for overflow before addition
		if distributableAmount > math.MaxInt64-prevLeftAmount {
			panic("distributable amount would overflow")
		}

		distributableAmount += prevLeftAmount
		setLeftGNSAmount(0)
	}

	distributable, leftAmount := calculateDistributableAmounts(distributableAmount)
	totalDistAmount := gnsmath.SafeSubInt64(distributableAmount, leftAmount)
	if leftAmount > 0 {
		setLeftGNSAmount(leftAmount)
	}
	setLastExecutedTimestamp(currentTimestamp)

	amountByAddress, err := applyDistribution(distributable)
	if err != nil {
		panic(err)
	}

	if err := transferToTarget(0, cur, amountByAddress); err != nil {
		panic(err)
	}

	stakerPct, err := GetDistributionBpsPct(LIQUIDITY_STAKER)
	if err != nil {
		panic(err)
	}
	stakerRewardPerSecond := GetEmissionAmountPerSecondBy(currentTimestamp, stakerPct)

	govStakerPct, err := GetDistributionBpsPct(GOV_STAKER)
	if err != nil {
		panic(err)
	}
	govStakerRewardPerSecond := GetEmissionAmountPerSecondBy(currentTimestamp, govStakerPct)

	previousRealm := cur.Previous()
	chain.Emit(
		"MintAndDistributeGns",
		"prevAddr", previousRealm.Address().String(),
		"prevRealm", previousRealm.PkgPath(),
		"lastTimestamp", utils.FormatInt(lastExecutedTimestamp),
		"currentTimestamp", utils.FormatInt(currentTimestamp),
		"currentHeight", utils.FormatInt(currentHeight),
		"mintedAmount", utils.FormatInt(mintedEmissionRewardAmount),
		"prevLeftAmount", utils.FormatInt(prevLeftAmount),
		"distributedAmount", utils.FormatInt(totalDistAmount),
		"currentLeftAmount", utils.FormatInt(GetLeftGNSAmount()),
		"gnsTotalSupply", utils.FormatInt(gns.TotalSupply()),
		"stakerRewardPerSecond", utils.FormatInt(stakerRewardPerSecond),
		"govStakerRewardPerSecond", utils.FormatInt(govStakerRewardPerSecond),
	)

	return totalDistAmount, true
}

// SetDistributionStartTime sets the timestamp when emission distribution starts.
//
// This function controls when GNS emission begins. Before the configured
// timestamp is reached, an admin or governance caller may reschedule it. Once
// the timestamp is reached, the start time is immutable.
//
// Parameters:
//   - cur: Current realm context; callers use cross(cur) when crossing into this realm.
//   - startTimestamp: positive future Unix timestamp when emission should begin.
//
// Requirements:
//   - Must be called before distribution starts.
//   - Timestamp must be in the future and leave room for the 12-year schedule.
//
// Effects:
//   - Sets global distribution start time.
//   - Initializes GNS emission state if not already started.
//   - Emission begins automatically when timestamp is reached.
//
// Only callable by admin or governance.
func SetDistributionStartTime(cur realm, startTimestamp int64) {
	halt.AssertIsNotHaltedEmission()

	caller := cur.Previous().Address()
	access.AssertIsAdminOrGovernance(caller)
	assertDefaultInitialPoolExists()

	if startTimestamp <= 0 {
		panic("distribution start timestamp must be positive")
	}

	if startTimestamp > math.MaxInt64-totalDistributionDuration {
		panic("distribution end timestamp must be before max int64 timestamp")
	}

	currentTimestamp := time.Now().Unix()

	// Must be in the future.
	if startTimestamp <= currentTimestamp {
		panic("distribution start timestamp must be greater than current timestamp")
	}

	// Cannot change after distribution started.
	if distributionStartTimestamp != 0 && distributionStartTimestamp <= currentTimestamp {
		panic("distribution has already started, cannot change start timestamp")
	}

	prevStartTimestamp := distributionStartTimestamp

	if gns.MintedEmissionAmount() == 0 {
		currentHeight := runtime.ChainHeight()
		gns.InitEmissionState(cross(cur), currentHeight, startTimestamp)
	}

	distributionStartTimestamp = startTimestamp

	chain.Emit(
		"SetDistributionStartTime",
		"caller", caller.String(),
		"prevStartTimestamp", utils.FormatInt(prevStartTimestamp),
		"newStartTimestamp", utils.FormatInt(startTimestamp),
		"height", utils.FormatInt(runtime.ChainHeight()),
		"timestamp", utils.FormatInt(time.Now().Unix()),
	)
}

// SetOnDistributionPctChangeCallback registers the optional callback invoked when
// distribution percentages change. A nil callback clears the registration.
// This allows external contracts (like staker) to update their internal caches
// when governance or admin changes emission rates.
//
// Parameters:
//   - cur: Current realm context; callers use cross(cur) when crossing into this realm.
//   - callback: nil to clear the callback, or a function receiving its callback
//     realm context and the current staker GNS emission rate per second; a nonnil
//     callback is invoked immediately after registration.
func SetOnDistributionPctChangeCallback(cur realm, callback func(cur realm, emissionAmountPerSecond int64)) {
	caller := cur.Previous().Address()
	access.AssertIsStaker(caller)

	if callback == nil {
		onDistributionPctChangeCallback = nil
		return
	}

	emissionAmountPerSecond, err := GetStakerEmissionAmountPerSecond()
	if err != nil {
		panic(err)
	}

	onDistributionPctChangeCallback = callback
	onDistributionPctChangeCallback(cross(cur), emissionAmountPerSecond)
}

// SetDefaultInitialPoolChecker registers the callback that verifies the
// canonical default initial pool exists before emission starts.
//
// The checker receives the pool path as a parameter so emission owns the
// canonical path policy (DefaultInitialPoolTierPath) while pool supplies only
// the generic "does this pool exist" capability.
//
// Parameters:
//   - cur: Current realm context; callers use cross(cur) when crossing into this realm.
//   - checker: nonnil function returning true when the supplied pool path exists;
//     it is called with DefaultInitialPoolTierPath and nil causes a panic.
//
// Only callable by the pool contract.
func SetDefaultInitialPoolChecker(cur realm, checker func(poolPath string) bool) {
	caller := cur.Previous().Address()
	access.AssertIsPool(caller)

	if checker == nil {
		panic(makeErrorWithDetails(errInvalidEmissionStart, "default initial pool checker cannot be nil"))
	}

	defaultInitialPoolChecker = checker
}

