package position

import (
	"gno.land/r/gnoswap/access/v1"
)

// RegisterInitializer registers a new position implementation version.
// This function is called by each version (v1, v2, etc.) during initialization
// to register their implementation with the proxy system.
//
// The initializer function creates a new instance of the implementation
// using the provided positionStore interface.
//
// Parameters:
//   - cur: current realm context; callers use cross(cur) when crossing into this realm
//   - initializer: callback that receives the implementation realm context and position store, then returns that version's IPosition implementation
//
// Security: Only contracts within the domain path can register initializers.
// Each package path can only register once to prevent duplicate registrations.
func RegisterInitializer(cur realm, initializer func(_ int, rlm realm, positionStore IPositionStore) IPosition) {
	initializerFunc := func(_ int, rlm realm, domainStore any) any {
		access.AssertIsRlmCurrent(0, rlm)

		currentPositionStore, ok := domainStore.(IPositionStore)
		if !ok {
			panic("domainStore is not an IPositionStore")
		}

		return initializer(0, rlm, currentPositionStore)
	}

	err := versionManager.RegisterInitializer(0, cur, initializerFunc)
	if err != nil {
		panic(err)
	}

	err = updateImplementation()
	if err != nil {
		panic(err)
	}
}

// UpgradeImpl switches the active position implementation to a different version.
// This function allows seamless upgrades from one version to another without
// data migration or downtime.
//
// Parameters:
//   - cur: current realm context; callers use cross(cur) when crossing into this realm
//   - packagePath: fully qualified package path of a previously registered replacement implementation
//
// Security: Only admin or governance can perform upgrades.
// The new implementation must have been previously registered via RegisterInitializer.
func UpgradeImpl(cur realm, packagePath string) {
	// Ensure only admin or governance can perform upgrades
	caller := cur.Previous().Address()
	access.AssertIsAdminOrGovernance(caller)

	err := versionManager.ChangeImplementation(0, cur, packagePath)
	if err != nil {
		panic(err)
	}

	err = updateImplementation()
	if err != nil {
		panic(err)
	}
}

// GetImplementationPackagePath returns the package path of the currently active implementation.
//
// Returns:
//   - packagePath: package path of the active implementation
func GetImplementationPackagePath() string {
	return versionManager.GetCurrentPackagePath()
}

// Package router provides swap routing and execution across GnoSwap liquidity pools.
//
// Router domain proxy for single-hop and multi-hop exact-in, exact-out, and
// dry-route operations.
//
// Live exact-in and exact-out calls validate a deadline and the corresponding
// amount limit (minimum output or maximum input). DrySwapRoute is a read-only
// quote path with no deadline or token transfer.
//
// The router fee is charged on output tokens. It defaults to 15 bps (0.15%)
// and is configurable by admin/governance from 0 through 1000 bps (0–10%);
// the current rate is fixed for each individual execution.
//
// The router acts as a proxy to version-specific implementations,
// currently routing to v1 for all swap operations.
package router

package router

// cloneStringInt64Map returns a copy so callers cannot reach the stored map.
func cloneStringInt64Map(src map[string]int64) map[string]int64 {
	if src == nil {
		return nil
	}

	cloned := make(map[string]int64, len(src))
	for k, v := range src {
		cloned[k] = v
	}

	return cloned
}

package router

// ExactInSwapRoute executes a multi-hop swap for an exact input amount.
//
// Parameters:
//   - cur: current realm context; callers use cross(cur) when crossing into this realm
//   - inputToken: input token path
//   - outputToken: output token path
//   - amountIn: exact input amount
//   - routeArr: encoded route
//   - quoteArr: encoded quotes
//   - amountOutMin: minimum output amount
//   - deadline: transaction deadline
//   - referrer: referral address
//
// Returns:
//   - amountIn: input amount consumed
//   - amountOut: net output amount delivered after the router fee
//
// Halt check: reverts while the Router halt scope is active.
func ExactInSwapRoute(cur realm, inputToken string, outputToken string, amountIn string, routeArr string, quoteArr string, amountOutMin string, deadline int64, referrer string) (string, string) {
	return getImplementation().ExactInSwapRoute(0, cur, inputToken, outputToken, amountIn, routeArr, quoteArr, amountOutMin, deadline, referrer)
}

// ExactInSingleSwapRoute executes a single-hop swap for an exact input amount.
//
// Parameters:
//   - cur: current realm context; callers use cross(cur) when crossing into this realm
//   - inputToken: input token path
//   - outputToken: output token path
//   - amountIn: exact input amount
//   - routeArr: encoded route
//   - amountOutMin: minimum output amount
//   - sqrtPriceLimitX96: Q64.96 price limit
//   - deadline: transaction deadline
//   - referrer: referral address
//
// Returns:
//   - amountIn: input amount consumed (a nonzero price limit may stop early)
//   - amountOut: net output amount delivered after the router fee
//
// Halt check: reverts while the Router halt scope is active.
func ExactInSingleSwapRoute(cur realm, inputToken string, outputToken string, amountIn string, routeArr string, amountOutMin string, sqrtPriceLimitX96 string, deadline int64, referrer string) (string, string) {
	return getImplementation().ExactInSingleSwapRoute(0, cur, inputToken, outputToken, amountIn, routeArr, amountOutMin, sqrtPriceLimitX96, deadline, referrer)
}

// ExactOutSwapRoute executes a multi-hop swap for a requested post-fee output
// target.
//
// Parameters:
//   - cur: current realm context; callers use cross(cur) when crossing into this realm
//   - inputToken: input token path
//   - outputToken: output token path
//   - amountOut: requested net output target
//   - routeArr: encoded route
//   - quoteArr: encoded quotes
//   - amountInMax: maximum input amount
