//
// This struct contains the necessary data and methods to manage and distribute
// rewards for a specific project.
//
// Fields:
// - id (string): The unique identifier for the project, formatted as "{tokenPath}:{createdHeight}".
// - name (string): The name of the project.
// - tokenPath (string): The path of the token associated with the project.
// - depositAmount (int64): The total amount of tokens deposited for the project.
// - recipient (address): The address to receive the project's rewards.
// - conditions (map[string]*ProjectCondition): A map of token paths to their associated conditions.
// - tiers (map[int64]*ProjectTier): A map of tier durations to their associated tiers.
// - tiersRatios (map[int64]int64): A map of tier durations to their associated ratios.
// - createdHeight (int64): The block height at which the project was created.
// - createdAt (int64): The Unix timestamp at which the project was created.
type Project struct {
	id            string // 'tokenPath:createdHeight'
	name          string
	tokenPath     string
	depositAmount int64
	recipient     address                      // string
	conditions    map[string]*ProjectCondition // tokenPath -> Condition
	tiers         map[int64]*ProjectTier
	tiersRatios   map[int64]int64
	createdHeight int64
	createdAt     int64
}

// ID returns the project identifier in "{tokenPath}:{createdHeight}" form.
//
// Returns:
//   - id: unique identifier assigned to this project.
func (p *Project) ID() string {
	return p.id
}

// SetID replaces the project's identifier.
//
// Parameters:
//   - id: project identifier to store, normally in "{tokenPath}:{createdHeight}" form.
func (p *Project) SetID(id string) {
	p.id = id
}

// Name returns the project's human-readable name.
//
// Returns:
//   - name: stored project name.
func (p *Project) Name() string {
	return p.name
}

// SetName replaces the project's human-readable name.
//
// Parameters:
//   - name: project name to store.
func (p *Project) SetName(name string) {
	p.name = name
}

// TokenPath returns the token path whose tokens are distributed as project rewards.
//
// Returns:
//   - tokenPath: configured project reward-token path.
func (p *Project) TokenPath() string {
	return p.tokenPath
}

// SetTokenPath replaces the project's reward-token path.
//
// Parameters:
//   - tokenPath: token path to store as the project's reward token.
func (p *Project) SetTokenPath(tokenPath string) {
	p.tokenPath = tokenPath
}

// DepositAmount returns the total reward-token allocation configured for the project.
//
// Returns:
//   - amount: project reward-token allocation.
func (p *Project) DepositAmount() int64 {
	return p.depositAmount
}

// SetDepositAmount replaces the project's total reward-token allocation.
//
// Parameters:
//   - amount: total reward-token amount allocated to the project.
func (p *Project) SetDepositAmount(amount int64) {
	p.depositAmount = amount
}

// Recipient returns the address authorized to receive the project's rewards.
//
// Returns:
//   - recipient: configured project recipient address.
func (p *Project) Recipient() address {
	return p.recipient
}

// SetRecipient replaces the address authorized to receive project rewards.
//
// Parameters:
//   - recipient: address to store as the project recipient.
func (p *Project) SetRecipient(recipient address) {
	p.recipient = recipient
}

// Conditions returns a copy of the project's token deposit conditions.
//
// Returns:
//   - conditions: map from token path to cloned condition values; mutations do not alter project state.
func (p *Project) Conditions() map[string]*ProjectCondition {
	conditions := make(map[string]*ProjectCondition)

	for tokenPath, condition := range p.conditions {
		conditions[tokenPath] = condition.Clone()
	}

	return conditions
}

// SetConditions replaces the project's token deposit conditions.
// The map and its entries are retained in the project realm for later mutation.
//
// Parameters:
//   - conditions: map from required token path to its deposit condition.
func (p *Project) SetConditions(conditions map[string]*ProjectCondition) {
	owned := make(map[string]*ProjectCondition, len(conditions))
	for tokenPath, condition := range conditions {
		owned[tokenPath] = condition
	}
	p.conditions = owned
}

// SetCondition replaces one token-path deposit condition in the project-owned map.
//
// Parameters:
//   - tokenPath: token path whose condition is replaced.
//   - condition: required balance condition for that token path.
func (p *Project) SetCondition(tokenPath string, condition *ProjectCondition) {
	p.conditions[tokenPath] = condition
}

// Tiers returns a copy of the project's configured duration-to-tier map.
//
// Returns:
//   - tiers: map from tier duration in seconds to cloned tier values.
func (p *Project) Tiers() map[int64]*ProjectTier {
	tiers := make(map[int64]*ProjectTier)

	for duration, tier := range p.tiers {
		tiers[duration] = tier.Clone()
	}

	return tiers
}

// SetTiers replaces the project's tier map with a project-owned map.
//
// Parameters:
//   - tiers: map from tier duration in seconds to its tier configuration.
func (p *Project) SetTiers(tiers map[int64]*ProjectTier) {
	owned := make(map[int64]*ProjectTier, len(tiers))
	for duration, tier := range tiers {
		owned[duration] = tier
	}
	p.tiers = owned
}

// TiersRatios returns reward allocation ratios keyed by tier duration.
//
// Returns:
//   - ratios: map from tier duration in seconds to its allocation ratio.
func (p *Project) TiersRatios() map[int64]int64 {
	return p.tiersRatios
}

// SetTiersRatios replaces the project's tier allocation ratios.
//
// Parameters:
//   - tiersRatios: map from tier duration in seconds to its reward allocation ratio.
func (p *Project) SetTiersRatios(tiersRatios map[int64]int64) {
	p.tiersRatios = tiersRatios
}

// CreatedHeight returns the block height at which the project was created.
//
// Returns:
//   - height: project creation block height.
func (p *Project) CreatedHeight() int64 {
	return p.createdHeight
}

// SetCreatedHeight replaces the project's creation block height.
//
// Parameters:
//   - height: block height to store as the project creation height.
func (p *Project) SetCreatedHeight(height int64) {
	p.createdHeight = height
}

// CreatedAt returns the Unix timestamp at which the project was created.
//
// Returns:
//   - time: project creation Unix timestamp.
func (p *Project) CreatedAt() int64 {
	return p.createdAt
}

// SetCreatedAt replaces the project's creation timestamp.
//
// Parameters:
//   - time: Unix timestamp to store as the project creation time.
func (p *Project) SetCreatedAt(time int64) {
	p.createdAt = time
}

// GetTier returns a copy of the project's tier for one duration.
//
// Parameters:
//   - duration: tier duration in seconds.
//
// Returns:
//   - tier: cloned tier configuration for the duration, or nil when absent.
//   - err: non-nil when no tier is configured for duration.
func (p *Project) GetTier(duration int64) (*ProjectTier, error) {
	tier, exists := p.tiers[duration]
	if !exists {
		return nil, ufmt.Errorf("tier(%d) not found", duration)
	}

	return tier.Clone(), nil
}

// SetTier replaces one duration entry in the project-owned tier map.
//
// Parameters:
//   - duration: tier duration in seconds used as the map key.
//   - tier: tier configuration to store for duration.
func (p *Project) SetTier(duration int64, tier *ProjectTier) {
	p.tiers[duration] = tier
}

// IsRecipient reports whether recipient matches the project's configured recipient address.
//
// Parameters:
//   - recipient: address to compare with the configured project recipient.
//
// Returns:
//   - matches: true when recipient is the configured project recipient.
func (p *Project) IsRecipient(recipient address) bool {
	return p.recipient == recipient
}

// NewProject creates a project with empty conditions, tiers, and tier-ratio maps.
//
// Parameters:
//   - name: human-readable project name.
//   - tokenPath: token path whose tokens are distributed as project rewards.
//   - depositAmount: total reward-token amount allocated to the project.
//   - recipient: address authorized to receive project rewards.
//   - createdHeight: block height at which the project is created.
//   - createdAt: Unix timestamp at which the project is created.
//
// Returns:
//   - project: initialized project with an ID derived from tokenPath and createdHeight.
func NewProject(
	name string,
	tokenPath string,
	depositAmount int64,
	recipient address,
	createdHeight int64,
	createdAt int64,
) *Project {
	return &Project{
		id:            MakeProjectID(tokenPath, createdHeight),
		name:          name,
		tokenPath:     tokenPath,
		depositAmount: depositAmount,
		recipient:     recipient,
		conditions:    make(map[string]*ProjectCondition),
		tiers:         make(map[int64]*ProjectTier),
		tiersRatios:   make(map[int64]int64),
		createdHeight: createdHeight,
		createdAt:     createdAt,
	}
}

// Clone returns a deep-enough copy of the project for independent map and nested
// condition/tier mutation; scalar fields are copied directly.
//
// Returns:
//   - clone: project copy with independently allocated condition, tier, and ratio maps.
func (p Project) Clone() *Project {
	conditions := make(map[string]*ProjectCondition)
	for k, v := range p.conditions {
		conditions[k] = v.Clone()
	}

	tiers := make(map[int64]*ProjectTier)
	for k, v := range p.tiers {
		tiers[k] = v.Clone()
	}

	tiersRatios := make(map[int64]int64)
	for k, v := range p.tiersRatios {
		tiersRatios[k] = v
	}

	return &Project{
		id:            p.id,
		name:          p.name,
		tokenPath:     p.tokenPath,
		depositAmount: p.depositAmount,
		recipient:     p.recipient,
		conditions:    conditions,
		tiers:         tiers,
		tiersRatios:   tiersRatios,
		createdHeight: p.createdHeight,
		createdAt:     p.createdAt,
	}
}

// MakeProjectID combines a token path and creation height into a project identifier.
//
// Parameters:
//   - tokenPath: token path associated with the project.
//   - createdHeight: block height at which the project was created.
//
// Returns:
//   - projectID: identifier in "{tokenPath}:{createdHeight}" form.
func MakeProjectID(tokenPath string, createdHeight int64) string {
	return ufmt.Sprintf("%s:%d", tokenPath, createdHeight)
}

package launchpad

import (
	"strconv"
	"strings"

	ufmt "gno.land/p/nt/ufmt/v0"
)

const stringSplitterPad = "*PAD*"

// ProjectCondition represents a condition for a project.
//
// This struct contains the necessary data and methods to manage and distribute
// rewards for a specific project.
//
// Fields:
// - tokenPath (string): The path of the token associated with the project.
// - minimumAmount (int64): The minimum amount of the token required for the project.
type ProjectCondition struct {
	tokenPath     string
	minimumAmount int64
}

// TokenPath returns the token contract path required by this condition.
//
// Returns:
//   - tokenPath: configured condition token path; an empty string means no token is configured.
func (p *ProjectCondition) TokenPath() string {
	return p.tokenPath
}

// MinimumAmount returns the minimum balance amount required by this condition.
//
// Returns:
//   - minimumAmount: minimum amount in the token's base units; values at or below zero make the condition unavailable.
func (p *ProjectCondition) MinimumAmount() int64 {
	return p.minimumAmount
}

// IsAvailable reports whether this condition has a non-empty token path and a positive minimum amount.
//
// Returns:
//   - available: true when both the token path and minimum amount are valid; false otherwise.
func (p *ProjectCondition) IsAvailable() bool {
	return p.tokenPath != "" && p.minimumAmount > 0
}

// CheckBalanceCondition validates an input token balance against this condition.
//
// Parameters:
//   - inputTokenPath: token path whose balance is being checked; it must equal the condition token path.
//   - inputAmount: input token balance in base units; it must be at least the configured minimum.
//
// Returns:
//   - err: nil when the token path and amount satisfy the condition; non-nil describing a mismatch otherwise.
func (p *ProjectCondition) CheckBalanceCondition(inputTokenPath string, inputAmount int64) error {
	if p.tokenPath != inputTokenPath {
		return ufmt.Errorf("token path(%s) is not matched", inputTokenPath)
	}

	if inputAmount < p.minimumAmount {
		return ufmt.Errorf("input amount(%d) is less than minimum amount(%d)", inputAmount, p.minimumAmount)
	}

	return nil
}

// Clone returns an independent copy of this project condition.
//
// Returns:
//   - condition: copied token path and minimum amount in a new ProjectCondition value.
func (p ProjectCondition) Clone() *ProjectCondition {
	return &ProjectCondition{
		tokenPath:     p.tokenPath,
		minimumAmount: p.minimumAmount,
	}
}

// NewProjectCondition creates a project condition for a token path and minimum amount.
//
// Parameters:
//   - tokenPath: token contract path whose balance is required.
//   - minimumAmount: minimum balance in the token's base units.
//
// Returns:
//   - condition: newly allocated project condition containing the supplied values.
func NewProjectCondition(tokenPath string, minimumAmount int64) *ProjectCondition {
	return &ProjectCondition{
		tokenPath:     tokenPath,
		minimumAmount: minimumAmount,
	}
}

// NewProjectConditionsWithError parses parallel *PAD*-separated token paths and minimum amounts.
//
// Parameters:
//   - conditionTokens: *PAD*-separated token contract paths, in condition order.
//   - conditionAmounts: *PAD*-separated decimal int64 minimum amounts paired by index with conditionTokens; entries beyond the token list are not consumed.
//
// Returns:
//   - conditions: parsed available conditions in the same order as their token paths; empty when both inputs are empty.
//   - err: nil on successful parsing; non-nil when a token lacks a matching amount, an amount is not a valid int64, or a condition is unavailable.
func NewProjectConditionsWithError(conditionTokens string, conditionAmounts string) ([]*ProjectCondition, error) {
	if conditionTokens == "" && conditionAmounts == "" {
		return []*ProjectCondition{}, nil
	}

	conditions := []*ProjectCondition{}

	tokenPaths := strings.Split(conditionTokens, stringSplitterPad)
	minimumAmounts := strings.Split(conditionAmounts, stringSplitterPad)

	for index, tokenPath := range tokenPaths {
		if index >= len(minimumAmounts) {
			return nil, ufmt.Errorf("condition amount(%s) is not matched with condition token(%s)", conditionAmounts, conditionTokens)
		}

		minimumAmount, err := strconv.ParseInt(minimumAmounts[index], 10, 64)
		if err != nil {
			return nil, ufmt.Errorf("condition amount(%s) is not a valid integer", minimumAmounts[index])
		}

		condition := NewProjectCondition(tokenPath, minimumAmount)
		if !condition.IsAvailable() {
			return nil, ufmt.Errorf("condition(%s) is not available", condition.TokenPath())
		}

		conditions = append(conditions, condition)
	}

	return conditions, nil
}

package launchpad

import (
	ufmt "gno.land/p/nt/ufmt/v0"

	u256 "gno.land/p/gnoswap/uint256/v1"
)

// ProjectTier represents a tier within a project.
//
// This struct contains the necessary data and methods to manage and distribute
// rewards for a specific tier of a project.
//
// Fields:
// - distributeAmountPerSecondX128 (u256.Uint): The amount of tokens to be distributed per second, represented as a Q128 fixed-point number.
// - startTime (int64): The time for the start of the tier.
// - endTime (int64): The time for the end of the tier.
// - id (string): The unique identifier for the tier, formatted as "{projectID}:duration".
// - totalDistributeAmount (int64): The total amount of tokens to be distributed for the tier.
// - totalDepositAmount (int64): The total amount of tokens deposited for the tier.
// - totalWithdrawAmount (int64): The total amount of tokens withdrawn from the tier.
// - totalDepositCount (int64): The total number of deposits made to the tier.
// - totalWithdrawCount (int64): The total number of withdrawals from the tier.
// - totalCollectedAmount (int64): The total amount of tokens collected as rewards for the tier.
type ProjectTier struct {
	distributeAmountPerSecondX128 *u256.Uint // distribute amount per second, Q128
	id                            string     // '{projectId}:duration' // duration == 30, 90, 180
	totalDistributeAmount         int64
	totalDepositAmount            int64 // accumulated deposit amount
	totalWithdrawAmount           int64 // accumulated withdraw amount
	totalDepositCount             int64 // accumulated deposit count
	totalWithdrawCount            int64 // accumulated withdraw count
	totalCollectedAmount          int64 // total collected amount by user (reward)
	startTime                     int64
	endTime                       int64
}

// DistributeAmountPerSecondX128 returns the distribute amount per second (Q128) of the project tier.
//
// Returns:
//   - amount: per-second distribution rate encoded as a Q128 fixed-point value.
func (pt *ProjectTier) DistributeAmountPerSecondX128() *u256.Uint {
	return pt.distributeAmountPerSecondX128
}

// SetDistributeAmountPerSecondX128 sets the distribute amount per second (Q128) of the project tier.
//
// Parameters:
//   - amount: per-second distribution rate to store, encoded as a Q128 fixed-point value.
func (pt *ProjectTier) SetDistributeAmountPerSecondX128(amount *u256.Uint) {
	pt.distributeAmountPerSecondX128 = u256.Zero().Set(amount)
}

// ID returns the ID of the project tier.
//
// Returns:
//   - id: tier identifier in the "{projectID}:{duration}" form.
func (pt *ProjectTier) ID() string {
	return pt.id
}

// SetID sets the ID of the project tier.
//
// Parameters:
//   - id: tier identifier to store, normally "{projectID}:{duration}".
func (pt *ProjectTier) SetID(id string) {
	pt.id = id
}

// TotalDistributeAmount returns the total distribute amount of the project tier.
//
// Returns:
//   - amount: total token amount allocated for distribution by this tier.
func (pt *ProjectTier) TotalDistributeAmount() int64 {
	return pt.totalDistributeAmount
}

// SetTotalDistributeAmount sets the total distribute amount of the project tier.
//
// Parameters:
//   - amount: total token amount allocated for distribution by this tier.
func (pt *ProjectTier) SetTotalDistributeAmount(amount int64) {
	pt.totalDistributeAmount = amount
}

// TotalDepositAmount returns the total deposit amount of the project tier.
//
// Returns:
//   - amount: aggregate token amount deposited into this tier.
func (pt *ProjectTier) TotalDepositAmount() int64 {
	return pt.totalDepositAmount
}

// SetTotalDepositAmount sets the total deposit amount of the project tier.
//
// Parameters:
//   - amount: aggregate token amount to record as deposited into this tier.
func (pt *ProjectTier) SetTotalDepositAmount(amount int64) {
	pt.totalDepositAmount = amount
}

// TotalWithdrawAmount returns the total withdraw amount of the project tier.
//
// Returns:
//   - amount: aggregate token amount withdrawn from this tier.
func (pt *ProjectTier) TotalWithdrawAmount() int64 {
	return pt.totalWithdrawAmount
}

// SetTotalWithdrawAmount sets the total withdraw amount of the project tier.
//
// Parameters:
//   - amount: aggregate token amount to record as withdrawn from this tier.
func (pt *ProjectTier) SetTotalWithdrawAmount(amount int64) {
	pt.totalWithdrawAmount = amount
}

// TotalDepositCount returns the total deposit count of the project tier.
//
// Returns:
//   - count: number of deposits recorded for this tier.
func (pt *ProjectTier) TotalDepositCount() int64 {
	return pt.totalDepositCount
}

// SetTotalDepositCount sets the total deposit count of the project tier.
//
// Parameters:
//   - count: number of deposits to record for this tier.
func (pt *ProjectTier) SetTotalDepositCount(count int64) {
	pt.totalDepositCount = count
}

// TotalWithdrawCount returns the total withdraw count of the project tier.
//
// Returns:
//   - count: number of withdrawals recorded for this tier.
func (pt *ProjectTier) TotalWithdrawCount() int64 {
	return pt.totalWithdrawCount
}

// SetTotalWithdrawCount sets the total withdraw count of the project tier.
//
// Parameters:
//   - count: number of withdrawals to record for this tier.
func (pt *ProjectTier) SetTotalWithdrawCount(count int64) {
	pt.totalWithdrawCount = count
}

// TotalCollectedAmount returns the total collected amount of the project tier.
//
// Returns:
//   - amount: aggregate reward amount collected from this tier.
func (pt *ProjectTier) TotalCollectedAmount() int64 {
	return pt.totalCollectedAmount
}

// SetTotalCollectedAmount sets the total collected amount of the project tier.
//
// Parameters:
//   - amount: aggregate reward amount to record as collected from this tier.
func (pt *ProjectTier) SetTotalCollectedAmount(amount int64) {
	pt.totalCollectedAmount = amount
}

// StartTime returns the start time of the project tier.
//
// Returns:
//   - time: tier start timestamp in Unix seconds.
func (pt *ProjectTier) StartTime() int64 {
	return pt.startTime
}

// SetStartTime sets the start time of the project tier.
//
// Parameters:
//   - time: tier start timestamp in Unix seconds.
func (pt *ProjectTier) SetStartTime(time int64) {
	pt.startTime = time
}

// EndTime returns the end time of the project tier.
//
// Returns:
//   - time: tier end timestamp in Unix seconds.
func (pt *ProjectTier) EndTime() int64 {
	return pt.endTime
}

// SetEndTime sets the end time of the project tier.
//
// Parameters:
//   - time: tier end timestamp in Unix seconds.
func (pt *ProjectTier) SetEndTime(time int64) {
	pt.endTime = time
}

// IsActivated reports whether the tier is active at the supplied timestamp.
//
// Parameters:
//   - currentTime: timestamp in Unix seconds to compare with the tier window.
//
// Returns:
//   - activated: true when startTime <= currentTime and currentTime < endTime; false otherwise.
func (pt *ProjectTier) IsActivated(currentTime int64) bool {
	return pt.startTime <= currentTime && currentTime < pt.endTime
}

// IsEnded returns true if the project tier has ended.
//
// Parameters:
//   - currentTime: timestamp in Unix seconds to compare with the tier end time.
//
// Returns:
//   - ended: true when endTime is strictly less than currentTime; false at or before the end time.
func (pt *ProjectTier) IsEnded(currentTime int64) bool {
	return pt.endTime < currentTime
}

// Clone returns an independent copy of the project tier, including a cloned
// Q128 distribution-rate value and all aggregate counters.
//
// Returns:
//   - clone: copy whose mutable fixed-point value is independent of the receiver.
func (pt ProjectTier) Clone() *ProjectTier {
	return &ProjectTier{
		id:                            pt.id,
		totalDistributeAmount:         pt.totalDistributeAmount,
		distributeAmountPerSecondX128: pt.distributeAmountPerSecondX128.Clone(),
		startTime:                     pt.startTime,
		endTime:                       pt.endTime,
		totalDepositAmount:            pt.totalDepositAmount,
		totalWithdrawAmount:           pt.totalWithdrawAmount,
		totalDepositCount:             pt.totalDepositCount,
		totalWithdrawCount:            pt.totalWithdrawCount,
		totalCollectedAmount:          pt.totalCollectedAmount,
	}
}

// NewProjectTier returns a pointer to a new ProjectTier with the given values.
//
// Parameters:
//   - projectID: launchpad project identifier associated with the tier.
//   - tierDuration: tier duration in days; launchpad tiers use 30, 90, or 180.
//   - totalDistributeAmount: total token amount allocated for this tier.
//   - startTime: tier start timestamp in Unix seconds.
//   - endTime: tier end timestamp in Unix seconds.
//
// Returns:
//   - tier: new ProjectTier with the supplied identity, allocation, and time window; counters and rates start at zero.
func NewProjectTier(
	projectID string,
	tierDuration int64,
	totalDistributeAmount int64,
	startTime int64,
	endTime int64,
) *ProjectTier {
	return &ProjectTier{
		id:                            MakeProjectTierID(projectID, tierDuration),
		totalDistributeAmount:         totalDistributeAmount,
		distributeAmountPerSecondX128: u256.Zero(),
		startTime:                     startTime,
		endTime:                       endTime,
		totalDepositAmount:            0,
		totalWithdrawAmount:           0,
		totalDepositCount:             0,
		totalWithdrawCount:            0,
		totalCollectedAmount:          0,
	}
}

// MakeProjectTierID constructs the tier identifier from a project ID and duration.
// The resulting identifier uses the "{projectID}:{duration}" format.
//
// Parameters:
//   - projectID: unique launchpad project identifier associated with the tier.
//   - duration: tier duration in days, such as 30, 90, or 180.
//
// Returns:
//   - projectTierID: identifier combining projectID and duration with a colon.
func MakeProjectTierID(projectID string, duration int64) string {
	return ufmt.Sprintf("%s:%d", projectID, duration)
}

package launchpad

// CreateProject creates a new launchpad project callable by the administrator or governance.
//
// Parameters:
//   - cur: current realm context; callers use cross(cur) when crossing into this realm.
//   - name: human-readable project name.
//   - tokenPath: token path whose tokens are distributed as project rewards.
//   - recipient: address authorized to receive project rewards and project proceeds.
//   - depositAmount: total reward-token amount allocated to the project.
//   - conditionTokens: optional `*PAD*`-separated token paths required for deposits.
//   - conditionAmounts: optional `*PAD*`-separated required amounts matching conditionTokens.
//   - tier30Ratio: reward allocation ratio for the 30-day tier.
//   - tier90Ratio: reward allocation ratio for the 90-day tier.
//   - tier180Ratio: reward allocation ratio for the 180-day tier.
//   - startTime: Unix timestamp at which project reward distribution starts.
//
// Returns:
//   - projectId: identifier assigned to the newly created project.
//
// Halt check: reverts while the Launchpad halt scope is active.
func CreateProject(
	cur realm,
	name string,
	tokenPath string,
	recipient address,
	depositAmount int64,
	conditionTokens string,
	conditionAmounts string,
	tier30Ratio int64,
	tier90Ratio int64,
	tier180Ratio int64,
	startTime int64,
) string {
	return getImplementation().CreateProject(
		0,
		cur,
		name,
		tokenPath,
		recipient,
		depositAmount,
		conditionTokens,
		conditionAmounts,
		tier30Ratio,
		tier90Ratio,
		tier180Ratio,
		startTime,
	)
}

// CollectProtocolFee collects protocol-fee rewards allocated to project recipients.
//
// Parameters:
//   - cur: current realm context; callers use cross(cur) when crossing into this realm.
//
// Halt check: reverts while the Withdraw halt scope is active.
func CollectProtocolFee(cur realm) {
	getImplementation().CollectProtocolFee(0, cur)
}

