	"gno.land/p/gnoswap/consts/v1"
	"gno.land/p/gnoswap/gnsmath/v1"
	i256 "gno.land/p/gnoswap/int256/v1"
	u256 "gno.land/p/gnoswap/uint256/v1"
	"gno.land/p/gnoswap/utils/v1"

	pl "gno.land/r/gnoswap/pool"
)

// Hook functions allow external contracts to be notified of swap events.
var (
	// MUST BE IMMUTABLE.
	// DO NOT USE THIS VALUE IN ANY ARITHMETIC OPERATIONS' INITIALIZATION
	zero           = u256.Zero()
	zeroI256       = i256.Zero() /* readonly */
	fixedPointQ128 = u256.MustFromDecimal(Q128)

	maxInt256 = u256.MustFromDecimal(MAX_INT256)
	maxInt64  = i256.Zero().SetInt64(INT64_MAX)
	minInt64  = i256.Zero().SetInt64(INT64_MIN)
)

// SetTickCrossHook sets the hook function called when a tick is crossed during swaps.
//
// Allows staker to monitor liquidity changes at price levels.
// Used for reward calculation when positions enter/exit range.
//
// Only callable by staker contract.
// Parameters:
//   - _: Leading integer discriminator for the forwarded realm call; callers
//     pass 0.
//   - rlm: Propagated realm context validated as current before the hook is
//     stored.
//   - hook: Callback invoked after an initialized tick is crossed with the
//     current pool realm, pool path, tick index, swap direction, and timestamp.
func (i *poolV1) SetTickCrossHook(_ int, rlm realm, hook func(cur realm, poolPath string, tickId int32, zeroForOne bool, timestamp int64)) {
	access.AssertIsRlmCurrent(0, rlm)

	i.assertPoolUnlocked()

	caller := rlm.Previous().Address()
	access.AssertIsStaker(caller)

	i.lockPool(0, rlm)
	defer i.unlockPool(0, rlm)

	err := i.store.SetTickCrossHook(0, rlm, hook)
	if err != nil {
		panic(err)
	}
}

// SetSwapStartHook sets the hook function called at the beginning of a swap.
//
// Enables pre-swap state tracking for reward distribution.
// Captures timestamp for time-weighted calculations.
//
// Only callable by staker contract.
//
// Parameters:
//   - _: Leading integer discriminator for the forwarded realm call; callers
//     pass 0.
//   - rlm: Propagated realm context validated as current before the hook is
//     stored.
//   - hook: Callback invoked before swap computation with the current pool
//     realm, pool path, and block timestamp.
func (i *poolV1) SetSwapStartHook(_ int, rlm realm, hook func(cur realm, poolPath string, timestamp int64)) {
	access.AssertIsRlmCurrent(0, rlm)

	i.assertPoolUnlocked()

	caller := rlm.Previous().Address()
	access.AssertIsStaker(caller)

	i.lockPool(0, rlm)
	defer i.unlockPool(0, rlm)

	err := i.store.SetSwapStartHook(0, rlm, hook)
	if err != nil {
		panic(err)
	}
}

// SetSwapEndHook sets the hook function called at the end of a swap.
//
// Finalizes reward calculations after swap completion.
// Allows error propagation to revert invalid swaps.
//
// Only callable by staker contract.
//
// Parameters:
//   - _: Leading integer discriminator for the forwarded realm call; callers
//     pass 0.
//   - rlm: Propagated realm context validated as current before the hook is
//     stored.
//   - hook: Callback invoked after swap settlement with the current pool realm
//     and pool path; a non-nil error aborts the surrounding swap.
func (i *poolV1) SetSwapEndHook(_ int, rlm realm, hook func(cur realm, poolPath string) error) {
	access.AssertIsRlmCurrent(0, rlm)

	i.assertPoolUnlocked()

	caller := rlm.Previous().Address()
	access.AssertIsStaker(caller)

	i.lockPool(0, rlm)
	defer i.unlockPool(0, rlm)

	err := i.store.SetSwapEndHook(0, rlm, hook)
	if err != nil {
		panic(err)
	}
}

// SwapResult encapsulates all state changes from a swap.
// It ensures atomic state transitions that can be applied at once.
type SwapResult struct {
	Amount0              *i256.Int
	Amount1              *i256.Int
	NewSqrtPrice         *u256.Uint
	NewTick              int32
	NewLiquidity         *u256.Uint
	NewProtocolFeeToken0 int64
	NewProtocolFeeToken1 int64
	FeeGrowthGlobal0X128 *u256.Uint
	FeeGrowthGlobal1X128 *u256.Uint
}

// SwapComputation encapsulates the pure computation logic for swaps.
type SwapComputation struct {
	AmountSpecified   *i256.Int
	SqrtPriceLimitX96 *u256.Uint
	ZeroForOne        bool
	ExactInput        bool
	InitialState      SwapState
	Cache             *SwapCache
}

// Swap executes a swap with callback pattern for optimistic transfers.
// This allows flash swaps where tokens are sent before payment is received.
//
// The flow is:
// 1. Pool sends output tokens to recipient
// 2. Pool calls callback on msg.sender
// 3. Callback must ensure pool receives input tokens
// 4. Pool validates its balance increased correctly
//
// Parameters:
//   - _: Leading integer discriminator for the forwarded realm call; callers
//     pass 0.
//   - rlm: Current propagated realm context; it is validated as current and
//     used for token transfers and callbacks.
//   - token0Path: Registered path of token0; it must be the first token in the
//     pool's canonical token ordering.
//   - token1Path: Registered path of token1; it must be the second token in
//     the pool's canonical token ordering.
//   - fee: Fee tier identifying the registered pool to swap against.
//   - recipient: Address that receives the output token transfer.
//   - zeroForOne: Swap direction; true sells token0 for token1, false sells
//     token1 for token0.
//   - amountSpecified: Signed decimal amount; positive values request exact
//     input, negative values request exact output, and zero is invalid.
//   - sqrtPriceLimitX96: Decimal Q96 square-root-price limit that bounds the
//     swap in its direction; an invalid bound causes the call to panic.
//   - swapCallback: Callback that must settle the input delta after output is
//     sent; it receives signed int64 token deltas and a callback marker, and a
//     non-nil error aborts the swap.
//
// Returns:
//   - string: Signed decimal token0 delta from the pool's perspective; a
//     positive value is owed to the pool and a negative value is sent out.
//   - string: Signed decimal token1 delta from the pool's perspective; a
//     positive value is owed to the pool and a negative value is sent out.
func (i *poolV1) Swap(
	_ int,
	rlm realm,
	token0Path string,
	token1Path string,
	fee uint32,
	recipient address,
	zeroForOne bool,
	amountSpecified string,
	sqrtPriceLimitX96 string,
	swapCallback func(cur realm, amount0Delta, amount1Delta int64, _ *pl.CallbackMarker) error,
) (string, string) {
	access.AssertIsRlmCurrent(0, rlm)

	i.assertPoolUnlocked()
	halt.AssertIsNotHaltedPool()

	assertIsNotUserCall(0, rlm)
	assertIsValidTokenOrder(token0Path, token1Path)

	amounts := i256.MustFromDecimal(amountSpecified)
	if amounts.IsZero() {
		panic(newErrorWithDetail(
			errInvalidSwapAmount,
			"amountSpecified == 0",
		))
	}

	pool := i.mustGetPoolBy(token0Path, token1Path, fee)
	observations := i.mustGetObservations(pool.PoolPath())

	slot0Start := pool.Slot0()
	i.lockPool(0, rlm)
	defer i.unlockPool(0, rlm)

	blockTimestamp := time.Now().Unix()

	// Call swap start hook if set
	if i.store.HasSwapStartHook() {
		swapStartHook := i.store.GetSwapStartHook()

		if swapStartHook != nil {
			swapStartHook(cross(rlm), pool.PoolPath(), blockTimestamp)
		}
	}

	sqrtPriceLimit := u256.MustFromDecimal(sqrtPriceLimitX96)
	validatePriceLimits(slot0Start, zeroForOne, sqrtPriceLimit)

	feeGrowthGlobalX128 := getFeeGrowthGlobal(pool, zeroForOne)
	feeProtocol := getFeeProtocol(slot0Start, zeroForOne)
	cache := newSwapCache(feeProtocol, pool.Liquidity().Clone(), blockTimestamp, slot0Start)
	state := newSwapState(amounts, feeGrowthGlobalX128, cache.liquidityStart.Clone(), slot0Start)

	comp := SwapComputation{
		AmountSpecified:   amounts,
		SqrtPriceLimitX96: sqrtPriceLimit,
		ZeroForOne:        zeroForOne,
		ExactInput:        amounts.Gt(zeroI256),
		InitialState:      state,
		Cache:             cache,
	}

	var hook func(cur realm, poolPath string, tickId int32, zeroForOne bool, timestamp int64)
	if i.store.HasTickCrossHook() {
		hook = i.store.GetTickCrossHook()
	}
	onTickCross := func(pool *pl.Pool, tickId int32, zeroForOne bool, timestamp int64) {
		chain.Emit(
			"PoolTickCross",
			"poolPath", pool.PoolPath(),
			"tick", NewTickEventInfo(tickId, *mustGetTick(pool, tickId)).ToString(),
		)
		if hook != nil {
			hook(cross(rlm), pool.PoolPath(), tickId, zeroForOne, timestamp)
		}
	}

	result, err := i.computeSwap(pool, observations, comp, onTickCross)
	if err != nil {
		panic(err)
	}

	// Update oracle BEFORE applying swap result (using pre-swap state)
	if result.NewTick != slot0Start.Tick() {
		observationIndex, observationCardinality, err := writeObservation(
			observations,
			slot0Start.ObservationIndex(),
			cache.blockTimestamp,
			slot0Start.Tick(),
			cache.liquidityStart,
			slot0Start.ObservationCardinality(),
			slot0Start.ObservationCardinalityNext(),
		)
		if err != nil {
			panic(err)
		}
		slot0 := pool.Slot0()
		slot0.SetObservationIndex(observationIndex)
		slot0.SetObservationCardinality(observationCardinality)
		pool.SetSlot0(slot0)
	}

	applySwapResult(pool, result)

	if i.store.HasSwapEndHook() {
		swapEndHook := i.store.GetSwapEndHook()
		if swapEndHook != nil {
			err := swapEndHook(cross(rlm), pool.PoolPath())
			if err != nil {
				panic(err)
			}
		}
	}

	// transfer swap result to recipient then receive input tokens from swap callback
	if zeroForOne {
		// receive token0 from swap callback
		// send token1 to recipient (output)
		if result.Amount1.IsNeg() {
			i.safeTransfer(0, rlm, pool, recipient, token1Path, result.Amount1.Abs(), false)
		}
		i.safeSwapCallback(0, rlm, pool, token0Path, result.Amount0, result.Amount1, zeroForOne, swapCallback)
	} else {
		// receive token1 from swap callback
		// send token0 to recipient (output)
		if result.Amount0.IsNeg() {
			i.safeTransfer(0, rlm, pool, recipient, token0Path, result.Amount0.Abs(), true)
		}
		i.safeSwapCallback(0, rlm, pool, token1Path, result.Amount1, result.Amount0, zeroForOne, swapCallback)
	}

	slot0 := pool.Slot0()
	lastObservation, err := observationAt(observations, slot0.ObservationIndex())
	if err != nil {
		panic(err)
	}

	token0Amount := result.Amount0.ToString()
	token1Amount := result.Amount1.ToString()

	previousRealm := rlm.Previous()

	chain.Emit(
		"Swap",
		"prevAddr", previousRealm.Address().String(),
		"prevRealm", previousRealm.PkgPath(),
		"poolPath", pool.PoolPath(),
		"zeroForOne", utils.FormatBool(zeroForOne),
		"requestAmount", amountSpecified,
		"sqrtPriceLimitX96", sqrtPriceLimitX96,
		"recipient", recipient.String(),
		"token0Amount", token0Amount,
		"token1Amount", token1Amount,
		"protocolFee0", utils.FormatInt(pool.ProtocolFeesToken0()),
		"protocolFee1", utils.FormatInt(pool.ProtocolFeesToken1()),
		"sqrtPriceX96", pool.Slot0SqrtPriceX96().ToString(),
		"exactIn", strconv.FormatBool(comp.ExactInput),
		"currentTick", strconv.FormatInt(int64(pool.Slot0Tick()), 10),
		"liquidity", pool.Liquidity().ToString(),
		"feeGrowthGlobal0X128", pool.FeeGrowthGlobal0X128().ToString(),
		"feeGrowthGlobal1X128", pool.FeeGrowthGlobal1X128().ToString(),
		"balanceToken0", utils.FormatInt(pool.BalanceToken0()),
		"balanceToken1", utils.FormatInt(pool.BalanceToken1()),
		"tickCumulative", utils.FormatInt(lastObservation.TickCumulative()),
		"secondsPerLiquidityCumulativeX128", lastObservation.SecondsPerLiquidityCumulativeX128(),
		"observationTimestamp", utils.FormatInt(lastObservation.BlockTimestamp()),
	)

	return token0Amount, token1Amount
}

// DrySwap simulates a swap against an isolated pool and observation snapshot;
// it never writes stored pool or oracle state.
//
// Parameters:
//   - token0Path: Registered path of token0; it must be the first token in the
//     pool's canonical token ordering.
//   - token1Path: Registered path of token1; it must be the second token in
//     the pool's canonical token ordering.
//   - fee: Fee tier identifying the registered pool to simulate.
//   - zeroForOne: Swap direction; true sells token0 for token1, false sells
//     token1 for token0.
//   - amountSpecified: Signed decimal amount; positive values request exact
//     input, negative values request exact output, and zero is invalid.
//   - sqrtPriceLimitX96: Decimal Q96 square-root-price limit that bounds the
//     simulation in its direction.
//
// Returns:
//   - amount0: Signed decimal token0 delta from the pool's perspective, or
//     "0" when simulation fails.
//   - amount1: Signed decimal token1 delta from the pool's perspective, or
//     "0" when simulation fails.
//   - err: Nil when the simulation succeeds; non-nil for invalid inputs,
//     missing pool state, invalid limits, computation failures, or insufficient
//     pool output balance.
func (i *poolV1) DrySwap(
	token0Path string,
	token1Path string,
	fee uint32,
	zeroForOne bool,
	amountSpecified string,
	sqrtPriceLimitX96 string,
) (amount0, amount1 string, err error) {
	defer func() {
		if r := recover(); r != nil {
			amount0 = "0"
			amount1 = "0"
			if recoveredErr, ok := r.(error); ok {
				err = recoveredErr
			} else {
				err = ufmt.Errorf("%v", r)
			}
		}
	}()

	i.assertPoolUnlocked()

	amounts := i256.MustFromDecimal(amountSpecified)
	if amounts.IsZero() {
		return "0", "0", errors.New(errInvalidSwapAmount)
	}

	pool := i.mustGetPoolBy(token0Path, token1Path, fee)
	blockTimestamp := time.Now().Unix()

	slot0Start := pool.Slot0()
	sqrtPriceLimit := u256.MustFromDecimal(sqrtPriceLimitX96)
	validatePriceLimits(slot0Start, zeroForOne, sqrtPriceLimit)

	feeGrowthGlobalX128 := getFeeGrowthGlobal(pool, zeroForOne)
	feeProtocol := getFeeProtocol(slot0Start, zeroForOne)
	cache := newSwapCache(feeProtocol, pool.Liquidity().Clone(), blockTimestamp, slot0Start)
	cache.readOnly = true
	state := newSwapState(amounts, feeGrowthGlobalX128, cache.liquidityStart, slot0Start)

	comp := SwapComputation{
		AmountSpecified:   amounts,
		SqrtPriceLimitX96: sqrtPriceLimit,
		ZeroForOne:        zeroForOne,
		ExactInput:        amounts.Gt(zeroI256),
		InitialState:      state,
		Cache:             cache,
	}

	result, err := i.computeSwap(pool, nil, comp, nil)
	if err != nil {
		return "0", "0", err
	}

	if zeroForOne {
		if pool.BalanceToken1() < gnsmath.SafeConvertToInt64(result.Amount1.Abs()) {
			return "0", "0", errors.New(errInsufficientPoolBalance)
		}
	} else {
		if pool.BalanceToken0() < gnsmath.SafeConvertToInt64(result.Amount0.Abs()) {
			return "0", "0", errors.New(errInsufficientPoolBalance)
		}
	}

	return result.Amount0.ToString(), result.Amount1.ToString(), nil
}

// tickCrossHookFn is invoked after an initialized tick is crossed. Swap uses it
// for externally visible side effects; DrySwap passes nil.
type tickCrossHookFn func(pool *pl.Pool, tickId int32, zeroForOne bool, timestamp int64)

// computeSwap calculates swap amounts; tick accounting is written unless Cache.readOnly is set.
// The computation continues until either:
// - The entire amount is consumed (amountSpecifiedRemaining = 0)
// - The price limit is reached (sqrtPriceX96 = sqrtPriceLimitX96)
//
// Important: This function is critical for AMM price discovery. It iterates through
// tick ranges, calculating swap amounts and fees for each liquidity segment.
// Returns an error if the computation fails at any step.
//
// The optional `onTickCross` callback is invoked when an initialized tick is
// crossed; Swap supplies a hook that performs a cross-realm call into the
// configured tick-cross hook, while DrySwap passes nil.
func (i *poolV1) computeSwap(pool *pl.Pool, observations *pl.ObservationTree, comp SwapComputation, onTickCross tickCrossHookFn) (*SwapResult, error) {
	state := comp.InitialState
	var err error

	// Compute swap steps until completion
	for shouldContinueSwap(state, comp.SqrtPriceLimitX96) {
		state, err = i.computeSwapStep(state, pool, observations, comp.ZeroForOne, comp.SqrtPriceLimitX96, comp.ExactInput, comp.Cache, onTickCross)
		if err != nil {
			return nil, err
		}
	}

	// Calculate final amounts
	amount0 := state.amountCalculated
	amount1 := i256.Zero().Sub(comp.AmountSpecified, state.amountSpecifiedRemaining)
	if comp.ZeroForOne == comp.ExactInput {
		amount0, amount1 = amount1, amount0
	}

	// Prepare result
	result := &SwapResult{
		Amount0:              amount0,
		Amount1:              amount1,
		NewSqrtPrice:         state.sqrtPriceX96,
		NewTick:              state.tick,
		NewLiquidity:         state.liquidity,
		NewProtocolFeeToken0: pool.ProtocolFeesToken0(),
		NewProtocolFeeToken1: pool.ProtocolFeesToken1(),
		FeeGrowthGlobal0X128: pool.FeeGrowthGlobal0X128(),
		FeeGrowthGlobal1X128: pool.FeeGrowthGlobal1X128(),
	}

	// Update protocol fees if necessary
	if comp.ZeroForOne {
		if state.protocolFee.Gt(zero) {
			result.NewProtocolFeeToken0 = gnsmath.SafeAddInt64(result.NewProtocolFeeToken0, gnsmath.SafeConvertToInt64(state.protocolFee))
		}
		result.FeeGrowthGlobal0X128 = state.feeGrowthGlobalX128.Clone()
	} else {
		if state.protocolFee.Gt(zero) {
			result.NewProtocolFeeToken1 = gnsmath.SafeAddInt64(result.NewProtocolFeeToken1, gnsmath.SafeConvertToInt64(state.protocolFee))
		}
		result.FeeGrowthGlobal1X128 = state.feeGrowthGlobalX128.Clone()
	}

	return result, nil
}

// applySwapResult updates pool state with computed results.
// All state changes are applied at once to maintain consistency
func applySwapResult(pool *pl.Pool, result *SwapResult) {
	slot0 := pool.Slot0()
	slot0.SetSqrtPriceX96(result.NewSqrtPrice)
	slot0.SetTick(result.NewTick)
	pool.SetSlot0(slot0)

	pool.SetLiquidity(result.NewLiquidity)
	pool.SetProtocolFeesToken0(result.NewProtocolFeeToken0)
	pool.SetProtocolFeesToken1(result.NewProtocolFeeToken1)
	pool.SetFeeGrowthGlobal0X128(result.FeeGrowthGlobal0X128)
	pool.SetFeeGrowthGlobal1X128(result.FeeGrowthGlobal1X128)
}

// validatePriceLimits ensures the provided price limit is valid for the swap direction
// The function enforces that:
// For zeroForOne (selling token0):
//   - Price limit must be below current price
//   - Price limit must be above MIN_SQRT_RATIO
//
// For !zeroForOne (selling token1):
//   - Price limit must be above current price
//   - Price limit must be below MAX_SQRT_RATIO
func validatePriceLimits(slot0 pl.Slot0, zeroForOne bool, sqrtPriceLimitX96 *u256.Uint) {
	if zeroForOne {
		cond1 := sqrtPriceLimitX96.Lt(slot0.SqrtPriceX96())
		cond2 := sqrtPriceLimitX96.Gt(consts.MinSqrtRatio())
		if !(cond1 && cond2) {
			panic(newErrorWithDetail(
				errPriceOutOfRange,
				ufmt.Sprintf("sqrtPriceLimitX96(%s) < slot0Start.sqrtPriceX96(%s) && sqrtPriceLimitX96(%s) > MIN_SQRT_RATIO(%s)",
					sqrtPriceLimitX96.ToString(),
					slot0.SqrtPriceX96().ToString(),
					sqrtPriceLimitX96.ToString(),
					MIN_SQRT_RATIO),
			))
		}
	} else {
		cond1 := sqrtPriceLimitX96.Gt(slot0.SqrtPriceX96())
		cond2 := sqrtPriceLimitX96.Lt(consts.MaxSqrtRatio())
		if !(cond1 && cond2) {
			panic(newErrorWithDetail(
				errPriceOutOfRange,
				ufmt.Sprintf("sqrtPriceLimitX96(%s) > slot0Start.sqrtPriceX96(%s) && sqrtPriceLimitX96(%s) < MAX_SQRT_RATIO(%s)",
					sqrtPriceLimitX96.ToString(),
					slot0.SqrtPriceX96().ToString(),
					sqrtPriceLimitX96.ToString(),
					MAX_SQRT_RATIO),
			))
		}
	}
}

// getFeeProtocol returns the appropriate fee protocol based on zero for one.
// When zeroForOne is true, we want the lower 4 bits (% 16).
// Otherwise, we want the upper 4 bits (/ 16).
func getFeeProtocol(slot0 pl.Slot0, zeroForOne bool) uint8 {
	shift := uint8(0)
	if !zeroForOne {
		shift = 4
	}
	return (slot0.FeeProtocol() >> shift) & uint8(0xF)
}

// getFeeGrowthGlobal returns the appropriate fee growth global based on zero for one.
func getFeeGrowthGlobal(pool *pl.Pool, zeroForOne bool) *u256.Uint {
	if zeroForOne {
		return pool.FeeGrowthGlobal0X128().Clone()
	}
	return pool.FeeGrowthGlobal1X128().Clone()
}

// shouldContinueSwap checks if swap should continue based on remaining amount and price limit.
func shouldContinueSwap(state SwapState, sqrtPriceLimitX96 *u256.Uint) bool {
	return !state.amountSpecifiedRemaining.IsZero() && !state.sqrtPriceX96.Eq(sqrtPriceLimitX96)
}

// computeSwapStep executes a single step of swap and returns new state
func (i *poolV1) computeSwapStep(
	state SwapState,
	pool *pl.Pool,
	observations *pl.ObservationTree,
	zeroForOne bool,
	sqrtPriceLimitX96 *u256.Uint,
	exactInput bool,
	cache *SwapCache,
	onTickCross tickCrossHookFn,
) (SwapState, error) {
	step := computeSwapStepInit(state, pool, zeroForOne)

	// determining the price target for this step
	sqrtRatioTargetX96 := computeTargetSqrtRatio(step, sqrtPriceLimitX96, zeroForOne).Clone()

	// computing the amounts to be swapped at this step
	var (
		newState SwapState
		err      error
	)

	newState, step = computeAmounts(state, sqrtRatioTargetX96, pool, step)
	newState, err = updateAmounts(step, newState, exactInput)
	if err != nil {
		return state, err
	}

	// if the protocol fee is on, calculate how much is owed,
	// decrement fee amount, and increment protocol fee
	if cache.feeProtocol > 0 {
		newState, step, err = updateFeeProtocol(step, cache.feeProtocol, newState)
		if err != nil {
			return state, err
		}
	}

	// update global fee tracker
	if newState.liquidity.Gt(u256.Zero()) {
		update := u256.MulDiv(step.feeAmount, fixedPointQ128, newState.liquidity)
		feeGrowthGlobalX128 := u256.Zero().Add(newState.feeGrowthGlobalX128, update)
		newState.setFeeGrowthGlobalX128(feeGrowthGlobalX128)
	}

	// handling tick transitions
	if newState.sqrtPriceX96.Eq(step.sqrtPriceNextX96) {
		newState, err = i.tickTransition(step, zeroForOne, newState, pool, observations, cache, onTickCross)
		if err != nil {
			return state, err
		}
	} else if newState.sqrtPriceX96.Neq(step.sqrtPriceStartX96) {
		newState.setTick(gnsmath.TickMathGetTickAtSqrtRatio(newState.sqrtPriceX96))
	}

	return newState, nil
}

// updateFeeProtocol calculates and updates protocol fees for the current step.
func updateFeeProtocol(step StepComputations, feeProtocol uint8, state SwapState) (SwapState, StepComputations, error) {
	delta := u256.Zero().Div(step.feeAmount, u256.NewUint(uint64(feeProtocol)))

	newFeeAmount, overflow := u256.Zero().SubOverflow(step.feeAmount, delta)
	if overflow {
		return state, step, errors.New(errUnderflow)
	}

	step.feeAmount = newFeeAmount

	newProtocolFee, overflow := u256.Zero().AddOverflow(state.protocolFee, delta)
	if overflow {
		return state, step, errors.New(errOverflow)
	}
	state.protocolFee = newProtocolFee

	return state, step, nil
}

// computeSwapStepInit initializes the computation for a single swap step.
func computeSwapStepInit(state SwapState, pool *pl.Pool, zeroForOne bool) StepComputations {
	var step StepComputations
	step.sqrtPriceStartX96 = state.sqrtPriceX96
	tickNext, initialized := tickBitmapNextInitializedTickWithInOneWord(
		pool,
		state.tick,
		pool.TickSpacing(),
		zeroForOne,
	)

	step.tickNext = tickNext
	step.initialized = initialized

	// prevent overshoot the min/max tick
	step.clampTickNext()
	// get the price for the next tick
	step.sqrtPriceNextX96 = gnsmath.TickMathGetSqrtRatioAtTick(step.tickNext)
	return step
}

// computeTargetSqrtRatio determines the target sqrt price for the current swap step.
func computeTargetSqrtRatio(step StepComputations, sqrtPriceLimitX96 *u256.Uint, zeroForOne bool) *u256.Uint {
	if shouldUsePriceLimit(step.sqrtPriceNextX96, sqrtPriceLimitX96, zeroForOne) {
		return sqrtPriceLimitX96
	}
	return step.sqrtPriceNextX96
}

// shouldUsePriceLimit returns true if the price limit should be used instead of the next tick price
func shouldUsePriceLimit(sqrtPriceNext, sqrtPriceLimit *u256.Uint, zeroForOne bool) bool {
	if zeroForOne {
		return sqrtPriceNext.Lt(sqrtPriceLimit)
	}
	return sqrtPriceNext.Gt(sqrtPriceLimit)
}

// computeAmounts calculates the input and output amounts for the current swap step.
func computeAmounts(state SwapState, sqrtRatioTargetX96 *u256.Uint, pool *pl.Pool, step StepComputations) (SwapState, StepComputations) {
	sqrtPriceX96, amountIn, amountOut, feeAmount := gnsmath.SwapMathComputeSwapStep(
		state.sqrtPriceX96,
		sqrtRatioTargetX96,
		state.liquidity,
		state.amountSpecifiedRemaining,
		uint64(pool.Fee()),
	)

	step.amountIn = amountIn
	step.amountOut = amountOut
	step.feeAmount = feeAmount

	state.setSqrtPriceX96(sqrtPriceX96)

	return state, step
}

// updateAmounts calculates new remaining and calculated amounts based on the swap step.
// For exact input swaps:
//   - Decrements remaining input amount by (amountIn + feeAmount)
//   - Decrements calculated amount by amountOut
//
// For exact output swaps:
//   - Increments remaining output amount by amountOut
//   - Increments calculated amount by (amountIn + feeAmount)
func updateAmounts(step StepComputations, state SwapState, exactInput bool) (SwapState, error) {
	amountInWithFeeU256 := u256.Zero().Add(step.amountIn, step.feeAmount)
	if amountInWithFeeU256.Gt(maxInt256) {
		return state, errors.New(errOverflow)
	}

	amountInWithFee := i256.FromUint256(amountInWithFeeU256)
	if step.amountOut.Gt(maxInt256) {
		return state, errors.New(errOverflow)
	}

	var (
		amountSpecifiedRemaining *i256.Int
		amountCalculated         *i256.Int
		overflow                 bool
	)

	if exactInput {
		amountSpecifiedRemaining, overflow = i256.Zero().SubOverflow(state.amountSpecifiedRemaining, amountInWithFee)
		if overflow {
			return state, errors.New(errUnderflow)
		}
		amountCalculated, overflow = i256.Zero().SubOverflow(state.amountCalculated, i256.FromUint256(step.amountOut))
		if overflow {
			return state, errors.New(errUnderflow)
		}
	} else {
		amountSpecifiedRemaining, overflow = i256.Zero().AddOverflow(state.amountSpecifiedRemaining, i256.FromUint256(step.amountOut))
		if overflow {
			return state, errors.New(errOverflow)
		}
		amountCalculated, overflow = i256.Zero().AddOverflow(state.amountCalculated, amountInWithFee)
		if overflow {
			return state, errors.New(errOverflow)
		}
	}

	// If an overflowed value is stored in state, it may cause problems in the next step
	if amountCalculated.Gt(maxInt64) || amountSpecifiedRemaining.Gt(maxInt64) {
		return state, errors.New(errOverflow)
	}

	// If an underflowed value is stored in state, it may cause problems in the next step
	if amountCalculated.Lt(minInt64) || amountSpecifiedRemaining.Lt(minInt64) {
		return state, errors.New(errUnderflow)
	}

	state.amountSpecifiedRemaining = amountSpecifiedRemaining
	state.amountCalculated = amountCalculated

	return state, nil
}

// tickTransition handles the transition between price ticks during a swap
func (i *poolV1) tickTransition(step StepComputations, zeroForOne bool, state SwapState, pool *pl.Pool, observations *pl.ObservationTree, cache *SwapCache, onTickCross tickCrossHookFn) (SwapState, error) {
	// ensure existing state to keep immutability
	newState := state

	if step.initialized {
		var liquidityNet *i256.Int
		if cache.readOnly {
			// Quotes need only the liquidity delta. Outside fee/oracle accumulators
			// do not affect pricing, and the monotonic path never revisits a tick.
			tick := getTick(pool, step.tickNext)
			liquidityNet = i256.MustFromDecimal(tick.LiquidityNet())
		} else {
			// Compute oracle values on first initialized tick cross.
			if !cache.computedLatestObservation {
				tickCumulative, secondsPerLiquidityStr, err := observeSingle(
					observations,
					cache.blockTimestamp,
					0,
					cache.slot0Start.Tick(),
					cache.slot0Start.ObservationIndex(),
					cache.liquidityStart,
					cache.slot0Start.ObservationCardinality(),
				)
				if err != nil {
					return newState, err
				}

				cache.tickCumulative = tickCumulative
				cache.secondsPerLiquidityCumulativeX128 = u256.MustFromDecimal(secondsPerLiquidityStr)
				cache.computedLatestObservation = true
			}

			fee0, fee1 := u256.Zero(), u256.Zero()
			if zeroForOne {
				fee0 = state.feeGrowthGlobalX128
				fee1 = pool.FeeGrowthGlobal1X128()
			} else {
				fee0 = pool.FeeGrowthGlobal0X128()
				fee1 = state.feeGrowthGlobalX128
			}

			liquidityNet = tickCross(
				pool,
				step.tickNext,
				fee0,
				fee1,
				cache.secondsPerLiquidityCumulativeX128,
				cache.tickCumulative,
				cache.blockTimestamp,
			)
		}

		if zeroForOne {
			liquidityNet = i256.Zero().Neg(liquidityNet)
		}

		newState.liquidity = gnsmath.LiquidityMathAddDelta(state.liquidity, liquidityNet)

		if !cache.readOnly && onTickCross != nil {
			onTickCross(pool, step.tickNext, zeroForOne, cache.blockTimestamp)
		}
	}

	newState.tick = step.tickNext
	if zeroForOne {
		newState.tick = step.tickNext - 1
	}

	return newState, nil
}

package pool

import (
	"gno.land/p/gnoswap/consts/v1"
	"gno.land/p/gnoswap/gnsmath/v1"
	ufmt "gno.land/p/nt/ufmt/v0"

	i256 "gno.land/p/gnoswap/int256/v1"
	u256 "gno.land/p/gnoswap/uint256/v1"
	pl "gno.land/r/gnoswap/pool"
)

// MAX_LIQUIDITY_PER_TICK_* values are spacing-specific limits returned by
// calculateMaxLiquidityPerTick; they are not a universal uint128 maximum.

const (
	MAX_LIQUIDITY_PER_TICK_SPACING_1         = "191757530477355301479181766273477"
	MAX_LIQUIDITY_PER_TICK_SPACING_10        = "1917569901783203986719870431555990"
	MAX_LIQUIDITY_PER_TICK_SPACING_60        = "11505743598341114571880798222544994"
	MAX_LIQUIDITY_PER_TICK_SPACING_200       = "38350317471085141830651933667504588"
	MIN_TICK                           int32 = -887272
	MAX_TICK                           int32 = 887272
)

// maxLiquidityPerTickSpacing* return the precomputed max-liquidity-per-tick for
// each supported tick spacing. They are constructors (not package-level vars) so
// each caller receives a fresh instance — calculateMaxLiquidityPerTick returns
// the value directly to callers, and a shared singleton could otherwise be
// mutated in place and corrupt every caller. Values are built from little-endian
// [4]uint64 literals to avoid runtime decimal parsing.
func maxLiquidityPerTickSpacing1FromDec() *u256.Uint {
	return &u256.Uint{3639524637645646277, 10395196556700, 0, 0} // 191757530477355301479181766273477
}

func maxLiquidityPerTickSpacing10FromDec() *u256.Uint {
	return &u256.Uint{4727306266354938262, 103951672670308, 0, 0} // 1917569901783203986719870431555990
}

func maxLiquidityPerTickSpacing60FromDec() *u256.Uint {
	return &u256.Uint{1428959955126579298, 623727610269131, 0, 0} // 11505743598341114571880798222544994
}

func maxLiquidityPerTickSpacing200FromDec() *u256.Uint {
	return &u256.Uint{6592429331424883148, 2078974875882965, 0, 0} // 38350317471085141830651933667504588
}

// getFeeGrowthInside calculates the fee growth within a specified tick range.
//
// This function computes the accumulated fee growth for token 0 and token 1 inside a given tick range
// (`tickLower` to `tickUpper`) relative to the current tick position (`tickCurrent`). It isolates the fee
// growth within the range by subtracting the fee growth below the lower tick and above the upper tick
// from the global fee growth.
//
// Parameters:
//   - tickLower: int32, the lower tick boundary of the range.
//   - tickUpper: int32, the upper tick boundary of the range.
//   - tickCurrent: int32, the current tick index.
//   - feeGrowthGlobal0X128: *u256.Uint, the global fee growth for token 0 in X128 precision.
//   - feeGrowthGlobal1X128: *u256.Uint, the global fee growth for token 1 in X128 precision.
//
// Returns:
//   - *u256.Uint: Fee growth inside the tick range for token 0.
//   - *u256.Uint: Fee growth inside the tick range for token 1.
//
// Workflow:
//  1. Retrieve the tick information (`lower` and `upper`) for the lower and upper tick boundaries
//     using `p.getTick`.
//  2. Calculate the fee growth below the lower tick using `getFeeGrowthBelowX128`.
//  3. Calculate the fee growth above the upper tick using `getFeeGrowthAboveX128`.
//  4. Subtract the fee growth below and above the range from the global fee growth values:
//     feeGrowthInside = feeGrowthGlobal - feeGrowthBelow - feeGrowthAbove
//  5. Return the computed fee growth values for token 0 and token 1 within the range.
//
// Behavior:
//   - The fee growth is isolated within the range `[tickLower, tickUpper]`.
//   - The function ensures the calculations accurately consider the tick boundaries and the current tick position.
//
// Example:
//
// ```gno
//
//	feeGrowth0, feeGrowth1 := pool.getFeeGrowthInside(
//	    100, 200, 150, globalFeeGrowth0, globalFeeGrowth1,
//	)
//	println("Fee Growth Inside (Token 0):", feeGrowth0)
//	println("Fee Growth Inside (Token 1):", feeGrowth1)
//
// ```
func getFeeGrowthInside(
	p *pl.Pool,
	tickLower int32,
	tickUpper int32,
	tickCurrent int32,
	feeGrowthGlobal0X128 *u256.Uint,
	feeGrowthGlobal1X128 *u256.Uint,
) (*u256.Uint, *u256.Uint) {
	lower := getTick(p, tickLower)
	upper := getTick(p, tickUpper)

	feeGrowthBelow0X128, feeGrowthBelow1X128 := getFeeGrowthBelowX128(tickLower, tickCurrent, feeGrowthGlobal0X128, feeGrowthGlobal1X128, lower)
	feeGrowthAbove0X128, feeGrowthAbove1X128 := getFeeGrowthAboveX128(tickUpper, tickCurrent, feeGrowthGlobal0X128, feeGrowthGlobal1X128, upper)

	feeGrowthInside0X128 := u256.Zero().Sub(u256.Zero().Sub(feeGrowthGlobal0X128, feeGrowthBelow0X128), feeGrowthAbove0X128)
	feeGrowthInside1X128 := u256.Zero().Sub(u256.Zero().Sub(feeGrowthGlobal1X128, feeGrowthBelow1X128), feeGrowthAbove1X128)

	return feeGrowthInside0X128, feeGrowthInside1X128
}

// tickUpdate updates the state of a specific tick.
//
// This function applies a given liquidity change (liquidityDelta) to the specified tick, updates
// the fee growth values if necessary, and adjusts the net liquidity based on whether the tick
// is an upper or lower boundary. It also verifies that the total liquidity does not exceed the
// maximum allowed value and ensures the net liquidity stays within the valid int128 range.
//
// Parameters:
//   - tick:          int32, the index of the tick to update.
//   - tickCurrent:   int32, the current active tick index.
//   - liquidityDelta: *i256.Int, the amount of liquidity to add or remove.
//   - feeGrowthGlobal0X128: *u256.Uint, the global fee growth value for token 0.
//   - feeGrowthGlobal1X128: *u256.Uint, the global fee growth value for token 1.
//   - secondsPerLiquidityCumulativeX128: *u256.Uint, the current oracle accumulator used to
//     seed the outside accumulator of a newly initialized active tick (tick <= tickCurrent).
//   - tickCumulative: int64, the current oracle tick accumulator used for the same seeding.
//   - blockTimestamp: int64, the current block timestamp used for the same seeding.
//   - upper:         bool, indicates if this is the upper boundary (true for upper, false for lower).
//   - maxLiquidity:  *u256.Uint, the maximum allowed liquidity.
//
// Returns:
//   - flipped: bool, indicates if the tick's initialization state has changed.
//     (e.g., liquidity transitioning from zero to non-zero, or vice versa)
//
// Workflow:
// 1. Nil input values are replaced with zero.
// 2. The function retrieves the tick information for the specified tick index.
// 3. Applies the liquidityDelta to compute the new total liquidity (liquidityGross).
//   - If the total liquidity exceeds the maximum allowed value, the function panics.
//     4. Checks whether the tick's initialized state has changed and sets the `flipped` flag.
//     5. If the tick was previously uninitialized and its index is less than or equal to the current tick,
//     the fee growth values are initialized to the current global values.
//     6. Updates the tick's net liquidity:
//   - For an upper boundary, it subtracts liquidityDelta.
//   - For a lower boundary, it adds liquidityDelta.
//   - Ensures the net liquidity remains within the int128 range using `checkOverFlowInt128`.
//     7. Updates the tick's state with the new values.
//     8. Returns whether the tick's initialized state has flipped.
//
// Panic Conditions:
// - The total liquidity (liquidityGross) exceeds the maximum allowed liquidity (maxLiquidity).
// - The net liquidity (liquidityNet) exceeds the int128 range.
//
// Example:
//
// ```gno
//
//	flipped := pool.tickUpdate(10, 5, liquidityDelta, feeGrowth0, feeGrowth1, secondsPerLiquidityCumulativeX128, tickCumulative, blockTimestamp, true, maxLiquidity)
//	println("Tick flipped:", flipped)
//
// ```
func tickUpdate(
	p *pl.Pool,
	tick int32,
	tickCurrent int32,
	liquidityDelta *i256.Int,
	feeGrowthGlobal0X128 *u256.Uint,
	feeGrowthGlobal1X128 *u256.Uint,
	secondsPerLiquidityCumulativeX128 *u256.Uint,
	tickCumulative int64,
	blockTimestamp int64,
	upper bool,
	maxLiquidity *u256.Uint,
) (flipped bool) {
	tickInfo := getTick(p, tick)

	liquidityGrossBefore := u256.MustFromDecimal(tickInfo.LiquidityGross())
	liquidityGrossAfter := gnsmath.LiquidityMathAddDelta(liquidityGrossBefore, liquidityDelta)

	if !liquidityGrossAfter.Lte(maxLiquidity) {
		panic(newErrorWithDetail(
			errLiquidityCalculation,
			ufmt.Sprintf("liquidityGrossAfter(%s) overflows maxLiquidity(%s)", liquidityGrossAfter.ToString(), maxLiquidity.ToString()),
		))
	}

	flipped = liquidityGrossAfter.IsZero() != liquidityGrossBefore.IsZero()

	if liquidityGrossBefore.IsZero() {
		if tick <= tickCurrent {
			tickInfo.SetFeeGrowthOutside0X128(feeGrowthGlobal0X128.ToString())
			tickInfo.SetFeeGrowthOutside1X128(feeGrowthGlobal1X128.ToString())
			tickInfo.SetSecondsPerLiquidityOutsideX128(secondsPerLiquidityCumulativeX128.ToString())
			tickInfo.SetTickCumulativeOutside(tickCumulative)
			tickInfo.SetSecondsOutside(uint32(blockTimestamp))
		}
		tickInfo.SetInitialized(true)
	}

	tickInfo.SetLiquidityGross(liquidityGrossAfter.ToString())

	liquidityNet := i256.MustFromDecimal(tickInfo.LiquidityNet())
	if upper {
		newLiquidityNet := i256.Zero().Sub(liquidityNet, liquidityDelta)
		checkOverFlowInt128(newLiquidityNet)
		tickInfo.SetLiquidityNet(newLiquidityNet.ToString())
	} else {
		newLiquidityNet := i256.Zero().Add(liquidityNet, liquidityDelta)
		checkOverFlowInt128(newLiquidityNet)
		tickInfo.SetLiquidityNet(newLiquidityNet.ToString())
	}

	setTick(p, tick, tickInfo)

	return flipped
}

// tickCross updates a tick's state when it is crossed and returns the liquidity net.
// Updates fee growth and oracle accumulator values for the tick.
func tickCross(
	p *pl.Pool,
	tick int32,
	feeGrowthGlobal0X128 *u256.Uint,
	feeGrowthGlobal1X128 *u256.Uint,
	secondsPerLiquidityCumulativeX128 *u256.Uint,
	tickCumulative int64,
	blockTimestamp int64,
) *i256.Int {
	thisTick := getTick(p, tick)

	feeOutside0 := u256.MustFromDecimal(thisTick.FeeGrowthOutside0X128())
	feeOutside1 := u256.MustFromDecimal(thisTick.FeeGrowthOutside1X128())
	thisTick.SetFeeGrowthOutside0X128(u256.Zero().Sub(feeGrowthGlobal0X128, feeOutside0).ToString())
	thisTick.SetFeeGrowthOutside1X128(u256.Zero().Sub(feeGrowthGlobal1X128, feeOutside1).ToString())

	tickSecondsPerLiquidity := u256.MustFromDecimal(thisTick.SecondsPerLiquidityOutsideX128())
	thisTick.SetSecondsPerLiquidityOutsideX128(u256.Zero().Sub(secondsPerLiquidityCumulativeX128, tickSecondsPerLiquidity).ToString())
	thisTick.SetTickCumulativeOutside(tickCumulative - thisTick.TickCumulativeOutside())
	thisTick.SetSecondsOutside(uint32(blockTimestamp) - thisTick.SecondsOutside())

	setTick(p, tick, thisTick)

	return i256.MustFromDecimal(thisTick.LiquidityNet())
}

// setTick updates the tick data for the specified tick index in the pool.
func setTick(p *pl.Pool, tick int32, newTickInfo pl.TickInfo) {
	p.SetTick(tick, newTickInfo)
}

// deleteTick deletes the tick data for the specified tick index in the pool.
func deleteTick(p *pl.Pool, tick int32) {
	p.DeleteTick(tick)
}

// getTick retrieves the TickInfo associated with the specified tick index from the pool.
// If the TickInfo contains any nil fields, they are replaced with zero values using valueOrZero.
//
// Parameters:
// - tick: The tick index (int32) for which the TickInfo is to be retrieved.
//
// Behavior:
// - Retrieves the TickInfo for the given tick from the pool's tick map.
// - Ensures that all fields of TickInfo are non-nil by calling valueOrZero, which replaces nil values with zero.
// - Returns the updated TickInfo.
//
// Returns:
// - TickInfo: The tick data with all fields guaranteed to have valid values (nil fields are set to zero).
//
// Use Case:
// This function ensures the retrieved tick data is always valid and safe for further operations,
// such as calculations or updates, by sanitizing nil fields in the TickInfo structure.
func getTick(p *pl.Pool, tick int32) pl.TickInfo {
	tickInfo, err := p.GetTick(tick)
	if err != nil {
		return pl.NewTickInfo()
	}

	return tickInfo
}

// mustGetTick retrieves the TickInfo for a specific tick, panicking if the tick does not exist.
//
// This function ensures that the requested tick data exists in the pool's tick mapping.
// If the tick does not exist, it panics with an appropriate error message.
//
// Parameters:
//   - tick: int32, the index of the tick to retrieve.
//
// Returns:
//   - TickInfo: The information associated with the specified tick.
//
// Behavior:
//   - Checks if the tick exists in the pool's tick mapping (`p.ticks`).
//   - If the tick exists, it returns the corresponding `TickInfo`.
//   - If the tick does not exist, the function panics with a descriptive error.
//
// Panic Conditions:
//   - The specified tick does not exist in the pool's mapping.
//
// Example:
//
// ```gno
//
//	tickInfo := pool.mustGetTick(10)
//	ufmt.Println("Tick Info:", tickInfo)
//
// ```
func mustGetTick(p *pl.Pool, tick int32) *pl.TickInfo {
	tickInfo, err := p.GetTick(tick)
	if err != nil {
		panic(err)
	}

	return &tickInfo
}

// calculateMaxLiquidityPerTick calculates the maximum liquidity
// per tick for a given tick spacing.
func calculateMaxLiquidityPerTick(tickSpacing int32) *u256.Uint {
	switch tickSpacing {
	case 1:
		return maxLiquidityPerTickSpacing1FromDec()
	case 10:
		return maxLiquidityPerTickSpacing10FromDec()
	case 60:
		return maxLiquidityPerTickSpacing60FromDec()
	case 200:
		return maxLiquidityPerTickSpacing200FromDec()
	default:
		minTick := (MIN_TICK / tickSpacing) * tickSpacing
		maxTick := (MAX_TICK / tickSpacing) * tickSpacing
		numTicks := uint64((maxTick-minTick)/tickSpacing) + 1

		return u256.Zero().Div(consts.MaxUint128(), u256.NewUint(numTicks))
	}
}

// getFeeGrowthBelowX128 calculates the fee growth below a specified tick.
//
// This function computes the fee growth for token 0 and token 1 below a given tick (`tickLower`)
// relative to the current tick (`tickCurrent`). The fee growth values are adjusted based on whether
// the `tickCurrent` is above or below the `tickLower`.
//
// Parameters:
//   - tickLower: int32, the lower tick boundary for fee calculation.
//   - tickCurrent: int32, the current tick index.
//   - feeGrowthGlobal0X128: *u256.Uint, the global fee growth for token 0 in X128 precision.
//   - feeGrowthGlobal1X128: *u256.Uint, the global fee growth for token 1 in X128 precision.
//   - lowerTick: TickInfo, the fee growth and liquidity details for the lower tick.
//
// Returns:
//   - *u256.Uint: Fee growth below `tickLower` for token 0.
//   - *u256.Uint: Fee growth below `tickLower` for token 1.
//
// Workflow:
//  1. If `tickCurrent` is greater than or equal to `tickLower`:
//     - Return the `feeGrowthOutside0X128` and `feeGrowthOutside1X128` values of the `lowerTick`.
//  2. If `tickCurrent` is below `tickLower`:
//     - Compute the fee growth below the lower tick by subtracting `feeGrowthOutside` values
//     from the global fee growth values (`feeGrowthGlobal0X128` and `feeGrowthGlobal1X128`).
//  3. Return the calculated fee growth values for both tokens.
//
// Behavior:
//   - If `tickCurrent >= tickLower`, the fee growth outside the lower tick is returned as-is.
//   - If `tickCurrent < tickLower`, the fee growth is calculated as:
//     feeGrowthBelow = feeGrowthGlobal - feeGrowthOutside
//
// Example:
//
// ```gno
//
//	feeGrowth0, feeGrowth1 := getFeeGrowthBelowX128(
//	    100, 150, globalFeeGrowth0, globalFeeGrowth1, lowerTickInfo,
//	)
//	println("Fee Growth Below:", feeGrowth0, feeGrowth1)
func getFeeGrowthBelowX128(
	tickLower, tickCurrent int32,
	feeGrowthGlobal0X128, feeGrowthGlobal1X128 *u256.Uint,
	lowerTick pl.TickInfo,
) (*u256.Uint, *u256.Uint) {
	feeOutside0 := u256.MustFromDecimal(lowerTick.FeeGrowthOutside0X128())
	feeOutside1 := u256.MustFromDecimal(lowerTick.FeeGrowthOutside1X128())

	if tickCurrent >= tickLower {
		return feeOutside0, feeOutside1
	}

	feeGrowthBelow0X128 := u256.Zero().Sub(feeGrowthGlobal0X128, feeOutside0)
	feeGrowthBelow1X128 := u256.Zero().Sub(feeGrowthGlobal1X128, feeOutside1)

	return feeGrowthBelow0X128, feeGrowthBelow1X128
}

// getFeeGrowthAboveX128 calculates the fee growth above a specified tick.
//
// This function computes the fee growth for token 0 and token 1 above a given tick (`tickUpper`)
// relative to the current tick (`tickCurrent`). The fee growth values are adjusted based on whether
// the `tickCurrent` is above or below the `tickUpper`.
//
// Parameters:
//   - tickUpper: int32, the upper tick boundary for fee calculation.
//   - tickCurrent: int32, the current tick index.
//   - feeGrowthGlobal0X128: *u256.Uint, the global fee growth for token 0 in X128 precision.
//   - feeGrowthGlobal1X128: *u256.Uint, the global fee growth for token 1 in X128 precision.
//   - upperTick: TickInfo, the fee growth and liquidity details for the upper tick.
//
// Returns:
//   - *u256.Uint: Fee growth above `tickUpper` for token 0.
//   - *u256.Uint: Fee growth above `tickUpper` for token 1.
//
// Workflow:
//  1. If `tickCurrent` is less than `tickUpper`:
//     - Return the `feeGrowthOutside0X128` and `feeGrowthOutside1X128` values of the `upperTick`.
//  2. If `tickCurrent` is greater than or equal to `tickUpper`:
//     - Compute the fee growth above the upper tick by subtracting `feeGrowthOutside` values
//     from the global fee growth values (`feeGrowthGlobal0X128` and `feeGrowthGlobal1X128`).
//  3. Return the calculated fee growth values for both tokens.
//
// Behavior:
//   - If `tickCurrent < tickUpper`, the fee growth outside the upper tick is returned as-is.
//   - If `tickCurrent >= tickUpper`, the fee growth is calculated as:
//     feeGrowthAbove = feeGrowthGlobal - feeGrowthOutside
//
// Example:
//
//	feeGrowth0, feeGrowth1 := getFeeGrowthAboveX128(
//	    200, 150, globalFeeGrowth0, globalFeeGrowth1, upperTickInfo,
//	)
//	println("Fee Growth Above:", feeGrowth0, feeGrowth1)
//
// ```
func getFeeGrowthAboveX128(
	tickUpper, tickCurrent int32,
	feeGrowthGlobal0X128, feeGrowthGlobal1X128 *u256.Uint,
	upperTick pl.TickInfo,
) (*u256.Uint, *u256.Uint) {
	feeOutside0 := u256.MustFromDecimal(upperTick.FeeGrowthOutside0X128())
	feeOutside1 := u256.MustFromDecimal(upperTick.FeeGrowthOutside1X128())

	if tickCurrent < tickUpper {
		return feeOutside0, feeOutside1
	}

	feeGrowthAbove0X128 := u256.Zero().Sub(feeGrowthGlobal0X128, feeOutside0)
	feeGrowthAbove1X128 := u256.Zero().Sub(feeGrowthGlobal1X128, feeOutside1)

	return feeGrowthAbove0X128, feeGrowthAbove1X128
}

// validateTicks validates the tick range for a liquidity position.
//
// This function performs three essential checks to ensure the provided
// tick values are valid before creating or modifying a liquidity position.
func validateTicks(tickLower, tickUpper int32) error {
	if tickLower >= tickUpper {
		return makeErrorWithDetails(
			errInvalidTickRange,
			ufmt.Sprintf("tickLower(%d), tickUpper(%d)", tickLower, tickUpper),
		)
	}

	if tickLower < MIN_TICK {
		return makeErrorWithDetails(
			errTickLowerInvalid,
			ufmt.Sprintf("tickLower(%d) < MIN_TICK(%d)", tickLower, MIN_TICK),
		)
	}

	if tickUpper > MAX_TICK {
		return makeErrorWithDetails(
			errTickUpperInvalid,
			ufmt.Sprintf("tickUpper(%d) > MAX_TICK(%d)", tickUpper, MAX_TICK),
		)
	}

	return nil
}

package pool

import (
	"gno.land/p/gnoswap/gnsmath/v1"
	u256 "gno.land/p/gnoswap/uint256/v1"
	pl "gno.land/r/gnoswap/pool"
)

// bitMask8 is used for efficient modulo 256 operations
const bitMask8 = 0xff // 256 - 1

// tickBitmapFlipTick flips the state of a tick in the tick bitmap.
//
// This function toggles the "initialized" state of a tick in the tick bitmap.
// It ensures that the tick aligns with the specified tick spacing and then
// flips the corresponding bit in the bitmap representation.
//
// Parameters:
//   - tick: int32, the tick index to toggle.
//   - tickSpacing: int32, the spacing between valid ticks.
//     The tick must align with this spacing.
//
// Workflow:
//  1. Validates that the `tick` aligns with `tickSpacing` using `checkTickSpacing`.
//  2. Computes the position of the bit in the tick bitmap:
//     - `wordPos`: Determines which word in the bitmap contains the bit.
//     - `bitPos`: Identifies the position of the bit within the word.
//  3. Creates a bitmask using `Lsh` (Left Shift) to target the bit at `bitPos`.
//  4. Toggles (flips) the bit using XOR with the current value of the tick bitmap.
//  5. Updates the tick bitmap with the modified word.
//
// Behavior:
//   - If the bit is `0` (uninitialized), it will be flipped to `1` (initialized).
//   - If the bit is `1` (initialized), it will be flipped to `0` (uninitialized).
//
// Example:
//
//	pool.tickBitmapFlipTick(120, 60)
//	// This flips the bit for tick 120 with a tick spacing of 60.
//
// Notes:
//   - The `tick` must be divisible by `tickSpacing`. If not, the function will panic.
func tickBitmapFlipTick(
	p *pl.Pool,
	tick int32,
	tickSpacing int32,
) {
	checkTickSpacing(tick, tickSpacing)
	wordPos, bitPos := tickBitmapPosition(tick / tickSpacing)

	mask := u256.Zero().Lsh(u256.One(), uint(bitPos))
	current := getTickBitmap(p, wordPos)
	next := u256.Zero().Xor(current, mask)
	if next.IsZero() {
		deleteTickBitmap(p, wordPos)
		return
	}

	setTickBitmap(p, wordPos, next)
}

// tickBitmapNextInitializedTickWithInOneWord finds the next initialized tick within
// one word of the bitmap.
func tickBitmapNextInitializedTickWithInOneWord(
	p *pl.Pool,
	tick int32,
	tickSpacing int32,
	lte bool,
) (int32, bool) {
	compress := tick / tickSpacing
	// Round towards negative infinity for negative ticks
	if tick < 0 && tick%tickSpacing != 0 {
		compress--
	}

	wordPos, bitPos := getWordAndBitPos(compress, lte)
	mask := getMaskBit(uint(bitPos), lte)
	masked := u256.Zero().And(getTickBitmap(p, wordPos), mask)
	initialized := !masked.IsZero()

	nextTick := getNextTick(lte, initialized, compress, bitPos, tickSpacing, masked)
	return nextTick, initialized
}

// getTickBitmap gets the tick bitmap for the given word position.
// Missing words are implicit zeroes.
func getTickBitmap(p *pl.Pool, wordPos int16) *u256.Uint {
	value, exist := p.TickBitmaps()[wordPos]
	if !exist {
		return u256.Zero()
	}

	return u256.MustFromDecimal(value)
}

// setTickBitmap sets the tick bitmap for the given word position.
func setTickBitmap(p *pl.Pool, wordPos int16, tickBitmap *u256.Uint) {
	p.SetTickBitmap(wordPos, tickBitmap.ToString())
}

// deleteTickBitmap deletes the tick bitmap for the given word position.
func deleteTickBitmap(p *pl.Pool, wordPos int16) {
	p.DeleteTickBitmap(wordPos)
}

// tickBitmapPosition calculates the word and bit position for a given tick
func tickBitmapPosition(tick int32) (int16, uint8) {
	return int16(tick >> 8), uint8(tick) & bitMask8
}

// getWordAndBitPos gets tick's wordPos and bitPos depending on the swap direction
func getWordAndBitPos(tick int32, lte bool) (int16, uint8) {
	if !lte {
		tick++
	}
	return tickBitmapPosition(tick)
}

// getMaskBit generates a mask based on the provided bit position (bitPos) and a boolean flag (lte).
// The function constructs a bitmask with a shift depending on the bit position and the boolean value.
// It either returns the mask or its negation, based on the value of 'lte' (swap direction).
//
// NOTE: should always use a newly created `u256.One()` object.
func getMaskBit(bitPos uint, lte bool) *u256.Uint {
	if lte {
		if bitPos == bitMask8 {
			return u256.Zero().SetAllOne()
		}
		return u256.Zero().Sub(u256.Zero().Lsh(u256.One(), bitPos+1), u256.One())
	}
	if bitPos == 0 {
		return u256.Zero().SetAllOne()
	}
	return u256.Zero().Not(u256.Zero().Sub(u256.Zero().Lsh(u256.One(), bitPos), u256.One()))
}

// getNextTick gets the next tick depending on the initialized state and the swap direction
func getNextTick(lte, initialized bool, compress int32, bitPos uint8, tickSpacing int32, masked *u256.Uint) int32 {
	if initialized {
		return getTickIfInitialized(compress, tickSpacing, bitPos, masked, lte)
	}
	return getTickIfNotInitialized(compress, tickSpacing, bitPos, lte)
}

// getTickIfInitialized gets the next tick if the tick bitmap is initialized
func getTickIfInitialized(compress, tickSpacing int32, bitPos uint8, masked *u256.Uint, lte bool) int32 {
	if lte {
		return (compress - int32(bitPos-gnsmath.BitMathMostSignificantBit(masked))) * tickSpacing
	}
	return (compress + 1 + int32(gnsmath.BitMathLeastSignificantBit(masked)-bitPos)) * tickSpacing
}

// getTickIfNotInitialized gets the next tick if the tick bitmap is not initialized
func getTickIfNotInitialized(compress, tickSpacing int32, bitPos uint8, lte bool) int32 {
	if lte {
		return (compress - int32(bitPos)) * tickSpacing
	}
	return (compress + 1 + int32(bitMask8-bitPos)) * tickSpacing
}

package pool

import (
	ufmt "gno.land/p/nt/ufmt/v0"

	prabc "gno.land/p/gnoswap/rbac/v1"

	"gno.land/r/gnoswap/access/v1"
	"gno.land/r/gnoswap/common"
	pl "gno.land/r/gnoswap/pool"

	"gno.land/p/gnoswap/gnsmath/v1"
	i256 "gno.land/p/gnoswap/int256/v1"
	u256 "gno.land/p/gnoswap/uint256/v1"
)

// safeTransfer performs a token transfer out of the pool while ensuring
// the pool has sufficient balance and updating internal accounting.
// This function is typically used during swaps and liquidity removals.
//
// Important requirements:
//   - The amount must be a positive value representing tokens to transfer out
//   - The pool must have sufficient balance for the transfer
//   - The transfer amount must fit within int64 range
//
// Parameters:
//   - p: the pool instance
//   - to: destination address for the transfer
//   - tokenPath: path identifier of the token to transfer
//   - amount: amount to transfer (positive u256.Uint value)
//   - isToken0: true if transferring token0, false for token1
//
// The function will:
//  1. Check pool has sufficient balance
//  2. Execute the transfer
//  3. Subtract the amount from pool's internal balance
//
// Panics if any validation fails or if the transfer fails
func (i *poolV1) safeTransfer(
	_ int,
	rlm realm,
	p *pl.Pool,
	to address,
	tokenPath string,
	amount *u256.Uint,
	isToken0 bool,
) {
	token0 := p.BalanceToken0()
	token1 := p.BalanceToken1()
	amountInt64 := gnsmath.SafeConvertToInt64(amount)

	if err := validatePoolBalance(token0, token1, amountInt64, isToken0); err != nil {
		panic(err)
	}

	common.SafeGRC20Transfer(0, rlm, tokenPath, to, amountInt64)

	newBalance, err := updatePoolBalance(token0, token1, amountInt64, isToken0)
	if err != nil {
		panic(err)
	}

	poolBalances := p.Balances()

	if isToken0 {
		poolBalances.SetToken0(newBalance)
	} else {
		poolBalances.SetToken1(newBalance)
	}

	p.SetBalances(poolBalances)
}

// safeTransferFrom securely transfers tokens into the pool while ensuring balance consistency.
//
// This function performs the following steps:
// 1. Validates and converts the transfer amount to `int64` using `gnsmath.SafeConvertToInt64`.
// 2. Executes the token transfer using `TransferFrom` via the token teller contract.
// 3. Verifies that the destination balance reflects the correct amount after transfer.
// 4. Updates the pool's internal balances (`token0` or `token1`) and validates the updated state.
//
// Parameters:
// - p (*pl.Pool): The pool instance to transfer tokens into.
// - from (address): Source address for the token transfer.
// - to (address): Destination address, typically the pool address.
// - tokenPath (string): Path identifier for the token being transferred.
// - amount (*u256.Uint): The amount of tokens to transfer (must be a positive value).
// - isToken0 (bool): A flag indicating whether the token being transferred is token0 (`true`) or token1 (`false`).
//
// Panics:
// - If the `amount` exceeds the int64 range during conversion.
// - If the token transfer (`TransferFrom`) fails.
// - If the destination balance after the transfer does not match the expected amount.
// - If the pool's internal balances (`token0` or `token1`) overflow or become inconsistent.
//
// Notes:
// - The function assumes that the sender (`from`) has approved the pool to spend the specified tokens.
// - The balance consistency check ensures that no tokens are lost or double-counted during the transfer.
// - Pool balance updates are performed atomically to ensure internal consistency.
func (i *poolV1) safeTransferFrom(
	_ int,
	rlm realm,
	p *pl.Pool,
	from, to address,
	tokenPath string,
	amount *u256.Uint,
	isToken0 bool,
) {
	amountInt64 := gnsmath.SafeConvertToInt64(amount)

	beforeBalance := common.BalanceOf(tokenPath, to)

	common.SafeGRC20TransferFrom(0, rlm, tokenPath, from, to, amountInt64)

	afterBalance := common.BalanceOf(tokenPath, to)
	if gnsmath.SafeAddInt64(beforeBalance, amountInt64) != afterBalance {
		panic(ufmt.Sprintf(
			"%v. beforeBalance(%d) + amount(%d) != afterBalance(%d)",
			errTransferFailed, beforeBalance, amountInt64, afterBalance,
		))
	}

	poolBalances := p.Balances()

	// update pool balances
	if isToken0 {
		poolBalances.SetToken0(gnsmath.SafeAddInt64(poolBalances.Token0(), amountInt64))
	} else {
		poolBalances.SetToken1(gnsmath.SafeAddInt64(poolBalances.Token1(), amountInt64))
	}

	p.SetBalances(poolBalances)
}

// safeSwapCallback executes a swap callback and validates the token payment.
//
// This function implements the flash swap pattern where the pool first sends output tokens
// to the recipient, then invokes the callback to receive input tokens from the caller.
// The callback is responsible for transferring the required input tokens to the pool.
//
// Callback Signature:
//
//	func(cur realm, amount0Delta, amount1Delta int64, _ *pool.CallbackMarker) error
//
// Delta Convention (following Uniswap V3 standard):
//   - Positive delta: Amount the pool must RECEIVE (input token)
//   - Negative delta: Amount the pool has SENT (output token)
//
// For zeroForOne swaps (token0 → token1):
//   - amount0Delta > 0: Pool receives token0 (input)
//   - amount1Delta < 0: Pool sends token1 (output)
//
// For oneForZero swaps (token1 → token0):
//   - amount0Delta < 0: Pool sends token0 (output)
//   - amount1Delta > 0: Pool receives token1 (input)
//
// Parameters:
//   - p: The pool instance
//   - tokenPath: Path of the input token that pool must receive
//   - amountInInt256: Amount pool must receive (positive i256.Int)
//   - amountOutInt256: Amount pool has sent (negative i256.Int)
//   - zeroForOne: Swap direction (true = token0 to token1)
//   - swapCallback: Callback function that must transfer input tokens to pool
//
// The callback needed:
//  1. Verify the caller is the legitimate pool contract address to prevent unauthorized invocations
//  2. Transfer at least `amountIn` of input tokens to the pool
//  3. Return nil on success, or an error to revert the swap
//
// Example callback implementation:
//
//	func(cur realm, amount0Delta, amount1Delta int64, _ *pool.CallbackMarker) error {
//	    // Security check: ensure this callback is invoked by the legitimate pool
//	    caller := runtime.PreviousRealm().Address()
//	    poolAddr := chain.PackageAddress("gno.land/r/gnoswap/pool")
//
//	    if caller != poolAddr {
//	        panic("unauthorized caller")
//	    }
//
//	    if amount0Delta > 0 {
//	        // Transfer token0 to pool
//	        token0.Transfer(cross, poolAddr, amount0Delta)
//	    }
//	    if amount1Delta > 0 {
//	        // Transfer token1 to pool
//	        token1.Transfer(cross, poolAddr, amount1Delta)
//	    }
//	    return nil
//	}
func (i *poolV1) safeSwapCallback(
	_ int,
	rlm realm,
	p *pl.Pool,
	tokenPath string,
	amountInInt256 *i256.Int,
	amountOutInt256 *i256.Int,
	zeroForOne bool,
	swapCallback func(cur realm, amount0Delta, amount1Delta int64, _ *pl.CallbackMarker) error,
) {
	if swapCallback == nil {
		panic(makeErrorWithDetails(
			errInvalidInput,
			"swapCallback is nil",
		))
	}

	currentAddress := access.MustGetAddress(prabc.ROLE_POOL.String())

	amountIn := amountInInt256.Int64()
	amountOut := amountOutInt256.Int64()
	balanceBefore := common.BalanceOf(tokenPath, currentAddress)

	// Make callback to the calling contract
	// The contract should transfer tokens to pool within this callback
	// Following Uniswap V3 convention:
	// - Positive delta: amount the pool must receive (input token)
	// - Negative delta: amount the pool has sent (output token)
	var amount0Delta, amount1Delta, beforeTokenBalance int64

	if zeroForOne {
		// zeroForOne: pool receives token0 (positive), sends token1 (negative)
		amount0Delta = amountIn
		amount1Delta = amountOut
		beforeTokenBalance = p.BalanceToken0()
	} else {
		// !zeroForOne: pool receives token1 (positive), sends token0 (negative)
		amount0Delta = amountOut
		amount1Delta = amountIn
		beforeTokenBalance = p.BalanceToken1()
	}

	// execute swap callback
	// CallbackMarker is created by the pool module to enforce type-system level validation.
	// Allocation goes through pl.NewCallbackMarker so the alloc happens in pool realm
	// (interrealm v2 forbids /r/-declared types being constructed outside their owner).
	err := swapCallback(cross(rlm), amount0Delta, amount1Delta, pl.NewCallbackMarker())
	if err != nil {
		panic(err)
	}

	balanceAfter := common.BalanceOf(tokenPath, currentAddress)
	balanceIncrease := gnsmath.SafeSubInt64(balanceAfter, balanceBefore)

	// check insufficient payment by swap callback
	if balanceIncrease < amountIn {
		panic(makeErrorWithDetails(
			errInsufficientPayment,
			ufmt.Sprintf("insufficient payment: expected %d, received %d", amountIn, balanceIncrease),
		))
	}

	// check overflow update pool balance
	resultTokenBalance := gnsmath.SafeAddInt64(beforeTokenBalance, amountIn)

	poolBalances := p.Balances()

	if zeroForOne {
		poolBalances.SetToken0(resultTokenBalance)
	} else {
		poolBalances.SetToken1(resultTokenBalance)
	}

	p.SetBalances(poolBalances)
}

// validatePoolBalance checks if the pool has sufficient balance of either token0 and token1
// before proceeding with a transfer. This prevents the pool won't go into a negative balance.
func validatePoolBalance(token0, token1, amount int64, isToken0 bool) error {
	if amount < 0 {
		return ufmt.Errorf("%v. amount(%d) must be positive", errTransferFailed, amount)
	}

	if isToken0 {
		if token0 < amount {
			return ufmt.Errorf(
				"%v. token0(%d) >= amount(%d)",
				errTransferFailed, token0, amount,
			)
		}
		return nil
	}
	if token1 < amount {
		return ufmt.Errorf(
			"%v. token1(%d) >= amount(%d)",
			errTransferFailed, token1, amount,
		)
	}
	return nil
}

// updatePoolBalance calculates the new balance after a transfer and validate.
// It ensures the resulting balance won't be negative or overflow.
func updatePoolBalance(
	token0, token1, amount int64,
	isToken0 bool,
) (int64, error) {
	if amount < 0 {
		return 0, ufmt.Errorf("%v. amount(%d) must be positive", errBalanceUpdateFailed, amount)
	}

	if isToken0 {
		if token0 < amount {
			return 0, ufmt.Errorf(
				"%v. cannot decrease, token0(%d) - amount(%d)",
				errBalanceUpdateFailed, token0, amount,
			)
		}
		return gnsmath.SafeSubInt64(token0, amount), nil
	}

	if token1 < amount {
		return 0, ufmt.Errorf(
			"%v. cannot decrease, token1(%d) - amount(%d)",
			errBalanceUpdateFailed, token1, amount,
		)
	}
	return gnsmath.SafeSubInt64(token1, amount), nil
}

package pool

import (
	"gno.land/p/gnoswap/gnsmath/v1"
	i256 "gno.land/p/gnoswap/int256/v1"
	u256 "gno.land/p/gnoswap/uint256/v1"

	pl "gno.land/r/gnoswap/pool"
)

// ModifyPositionParams repersents the parameters for modifying a liquidity position.
// This structure is used internally both `Mint` and `Burn` operation to manage
// the liquidity positions.
type ModifyPositionParams struct {
	// owner is the address that owns the position
	owner address

	// tickLower and atickUpper define the price range
	// The actual price range is calculated as 1.0001^tick
	// This allows for precision in price range while using integer math.

	tickLower int32 // lower tick of the position
	tickUpper int32 // upper tick of the position

	// liquidityDelta represents the change in liquidity
	// Positive for minting, negative for burning
	liquidityDelta *i256.Int
}

// newModifyPositionParams creates a new `ModifyPositionParams` instance.
// This is used to preare parameters for the `modifyPosition` function,
// which handles both minting and burning of liquidity positions.
//
// Parameters:
//   - owner: address that will own (or owns) the position
//   - tickLower: lower tick bound of the position
//   - tickUpper: upper tick bound of the position
//   - liquidityDelta: amount of liquidity to add (positive) or remove (negative)
//
// The tick parameters represent prices as powers of 1.0001:
// - actual_price = 1.0001^tick
// - For example, tick = 100 means price = 1.0001^100
//
// Returns:
//   - ModifyPositionParams: a new instance of ModifyPositionParams
func newModifyPositionParams(
	owner address,
	tickLower int32,
	tickUpper int32,
	liquidityDelta *i256.Int,
) ModifyPositionParams {
	return ModifyPositionParams{
		owner:          owner,
		tickLower:      tickLower,
		tickUpper:      tickUpper,
		liquidityDelta: liquidityDelta,
	}
}

// SwapCache holds immutable swap-start inputs and oracle cumulatives that are
// populated lazily when the swap first crosses an initialized tick.
type SwapCache struct {
	feeProtocol                       uint8      // protocol fee for the input token
	liquidityStart                    *u256.Uint // liquidity at the beginning of the swap
	blockTimestamp                    int64      // current block timestamp
	tickCumulative                    int64      // current tick accumulator value
	secondsPerLiquidityCumulativeX128 *u256.Uint // current seconds per liquidity accumulator
	computedLatestObservation         bool       // whether we've computed the above accumulators
	slot0Start                        pl.Slot0   // immutable Slot0 snapshot captured at swap start
	readOnly                          bool       // quote without tick accounting or hooks
}

func newSwapCache(
	feeProtocol uint8,
	liquidityStart *u256.Uint,
	blockTimestamp int64,
	slot0Start pl.Slot0,
) *SwapCache {
	return &SwapCache{
		feeProtocol:                       feeProtocol,
		liquidityStart:                    liquidityStart,
		blockTimestamp:                    blockTimestamp,
		tickCumulative:                    0,
		secondsPerLiquidityCumulativeX128: u256.Zero(),
		computedLatestObservation:         false,
		slot0Start:                        slot0Start.Clone(),
	}
}

// SwapState tracks the changing values during a swap.
// This type helps manage the state transitions that occur as the swap progresses
// across different price ranges.
type SwapState struct {
	amountSpecifiedRemaining *i256.Int  // amount remaining to be swapped in/out of the input/output token
	amountCalculated         *i256.Int  // amount already swapped out/in of the output/input token
	sqrtPriceX96             *u256.Uint // current sqrt(price)
	tick                     int32      // tick associated with the current sqrt(price)
	feeGrowthGlobalX128      *u256.Uint // global fee growth of the input token
	protocolFee              *u256.Uint // amount of input token paid as protocol fee
	liquidity                *u256.Uint // current liquidity in range
}

func newSwapState(
	amountSpecifiedRemaining *i256.Int,
	feeGrowthGlobalX128 *u256.Uint,
	liquidity *u256.Uint,
	slot0 pl.Slot0,
) SwapState {
	return SwapState{
		amountSpecifiedRemaining: amountSpecifiedRemaining,
		amountCalculated:         i256.Zero(),
		sqrtPriceX96:             slot0.SqrtPriceX96(),
		tick:                     slot0.Tick(),
		feeGrowthGlobalX128:      feeGrowthGlobalX128,
		protocolFee:              u256.Zero(),
		liquidity:                liquidity,
	}
}

func (s *SwapState) setSqrtPriceX96(sqrtPriceX96 *u256.Uint) {
	s.sqrtPriceX96 = sqrtPriceX96.Clone()
}

func (s *SwapState) setTick(tick int32) {
	s.tick = tick
}

func (s *SwapState) setFeeGrowthGlobalX128(feeGrowthGlobalX128 *u256.Uint) {
	s.feeGrowthGlobalX128 = feeGrowthGlobalX128
}

func (s *SwapState) setProtocolFee(fee *u256.Uint) {
	s.protocolFee = fee
}

// StepComputations holds intermediate values used during a single step of a swap.
// Each step represents movement from the current tick to the next initialized tick
// or the target price, whichever comes first.
type StepComputations struct {
	sqrtPriceStartX96 *u256.Uint // price at the beginning of the step
	tickNext          int32      // next tick to swap to from the current tick in the swap direction
	initialized       bool       // whether tickNext is initialized
	sqrtPriceNextX96  *u256.Uint // sqrt(price) for the next tick (token1/token0) Q96
	amountIn          *u256.Uint // how much being swapped in this step
	amountOut         *u256.Uint // how much is being swapped out in this step
	feeAmount         *u256.Uint // how much fee is being paid in this step
}

// init initializes the computation for a single swap step
func (step *StepComputations) initSwapStep(state SwapState, p *pl.Pool, zeroForOne bool) {
	step.sqrtPriceStartX96 = state.sqrtPriceX96
	step.tickNext, step.initialized = tickBitmapNextInitializedTickWithInOneWord(
		p,
		state.tick,
		p.TickSpacing(),
		zeroForOne,
	)

	// prevent overshoot the min/max tick
	step.clampTickNext()

	// get the price for the next tick
	step.sqrtPriceNextX96 = gnsmath.TickMathGetSqrtRatioAtTick(step.tickNext)
}

// clampTickNext ensures that `tickNext` stays within the min, max tick boundaries
// as the tick bitmap is not aware of these bounds
func (step *StepComputations) clampTickNext() {
	if step.tickNext < MIN_TICK {
		step.tickNext = MIN_TICK
	} else if step.tickNext > MAX_TICK {
		step.tickNext = MAX_TICK
	}
}

func newPool(poolInfo *poolCreateConfig) *pl.Pool {
	tick := gnsmath.TickMathGetTickAtSqrtRatio(poolInfo.SqrtPriceX96())

	return pl.NewPool(
		poolInfo.Token0Path(),
		poolInfo.Token1Path(),
		poolInfo.Fee(),
		poolInfo.SqrtPriceX96(),
		poolInfo.TickSpacing(),
		tick,
		poolInfo.slot0FeeProtocol,
	)
}

package pool

import (
	i256 "gno.land/p/gnoswap/int256/v1"
	u256 "gno.land/p/gnoswap/uint256/v1"
	ufmt "gno.land/p/nt/ufmt/v0"
)

const (
	MAX_UINT64  string = "18446744073709551615"
	MAX_INT64   string = "9223372036854775807"
	MAX_INT128  string = "170141183460469231731687303715884105727"
	MIN_INT128  string = "-170141183460469231731687303715884105728"
	MAX_UINT128 string = "340282366920938463463374607431768211455"
	MAX_INT256  string = "57896044618658097711785492504343953926634992332820282019728792003956564819967"

	INT64_MIN int64 = -9223372036854775808
	INT64_MAX int64 = 9223372036854775807

	Q96_RESOLUTION  uint = 96
	Q128_RESOLUTION uint = 128

	Q64  string = "18446744073709551616"                    // 2 ** 64
	Q96  string = "79228162514264337593543950336"           // 2 ** 96
	Q128 string = "340282366920938463463374607431768211456" // 2 ** 128
)

var (
	maxInt128FromDecimal  = i256.MustFromDecimal(MAX_INT128)
	minInt128FromDecimal  = i256.MustFromDecimal(MIN_INT128)
	maxUint128FromDecimal = u256.MustFromDecimal(MAX_UINT128)
	q128FromDecimal       = u256.MustFromDecimal(Q128)
)

var uint128Mask = func() *u256.Uint {
	m := u256.Zero().Lsh(u256.One(), Q128_RESOLUTION)
	return m.Sub(m, u256.One())
}()

// toUint128 ensures a *u256.Uint value fits within the uint128 range.
//
// This function validates that the given `value` is properly initialized and checks whether
// it exceeds the maximum value of uint128. If the value exceeds the uint128 range,
// it applies a masking operation to truncate the value to fit within the uint128 limit.
//
// Parameters:
//   - value: *u256.Uint, the value to be checked and possibly truncated.
//
// Returns:
//   - *u256.Uint: A value guaranteed to fit within the uint128 range.
//
// Notes:
//   - The function first checks if the value is not nil to avoid potential runtime errors.
//   - The mask ensures that only the lower 128 bits of the value are retained.
//   - If the input value is already within the uint128 range, it is returned unchanged.
//   - If masking is required, a new instance is returned without modifying the input.
//   - MAX_UINT128 is a constant representing `2^128 - 1`.
func toUint128(value *u256.Uint) *u256.Uint {
	if value == nil {
		panic(newErrorWithDetail(errInvalidInput, "value is nil"))
	}

	if value.Gt(maxUint128FromDecimal) {
		return u256.Zero().And(value, uint128Mask)
	}
	return value
}

// u256Min returns the smaller of two *u256.Uint values.
//
// This function compares two unsigned 256-bit integers and returns the smaller of the two.
// If `num1` is less than `num2`, it returns `num1`; otherwise, it returns `num2`.
//
// Parameters:
// - num1 (*u256.Uint): The first unsigned 256-bit integer.
// - num2 (*u256.Uint): The second unsigned 256-bit integer.
//
// Returns:
// - *u256.Uint: The smaller of `num1` and `num2`.
//
// Notes:
//   - This function uses the `Lt` (less than) method of `*u256.Uint` to perform the comparison.
//   - The function assumes both input values are non-nil. If nil inputs are possible in the usage context,
//     additional validation may be needed.
//
// Example:
// smaller := u256Min(u256.MustFromDecimal("10"), u256.MustFromDecimal("20")) // Returns 10
// smaller := u256Min(u256.MustFromDecimal("30"), u256.MustFromDecimal("20")) // Returns 20
func u256Min(num1, num2 *u256.Uint) *u256.Uint {
	if num1.Lt(num2) {
		return num1
	}
	return num2
}

// checkOverFlowInt128 checks if the value overflows the int128 range.
func checkOverFlowInt128(value *i256.Int) {
	if value.Gt(maxInt128FromDecimal) || value.Lt(minInt128FromDecimal) {
		panic(ufmt.Sprintf(
			"%v: amount(%s) overflows int128 range",
			errOverflow, value.ToString(),
		))
	}
}

// checkTickSpacing checks if the tick is divisible by the tickSpacing.
func checkTickSpacing(tick, tickSpacing int32) {
	if tick%tickSpacing != 0 {
		panic(newErrorWithDetail(
			errInvalidTickAndTickSpacing,
			ufmt.Sprintf("tick(%d) MOD tickSpacing(%d) != 0(%d)", tick, tickSpacing, tick%tickSpacing),
		))
	}
}

package position

import (
	"errors"
	"time"

	u256 "gno.land/p/gnoswap/uint256/v1"
	ufmt "gno.land/p/nt/ufmt/v0"

	prbac "gno.land/p/gnoswap/rbac/v1"
	"gno.land/r/gnoswap/access/v1"
)

// assertIsNotExpired panics if the deadline is expired.
func assertIsNotExpired(deadline int64) {
	now := time.Now().Unix()

	if now > deadline {
		panic(makeErrorWithDetails(
			errExpired,
			ufmt.Sprintf("transaction too old, now(%d) > deadline(%d)", now, deadline),
		))
	}
}

// assertValidNumberString panics if the input string does not represent a valid integer.
func assertValidNumberString(input string) {
	if len(input) == 0 {
		panic(newErrorWithDetail(errInvalidInput, "input is empty"))
	}

	bytes := []byte(input)
	for i, b := range bytes {
		if i == 0 && b == '-' {
			continue // Allow if the first character is a negative sign (-)
		}
		if b < '0' || b > '9' {
			panic(newErrorWithDetail(
				errInvalidInput,
				ufmt.Sprintf("input string : %s", input)))
		}
	}
}

// assertValidLiquidityAmount panics if the liquidity amount is zero.
func assertValidLiquidityAmount(liquidity string) {
	if u256.MustFromDecimal(liquidity).IsZero() {
		panic(newErrorWithDetail(
			errZeroLiquidity,
			ufmt.Sprintf("liquidity amount must be greater than 0, got %s", liquidity),
		))
	}
}

// assertExistsPosition panics if the position does not exist.
func assertExistsPosition(p *positionV1, positionId uint64) {
	if !p.exists(positionId) {
		panic(newErrorWithDetail(
			errPositionDoesNotExist,
			ufmt.Sprintf("position with position ID(%d) doesn't exist", positionId),
		))
	}
}

// assertIsOwnerForToken panics if caller is not the owner of the position.
func assertIsOwnerForToken(p *positionV1, positionId uint64, caller address) {
	assertExistsPosition(p, positionId)

	if !p.isOwner(positionId, caller) {
		panic(newErrorWithDetail(
			errNoPermission,
			ufmt.Sprintf("caller(%s) is not owner of positionId(%d)", caller, positionId),
		))
	}
}

// assertIsOwnerOrOperatorForToken panics if caller is not the owner or operator of the position.
func assertIsOwnerOrOperatorForToken(p *positionV1, positionId uint64, caller address) {
	assertExistsPosition(p, positionId)

	if !p.isOwnerOrOperator(positionId, caller) {
		panic(newErrorWithDetail(
			errNoPermission,
			ufmt.Sprintf("caller(%s) is not owner or approved operator of positionId(%d)", caller, positionId),
		))
	}
}

// assertEqualsAddress panics if addresses are invalid or not equal.
func assertEqualsAddress(prevAddr, otherAddr address) {
	access.AssertIsValidAddress(prevAddr)
	access.AssertIsValidAddress(otherAddr)

	if prevAddr != otherAddr {
		panic(newErrorWithDetail(
			errInvalidAddress,
			ufmt.Sprintf("(%s, %s)", prevAddr, otherAddr),
		))
	}
}

// assertValidOperatorAddress validates operator address.
// Empty address is allowed (for operator removal), but non-empty addresses must be valid.
func assertValidOperatorAddress(operator address) {
	if operator != address("") && !operator.IsValid() {
		panic(newErrorWithDetail(errInvalidAddress, ufmt.Sprintf("operator(%s)", operator)))
	}
}

// assertIsNotMintToStaker panics if the mintTo address is staker.
func assertIsNotMintToStaker(mintTo address) {
	stakerAddr := access.MustGetAddress(prbac.ROLE_STAKER.String())
	if mintTo == stakerAddr {
		panic(errors.New(errCannotMintToStaker))
	}
}

package position

import (
	"errors"

	"gno.land/p/gnoswap/consts/v1"
	"gno.land/p/gnoswap/gnsmath/v1"
	u256 "gno.land/p/gnoswap/uint256/v1"
	"gno.land/p/gnoswap/utils/v1"
	ufmt "gno.land/p/nt/ufmt/v0"

	pl "gno.land/r/gnoswap/pool"
	"gno.land/r/gnoswap/position"
)

// decreaseLiquidity reduces position liquidity and collects fees.
// Returns positionId, liquidity, fee0, fee1, amount0, amount1, poolPath.
func (p *positionV1) decreaseLiquidity(_ int, rlm realm, params DecreaseLiquidityParams) (uint64, string, string, string, string, string, string, error) {
	caller := params.caller

	// before decrease liquidity, collect fee first
	_, fee0Str, fee1Str, _, _, _ := p.collectFee(0, rlm, params.positionId, params.caller)

	position := p.mustGetPosition(params.positionId)
	positionLiquidity := u256.MustFromDecimal(position.Liquidity())
	if positionLiquidity.IsZero() {
		return params.positionId,
			"",
			fee0Str,
			fee1Str,
			"", "",
			position.PoolKey(),
			makeErrorWithDetails(
				errZeroLiquidity,
				ufmt.Sprintf("position(position ID:%d) has 0 liquidity", params.positionId),
			)
	}

	liquidityToRemove := u256.MustFromDecimal(params.liquidity)

	if liquidityToRemove.Gt(positionLiquidity) {
		return params.positionId,
			liquidityToRemove.ToString(),
			fee0Str,
			fee1Str,
			"", "",
			position.PoolKey(),
			makeErrorWithDetails(
				errInvalidLiquidity,
				ufmt.Sprintf("Liquidity requested(%s) is greater than liquidity held(%s)", liquidityToRemove.ToString(), positionLiquidity.ToString()),
			)
	}

	pToken0, pToken1, pFee := splitOf(position.PoolKey())
	burn0, burn1 := pl.Burn(cross(rlm), pToken0, pToken1, pFee, position.TickLower(), position.TickUpper(), liquidityToRemove.ToString(), caller)

	burnedAmount0 := utils.SafeParseInt64(burn0)
	burnedAmount1 := utils.SafeParseInt64(burn1)

	if burnedAmount0 < 0 || burnedAmount1 < 0 {
		panic(errors.New(errUnderflow))
	}

	positionKey := computePositionKey(position.TickLower(), position.TickUpper())
	feeGrowthInside0LastX128Str, feeGrowthInside1LastX128Str, err := pl.GetPositionFeeGrowthInsideLastX128(position.PoolKey(), positionKey)
	if err != nil {
		return 0, "", "", "", "", "", position.PoolKey(), err
	}

	// Add only burned amounts to tokensOwed since fees were already collected and processed in collectFee
	tokensOwed0 := gnsmath.SafeAddInt64(position.TokensOwed0(), burnedAmount0)
	tokensOwed1 := gnsmath.SafeAddInt64(position.TokensOwed1(), burnedAmount1)

	newLiquidity, underflow := u256.Zero().SubOverflow(positionLiquidity, liquidityToRemove)
	if underflow {
		panic(newErrorWithDetail(errUnderflow, "positionLiquidity - liquidityToRemove underflow"))
	}

	position.SetTokensOwed0(tokensOwed0)
	position.SetTokensOwed1(tokensOwed1)
	position.SetFeeGrowthInside0LastX128(feeGrowthInside0LastX128Str)
	position.SetFeeGrowthInside1LastX128(feeGrowthInside1LastX128Str)
	position.SetLiquidity(newLiquidity.ToString())

	p.mustUpdatePosition(0, rlm, params.positionId, *position)

	collect0, collect1 := pl.Collect(
		cross(rlm),
		pToken0,
		pToken1,
		pFee,
		caller,
		position.TickLower(),
		position.TickUpper(),
		burn0,
		burn1,
	)

	collectAmount0 := u256.MustFromDecimal(collect0)
	collectAmount1 := u256.MustFromDecimal(collect1)

	// Slippage check on actually collected amounts to ensure user receives minimum expected tokens
	if isSlippageExceeded(collectAmount0, collectAmount1, params.amount0Min, params.amount1Min) {
		return params.positionId,
			liquidityToRemove.ToString(),
			fee0Str,
			fee1Str,
			collect0,
			collect1,
			position.PoolKey(),
			makeErrorWithDetails(
				errSlippage,
				ufmt.Sprintf("collectAmount0(%s) >= amount0Min(%s) && collectAmount1(%s) >= amount1Min(%s)",
					collectAmount0.ToString(),
					params.amount0Min.ToString(),
					collectAmount1.ToString(),
					params.amount1Min.ToString(),
				),
			)
	}

	// Check for underflow when subtracting collected amounts from tokens owed
	collectAmount0Int64 := gnsmath.SafeConvertToInt64(collectAmount0)
	collectAmount1Int64 := gnsmath.SafeConvertToInt64(collectAmount1)

	if position.TokensOwed0() < collectAmount0Int64 {
		panic(ufmt.Sprintf("[POSITION] burn.gno | collect() | tokensOwed0(%d) < collectAmount0(%d)", position.TokensOwed0(), collectAmount0Int64))
	}
	position.SetTokensOwed0(gnsmath.SafeSubInt64(position.TokensOwed0(), collectAmount0Int64))

	if position.TokensOwed1() < collectAmount1Int64 {
		panic(ufmt.Sprintf("[POSITION] burn.gno | collect() | tokensOwed1(%d) < collectAmount1(%d)", position.TokensOwed1(), collectAmount1Int64))
	}
	position.SetTokensOwed1(gnsmath.SafeSubInt64(position.TokensOwed1(), collectAmount1Int64))

	if position.IsClear() {
		position.SetBurned(true) // just update flag (we don't want to burn actual position)
	}

	p.mustUpdatePosition(0, rlm, params.positionId, *position)

	return params.positionId, liquidityToRemove.ToString(), fee0Str, fee1Str, collect0, collect1, position.PoolKey(), nil
}

// calculateFees calculates the fees for the current position.
func (p *positionV1) calculateFees(position *position.Position, currentFeeGrowth FeeGrowthInside) (int64, int64) {
	posLiquidity := u256.MustFromDecimal(position.Liquidity())
	fee0 := calculateTokensOwed(
		currentFeeGrowth.feeGrowthInside0LastX128,
		u256.MustFromDecimal(position.FeeGrowthInside0LastX128()),
		posLiquidity,
	)

	fee1 := calculateTokensOwed(
		currentFeeGrowth.feeGrowthInside1LastX128,
		u256.MustFromDecimal(position.FeeGrowthInside1LastX128()),
		posLiquidity,
	)

	return gnsmath.SafeAddInt64(position.TokensOwed0(), gnsmath.SafeConvertToInt64(fee0)), gnsmath.SafeAddInt64(position.TokensOwed1(), gnsmath.SafeConvertToInt64(fee1))
}

func calculateTokensOwed(
	feeGrowthInsideLastX128 *u256.Uint,
	positionFeeGrowthInsideLastX128 *u256.Uint,
	positionLiquidity *u256.Uint,
) *u256.Uint {
	diff := u256.Zero().Sub(feeGrowthInsideLastX128, positionFeeGrowthInsideLastX128)
	return u256.MulDiv(diff, positionLiquidity, consts.Q128())
}

// package v1 manages liquidity positions as NFTs in GnoSwap pools.
//
// Each position is represented as a GRC721 NFT with concentrated liquidity
// within a specific tick range. Unstaked NFTs follow GRC721 owner/approval/
// operator transfer rules; staked NFTs are locked to staker-mediated transfers.
// The package handles minting, liquidity adjustments, fee collection, and
// repositioning.
package position

package position

import (
	ufmt "gno.land/p/nt/ufmt/v0"
)

const (
	errNoPermission         = "[GNOSWAP-POSITION-001] caller has no permission"
	errSlippage             = "[GNOSWAP-POSITION-002] slippage failed"
	errInvalidTokenPath     = "[GNOSWAP-POSITION-003] invalid token address"
	errInvalidInput         = "[GNOSWAP-POSITION-004] invalid input data"
	errDataNotFound         = "[GNOSWAP-POSITION-005] requested data not found"
	errExpired              = "[GNOSWAP-POSITION-006] transaction expired"
	errInvalidLiquidity     = "[GNOSWAP-POSITION-007] invalid liquidity"
	errNotClear             = "[GNOSWAP-POSITION-008] position is not clear"
	errZeroLiquidity        = "[GNOSWAP-POSITION-009] zero liquidity"
	errPositionExist        = "[GNOSWAP-POSITION-010] position with same positionId already exists"
	errInvalidAddress       = "[GNOSWAP-POSITION-011] invalid address"
	errPositionDoesNotExist = "[GNOSWAP-POSITION-012] position does not exist"
	errUnderflow            = "[GNOSWAP-POSITION-013] underflow"
	errOverflow             = "[GNOSWAP-POSITION-014] overflow"
	errCannotMintToStaker   = "[GNOSWAP-POSITION-015] cannot mint to staker"
	errSpoofedRealm         = "[GNOSWAP-POSITION-016] rlm does not match the current crossing frame"
)

// newErrorWithDetail appends additional context or details to an existing error message.
func newErrorWithDetail(message string, detail string) string {
	return ufmt.Errorf("%s || %s", message, detail).Error()
}

// makeErrorWithDetails creates an error with additional context.
func makeErrorWithDetails(message string, details string) error {
	return ufmt.Errorf("%s || %s", message, details)
}

package position

import (
	"errors"

	"gno.land/p/gnoswap/consts/v1"
	u256 "gno.land/p/gnoswap/uint256/v1"
	rotree "gno.land/p/nt/bptree/rotree/v0"
	ufmt "gno.land/p/nt/ufmt/v0"

	pl "gno.land/r/gnoswap/pool"
	"gno.land/r/gnoswap/position"
)

// getPosition returns a position for a given position ID.
// Returns an error if the position doesn't exist.
func (p *positionV1) getPosition(positionId uint64) (position.Position, error) {
	pos, exists := p.store.GetPosition(positionId)
	if !exists {
		return pos, errors.New(newErrorWithDetail(
			errPositionDoesNotExist,
			ufmt.Sprintf("position with position ID(%d) doesn't exist", positionId),
		))
	}

	return pos, nil
}

// mustGetPosition returns a position for a given position ID.
// panics if position doesn't exist
func (p *positionV1) mustGetPosition(positionId uint64) *position.Position {
	position, err := p.getPosition(positionId)
	if err != nil {
		panic(err.Error())
	}

	return &position
}

// GetPositions returns a read-only view of every position, keyed by the decimal
// string form of the position ID.
//
// Returns:
//   - positions: read-only tree exposing the position store without mutation methods
func (p *positionV1) GetPositions() *rotree.ReadOnlyTree {
	// makeEntrySafeFn is a function that makes an entry safe to read.
	// But Position is immutable, so we can just return the entry as is.
	return rotree.Wrap(p.store.GetPositions(), nil)
}

// ExistPosition reports whether a position exists for a given position ID.
//
// Parameters:
//   - positionId: numeric ID to test in the position store
//
// Returns:
//   - exists: true when the position store contains positionId
func (p *positionV1) ExistPosition(positionId uint64) bool {
	return p.store.HasPosition(positionId)
}

// IsBurned reports the empty-position marker stored for a position.
//
// Parameters:
//   - positionId: numeric ID whose burned marker is requested
//
// Returns:
//   - burned: true when the position is marked empty; the NFT record itself may still exist
//   - err: nil on lookup success; errPositionDoesNotExist when the position is absent
func (p *positionV1) IsBurned(positionId uint64) (bool, error) {
	position, err := p.getPosition(positionId)
	if err != nil {
		return false, err
	}

	return position.Burned(), nil
}

// IsInRange reports whether the pool's current tick is inside a position's range.
//
// Parameters:
//   - positionId: numeric ID whose tick range and pool are inspected
//
// Returns:
//   - inRange: true when tickLower <= current pool tick < tickUpper
//   - err: nil on success; an error when the position or its pool tick cannot be read
func (p *positionV1) IsInRange(positionId uint64) (bool, error) {
	position, err := p.getPosition(positionId)
	if err != nil {
		return false, err
	}

	poolPath := position.PoolKey()
	poolCurrentTick, err := pl.GetSlot0Tick(poolPath)
	if err != nil {
		return false, err
	}

	return position.TickLower() <= poolCurrentTick && poolCurrentTick < position.TickUpper(), nil
}

// GetPositionOperator returns the address approved to operate on a position.
//
// Parameters:
//   - positionId: numeric ID whose operator is requested
//
// Returns:
//   - operator: approved operator address, or the empty address when none is set
//   - err: nil on lookup success; errPositionDoesNotExist when the position is absent
func (p *positionV1) GetPositionOperator(positionId uint64) (address, error) {
	position, err := p.getPosition(positionId)
	if err != nil {
		return address(""), err
	}

	return position.Operator(), nil
}

// GetPositionPoolKey returns the pool identifier stored on a position.
//
// Parameters:
//   - positionId: numeric ID whose pool key is requested
//
// Returns:
//   - poolKey: pool key encoding the position's token pair and fee tier
//   - err: nil on lookup success; errPositionDoesNotExist when the position is absent
func (p *positionV1) GetPositionPoolKey(positionId uint64) (string, error) {
	position, err := p.getPosition(positionId)
	if err != nil {
		return "", err
	}

	return position.PoolKey(), nil
}

// GetPositionTickLower returns the lower tick boundary stored on a position.
//
// Parameters:
//   - positionId: numeric ID whose lower tick is requested
//
// Returns:
//   - tickLower: lower tick boundary, inclusive in range checks
//   - err: nil on lookup success; errPositionDoesNotExist when the position is absent
func (p *positionV1) GetPositionTickLower(positionId uint64) (int32, error) {
	position, err := p.getPosition(positionId)
	if err != nil {
		return 0, err
	}

	return position.TickLower(), nil
}

// GetPositionTickUpper returns the upper tick boundary stored on a position.
//
// Parameters:
//   - positionId: numeric ID whose upper tick is requested
//
// Returns:
//   - tickUpper: upper tick boundary, exclusive in range checks
//   - err: nil on lookup success; errPositionDoesNotExist when the position is absent
func (p *positionV1) GetPositionTickUpper(positionId uint64) (int32, error) {
	position, err := p.getPosition(positionId)
	if err != nil {
		return 0, err
	}

	return position.TickUpper(), nil
}

// GetPositionLiquidity returns the decimal-encoded liquidity stored on a position.
//
// Parameters:
//   - positionId: numeric ID whose liquidity is requested
//
// Returns:
//   - liquidity: decimal string representing the position's current liquidity
//   - err: nil on lookup success; errPositionDoesNotExist when the position is absent
func (p *positionV1) GetPositionLiquidity(positionId uint64) (string, error) {
	position, err := p.getPosition(positionId)
	if err != nil {
		return "", err
	}

	return position.Liquidity(), nil
}

// GetPositionTokenBalances returns balances derived from current pool price,
// position range, and liquidity; token balances are not stored snapshots.
//
// Parameters:
//   - positionId: numeric ID whose current token balances are calculated
//
// Returns:
//   - token0Balance: current token0 amount represented by the position's liquidity and range
//   - token1Balance: current token1 amount represented by the position's liquidity and range
//   - err: nil when the position exists; errPositionDoesNotExist when it is absent (pool price lookup failures panic during calculation)
func (p *positionV1) GetPositionTokenBalances(positionId uint64) (int64, int64, error) {
	position, err := p.getPosition(positionId)
	if err != nil {
		return 0, 0, err
	}

	balance0, balance1 := calculatePositionBalances(&position)
	return balance0, balance1, nil
}

// GetPositionFeeGrowthInside0LastX128 returns the token0 fee-growth checkpoint
// stored on a position.
//
// Parameters:
//   - positionId: numeric ID whose token0 fee-growth checkpoint is requested
//
// Returns:
//   - feeGrowthInside0LastX128: decimal-encoded Q128 token0 fee growth inside the position's range at its last update
//   - err: nil on lookup success; errPositionDoesNotExist when the position is absent
func (p *positionV1) GetPositionFeeGrowthInside0LastX128(positionId uint64) (string, error) {
	position, err := p.getPosition(positionId)
	if err != nil {
		return "", err
	}

	return position.FeeGrowthInside0LastX128(), nil
}

// GetPositionFeeGrowthInside1LastX128 returns the token1 fee-growth checkpoint
// stored on a position.
//
// Parameters:
//   - positionId: numeric ID whose token1 fee-growth checkpoint is requested
//
// Returns:
//   - feeGrowthInside1LastX128: decimal-encoded Q128 token1 fee growth inside the position's range at its last update
//   - err: nil on lookup success; errPositionDoesNotExist when the position is absent
func (p *positionV1) GetPositionFeeGrowthInside1LastX128(positionId uint64) (string, error) {
	position, err := p.getPosition(positionId)
	if err != nil {
		return "", err
	}

	return position.FeeGrowthInside1LastX128(), nil
}

// GetPositionFeeGrowthInsideLastX128 returns both fee-growth checkpoints stored
// on a position, in token0 then token1 order.
//
// Parameters:
//   - positionId: numeric ID whose fee-growth checkpoints are requested
//
// Returns:
//   - feeGrowthInside0LastX128: decimal-encoded Q128 token0 fee growth checkpoint
//   - feeGrowthInside1LastX128: decimal-encoded Q128 token1 fee growth checkpoint
//   - err: nil on lookup success; errPositionDoesNotExist when the position is absent
func (p *positionV1) GetPositionFeeGrowthInsideLastX128(positionId uint64) (string, string, error) {
	position, err := p.getPosition(positionId)
	if err != nil {
		return "", "", err
	}

	return position.FeeGrowthInside0LastX128(), position.FeeGrowthInside1LastX128(), nil
}

// GetPositionTicks returns both tick boundaries stored on a position.
//
// Parameters:
//   - positionId: numeric ID whose tick boundaries are requested
//
// Returns:
//   - tickLower: lower tick boundary, inclusive in range checks
//   - tickUpper: upper tick boundary, exclusive in range checks
//   - err: nil on lookup success; errPositionDoesNotExist when the position is absent
func (p *positionV1) GetPositionTicks(positionId uint64) (int32, int32, error) {
	position, err := p.getPosition(positionId)
	if err != nil {
		return 0, 0, err
	}

	return position.TickLower(), position.TickUpper(), nil
}

// GetPositionTokensOwed0 returns the stored token0 amount owed to a position.
//
// Parameters:
//   - positionId: numeric ID whose token0 owed amount is requested
//
// Returns:
//   - tokensOwed0: accrued token0 amount awaiting collection, in token units
//   - err: nil on lookup success; errPositionDoesNotExist when the position is absent
func (p *positionV1) GetPositionTokensOwed0(positionId uint64) (int64, error) {
	position, err := p.getPosition(positionId)
	if err != nil {
		return 0, err
	}

	return position.TokensOwed0(), nil
}

// GetPositionTokensOwed1 returns the stored token1 amount owed to a position.
//
// Parameters:
//   - positionId: numeric ID whose token1 owed amount is requested
//
// Returns:
//   - tokensOwed1: accrued token1 amount awaiting collection, in token units
//   - err: nil on lookup success; errPositionDoesNotExist when the position is absent
func (p *positionV1) GetPositionTokensOwed1(positionId uint64) (int64, error) {
	position, err := p.getPosition(positionId)
	if err != nil {
		return 0, err
	}

	return position.TokensOwed1(), nil
}

// GetPositionTokensOwed returns both stored token amounts owed to a position,
// in token0 then token1 order.
//
// Parameters:
//   - positionId: numeric ID whose owed amounts are requested
//
// Returns:
//   - tokensOwed0: accrued token0 amount awaiting collection, in token units
//   - tokensOwed1: accrued token1 amount awaiting collection, in token units
//   - err: nil on lookup success; errPositionDoesNotExist when the position is absent
func (p *positionV1) GetPositionTokensOwed(positionId uint64) (int64, int64, error) {
	position, err := p.getPosition(positionId)
	if err != nil {
		return 0, 0, err
	}

	return position.TokensOwed0(), position.TokensOwed1(), nil
}

// GetPositionOwner returns the address that owns the position NFT.
//
// Parameters:
//   - positionId: numeric ID whose NFT ownership is requested
//
// Returns:
//   - owner: current owner address reported by the NFT accessor
//   - err: nil when the NFT accessor finds the token; otherwise its ownership lookup error
func (p *positionV1) GetPositionOwner(positionId uint64) (address, error) {
	owner, err := p.nftAccessor.OwnerOf(positionIdFrom(positionId))
	if err != nil {
		return address(""), err
	}

	return owner, nil
}

// GetUnclaimedFee calculates unclaimed token fees from current in-range
// fee growth, the position's checkpoints, and its liquidity.
//
// Parameters:
//   - positionId: numeric ID whose unclaimed token fees are calculated
//
// Returns:
//   - unclaimedFee0: token0 fees accrued since the stored checkpoint, scaled by position liquidity
//   - unclaimedFee1: token1 fees accrued since the stored checkpoint, scaled by position liquidity
//   - err: nil on success; nil fee pointers and the underlying lookup error when position or pool data is unavailable
func (p *positionV1) GetUnclaimedFee(positionId uint64) (*u256.Uint, *u256.Uint, error) {
	// ref: https://blog.uniswap.org/uniswap-v3-math-primer-2#calculating-uncollected-fees
	position, err := p.getPosition(positionId)
	if err != nil {
		return nil, nil, err
	}

	liquidity := u256.MustFromDecimal(position.Liquidity())
	tickLower := position.TickLower()
	tickUpper := position.TickUpper()

	poolKey := position.PoolKey()

	currentTick, err := pl.GetSlot0Tick(poolKey)
	if err != nil {
		return nil, nil, err
	}

	feeGrowthGlobal0X128Str, feeGrowthGlobal1X128Str, err := pl.GetFeeGrowthGlobalX128(poolKey)
	if err != nil {
		return nil, nil, err
	}
	feeGrowthGlobal0X128 := u256.MustFromDecimal(feeGrowthGlobal0X128Str)
	feeGrowthGlobal1X128 := u256.MustFromDecimal(feeGrowthGlobal1X128Str)

	tickUpperFeeGrowthOutside0X128Str, tickUpperFeeGrowthOutside1X128Str, err := pl.GetTickFeeGrowthOutsideX128(poolKey, tickUpper)
	if err != nil {
		return nil, nil, err
	}
	tickUpperFeeGrowthOutside0X128 := u256.MustFromDecimal(tickUpperFeeGrowthOutside0X128Str)
	tickUpperFeeGrowthOutside1X128 := u256.MustFromDecimal(tickUpperFeeGrowthOutside1X128Str)

	tickLowerFeeGrowthOutside0X128Str, tickLowerFeeGrowthOutside1X128Str, err := pl.GetTickFeeGrowthOutsideX128(poolKey, tickLower)
	if err != nil {
		return nil, nil, err
	}
	tickLowerFeeGrowthOutside0X128 := u256.MustFromDecimal(tickLowerFeeGrowthOutside0X128Str)
	tickLowerFeeGrowthOutside1X128 := u256.MustFromDecimal(tickLowerFeeGrowthOutside1X128Str)

	feeGrowthInside0LastX128 := u256.MustFromDecimal(position.FeeGrowthInside0LastX128())
	feeGrowthInside1LastX128 := u256.MustFromDecimal(position.FeeGrowthInside1LastX128())

	var tickLowerFeeGrowthBelow0, tickLowerFeeGrowthBelow1, tickUpperFeeGrowthAbove0, tickUpperFeeGrowthAbove1 *u256.Uint

	if currentTick >= tickUpper {
		tickUpperFeeGrowthAbove0 = u256.Zero().Sub(feeGrowthGlobal0X128, tickUpperFeeGrowthOutside0X128)
		tickUpperFeeGrowthAbove1 = u256.Zero().Sub(feeGrowthGlobal1X128, tickUpperFeeGrowthOutside1X128)
	} else {
		tickUpperFeeGrowthAbove0 = tickUpperFeeGrowthOutside0X128
		tickUpperFeeGrowthAbove1 = tickUpperFeeGrowthOutside1X128
	}

	if currentTick >= tickLower {
		tickLowerFeeGrowthBelow0 = tickLowerFeeGrowthOutside0X128
		tickLowerFeeGrowthBelow1 = tickLowerFeeGrowthOutside1X128
	} else {
		tickLowerFeeGrowthBelow0 = u256.Zero().Sub(feeGrowthGlobal0X128, tickLowerFeeGrowthOutside0X128)
		tickLowerFeeGrowthBelow1 = u256.Zero().Sub(feeGrowthGlobal1X128, tickLowerFeeGrowthOutside1X128)
	}

	feeGrowthInside0X128 := u256.Zero().Sub(feeGrowthGlobal0X128, tickLowerFeeGrowthBelow0)
	feeGrowthInside0X128 = u256.Zero().Sub(feeGrowthInside0X128, tickUpperFeeGrowthAbove0)

	feeGrowthInside1X128 := u256.Zero().Sub(feeGrowthGlobal1X128, tickLowerFeeGrowthBelow1)
	feeGrowthInside1X128 = u256.Zero().Sub(feeGrowthInside1X128, tickUpperFeeGrowthAbove1)

	diffGrowthInside0X128 := u256.Zero().Sub(feeGrowthInside0X128, feeGrowthInside0LastX128)
	unclaimedFee0 := u256.MulDiv(diffGrowthInside0X128, liquidity, consts.Q128())

	diffGrowthInside1X128 := u256.Zero().Sub(feeGrowthInside1X128, feeGrowthInside1LastX128)
	unclaimedFee1 := u256.MulDiv(diffGrowthInside1X128, liquidity, consts.Q128())
	return unclaimedFee0, unclaimedFee1, nil
}

package position

import (
	"gno.land/r/gnoswap/access/v1"
	"gno.land/r/gnoswap/position"
)

func init(cur realm) {
	registerPositionV1(cur)
}

func registerPositionV1(cur realm) {
	position.RegisterInitializer(
		cross(cur),
		func(_ int, rlm realm, positionStore position.IPositionStore) position.IPosition {
			access.AssertIsRlmCurrent(0, rlm)

			err := initStoreData(0, rlm, positionStore)
			if err != nil {
				panic(err)
			}

			return NewPositionV1(positionStore, newGNFTAccessor())
		},
	)
}

func initStoreData(_ int, rlm realm, positionStore position.IPositionStore) error {
	if !positionStore.HasPositionNextIDStoreKey() {
		err := positionStore.SetPositionNextID(0, rlm, uint64(1))
		if err != nil {
			return err
		}
	}

	if !positionStore.HasPositionsStoreKey() {
		err := positionStore.SetPositions(0, rlm, position.NewPositionsTree())
		if err != nil {
			return err
		}
	}

	return nil
}

package position

import (
	"errors"

	"gno.land/p/nt/grc721/v0"
	"gno.land/r/gnoswap/access/v1"
	"gno.land/r/gnoswap/gnft"
	"gno.land/r/gnoswap/position"
)

type positionV1 struct {
	store       position.IPositionStore
	nftAccessor NFTAccessor
}

// NewPositionV1 constructs a position implementation backed by the supplied
// position store and NFT accessor.
//
// Parameters:
//   - positionStore: storage interface used to read and update position records
//   - accessor: NFT interface used for position token minting, burning, approval, and ownership
//
// Returns:
//   - position: IPosition implementation connected to positionStore and accessor
func NewPositionV1(positionStore position.IPositionStore, accessor NFTAccessor) position.IPosition {
	return &positionV1{
		store:       positionStore,
		nftAccessor: accessor,
	}
}

type NFTAccessor interface {
	// Approve forwards an operator approval for a position NFT.
	//
	// Parameters:
	//   - _: leading realm-call discriminator for the forwarded NFT operation; callers pass 0
	//   - rlm: propagated realm context validated by the concrete accessor before crossing into the NFT realm
	//   - approved: address to approve for the specified position NFT; the empty address revokes approval
	//   - tid: position NFT token ID whose operator approval is changed
	//
	// Returns:
	//   - err: nil when approval succeeds; otherwise the NFT accessor or realm-validation error
	Approve(_ int, rlm realm, approved address, tid grc721.TokenID) error
	// Mint creates a position NFT for an address and token ID.
	//
	// Parameters:
	//   - _: leading realm-call discriminator for the forwarded NFT operation; callers pass 0
	//   - rlm: propagated realm context used to cross into the NFT realm
	//   - to: address that receives the newly minted position NFT
	//   - tid: requested position NFT token ID
	//
	// Returns:
	//   - mintedTid: token ID returned by the NFT realm after minting
	Mint(_ int, rlm realm, to address, tid grc721.TokenID) grc721.TokenID
	// Burn removes a position NFT from the NFT ledger.
	//
	// Parameters:
	//   - _: leading realm-call discriminator for the forwarded NFT operation; callers pass 0
	//   - rlm: propagated realm context used to cross into the NFT realm
	//   - tid: position NFT token ID to burn
	Burn(_ int, rlm realm, tid grc721.TokenID)
	// TotalSupply returns the number of NFTs currently recorded by the ledger.
	//
	// Returns:
	//   - totalSupply: current number of position NFTs in the ledger
	TotalSupply() int64
	// Exists reports whether the NFT ledger contains a token ID.
	//
	// Parameters:
	//   - tid: position NFT token ID to test
	//
	// Returns:
	//   - exists: true when the NFT ledger contains tid
	Exists(tid grc721.TokenID) bool
	// OwnerOf returns the current owner of a position NFT.
	//
	// Parameters:
	//   - tid: position NFT token ID whose owner is requested
	//
	// Returns:
	//   - owner: address recorded as the token owner
	//   - err: nil when the token exists; otherwise the NFT ledger's ownership lookup error
	OwnerOf(tid grc721.TokenID) (address, error)
}

type gnftAccessor struct{}

// Approve forwards an operator approval to the GNFT realm.
//
// Parameters:
//   - _: leading realm-call discriminator for the forwarded NFT operation; callers pass 0
//   - rlm: propagated realm context that must be current before crossing into GNFT
//   - approved: address to approve for the specified position NFT; the empty address revokes approval
//   - tid: position NFT token ID whose operator approval is changed
//
// Returns:
//   - err: nil when GNFT accepts the approval; errSpoofedRealm when rlm is not current, otherwise the underlying GNFT error
func (n *gnftAccessor) Approve(_ int, rlm realm, approved address, tid grc721.TokenID) error {
	if !rlm.IsCurrent() {
		return errors.New(errSpoofedRealm)
	}

	return gnft.Approve(cross(rlm), approved, tid)
}

// Mint forwards position NFT creation to the GNFT realm.
//
// Parameters:
//   - _: leading realm-call discriminator for the forwarded NFT operation; callers pass 0
//   - rlm: propagated realm context asserted current before crossing into GNFT
//   - to: address that receives the newly minted position NFT
//   - tid: requested position NFT token ID
//
// Returns:
//   - mintedTid: token ID returned by GNFT after minting
func (n *gnftAccessor) Mint(_ int, rlm realm, to address, tid grc721.TokenID) grc721.TokenID {
	access.AssertIsRlmCurrent(0, rlm)

	return gnft.Mint(cross(rlm), to, tid)
}

// Burn forwards position NFT destruction to the GNFT realm.
//
// Parameters:
//   - _: leading realm-call discriminator for the forwarded NFT operation; callers pass 0
//   - rlm: propagated realm context asserted current before crossing into GNFT
//   - tid: position NFT token ID to burn
func (n *gnftAccessor) Burn(_ int, rlm realm, tid grc721.TokenID) {
	access.AssertIsRlmCurrent(0, rlm)

	gnft.Burn(cross(rlm), tid)
}

// TotalSupply returns the GNFT ledger's current token count.
//
// Returns:
//   - totalSupply: number of NFTs currently recorded by GNFT
func (n *gnftAccessor) TotalSupply() int64 {
	return gnft.TotalSupply()
}

// Exists reports whether GNFT contains a position NFT token ID.
//
// Parameters:
//   - tid: position NFT token ID to test
//
// Returns:
//   - exists: true when GNFT contains tid
func (n *gnftAccessor) Exists(tid grc721.TokenID) bool {
	return gnft.Exists(tid)
}

// OwnerOf returns the owner recorded by GNFT for a position NFT.
//
// Parameters:
//   - tid: position NFT token ID whose owner is requested
//
// Returns:
//   - owner: address recorded as the token owner
//   - err: nil when GNFT finds the token; otherwise GNFT's ownership lookup error
func (n *gnftAccessor) OwnerOf(tid grc721.TokenID) (address, error) {
	return gnft.OwnerOf(tid)
}

func newGNFTAccessor() NFTAccessor {
	return &gnftAccessor{}
}

package position

import (
	"gno.land/r/gnoswap/position"
)

// GetNextId is the next position ID to be minted
func (p *positionV1) getNextId() uint64 {
	return p.store.GetPositionNextID()
}

// incrementNextId increments the next position ID to be minted
func (p *positionV1) incrementNextId(_ int, rlm realm) error {
	return p.store.SetPositionNextID(0, rlm, p.getNextId()+1)
}

// setPosition sets a position for a given position ID.
// Returns false if position is newly created, true if position already existed and was updated.
func (p *positionV1) setPosition(_ int, rlm realm, id uint64, pos position.Position) error {
	return p.store.SetPosition(0, rlm, id, pos)
}

// mustUpdatePosition updates a position for a given position ID.
func (p *positionV1) mustUpdatePosition(_ int, rlm realm, id uint64, pos position.Position) {
	err := p.setPosition(0, rlm, id, pos)
	if err != nil {
		panic(err)
	}
}

package position

import (
	"errors"

	u256 "gno.land/p/gnoswap/uint256/v1"
	ufmt "gno.land/p/nt/ufmt/v0"

	"gno.land/r/gnoswap/common"
	pl "gno.land/r/gnoswap/pool"
	"gno.land/r/gnoswap/position"
)

// mint creates a new liquidity position by adding liquidity to a pool and minting an NFT.
// Panics if position ID already exists or adding liquidity fails.
func (p *positionV1) mint(_ int, rlm realm, params MintParams) (uint64, *u256.Uint, *u256.Uint, *u256.Uint) {
	poolKey := pl.GetPoolPath(params.token0, params.token1, params.fee)
	liquidity, amount0, amount1 := p.addLiquidity(
		0,
		rlm,
		AddLiquidityParams{
			poolKey:        poolKey,
			tickLower:      params.tickLower,
			tickUpper:      params.tickUpper,
			amount0Desired: params.amount0Desired,
			amount1Desired: params.amount1Desired,
			amount0Min:     params.amount0Min,
			amount1Min:     params.amount1Min,
			caller:         params.caller,
		},
	)
	// Ensure liquidity is not zero before minting NFT
	if liquidity.IsZero() {
		panic(newErrorWithDetail(
			errZeroLiquidity,
			"Liquidity is zero, cannot mint position.",
		))
	}

	id := p.getNextId()

	if p.ExistPosition(id) {
		panic(newErrorWithDetail(
			errPositionExist,
			ufmt.Sprintf("positionId(%d)", id),
		))
	}

	p.nftAccessor.Mint(0, rlm, params.mintTo, positionIdFrom(id))

	positionKey := computePositionKey(params.tickLower, params.tickUpper)
	feeGrowthInside0LastX128, feeGrowthInside1LastX128, err := pl.GetPositionFeeGrowthInsideLastX128(poolKey, positionKey)
	if err != nil {
		panic(err)
	}

	position := position.NewPosition(
		poolKey,
		params.tickLower,
		params.tickUpper,
		liquidity.ToString(),
		feeGrowthInside0LastX128,
		feeGrowthInside1LastX128,
		0,
		0,
		false,
		zeroAddress,
	)

	// The position ID should not exist at the time of minting
	p.mustUpdatePosition(0, rlm, id, *position)
	p.incrementNextId(0, rlm)

	return id, liquidity, amount0, amount1
}

// processMintInput processes and validates user input for minting liquidity.
// It handles token ordering and amount validation.
func (p *positionV1) processMintInput(input MintInput) (ProcessedMintInput, error) {
	token0, token1 := input.token0, input.token1
	if err := validateTokenPath(token0, token1); err != nil {
		return ProcessedMintInput{}, makeErrorWithDetails(err.Error(), ufmt.Sprintf("token0(%s), token1(%s)", token0, token1))
	}

	pair := TokenPair{
		token0: token0,
		token1: token1,
	}

	// parse amounts
	amount0Desired, amount1Desired, amount0Min, amount1Min := parseAmounts(input.amount0Desired, input.amount1Desired, input.amount0Min, input.amount1Min)

	tickLower, tickUpper := input.tickLower, input.tickUpper

	// swap if token1 < token0
	if token1 < token0 {
		pair.token0, pair.token1 = pair.token1, pair.token0
		amount0Desired, amount1Desired = amount1Desired, amount0Desired
		amount0Min, amount1Min = amount1Min, amount0Min
		tickLower, tickUpper = -tickUpper, -tickLower
	}

	return ProcessedMintInput{
		tokenPair:      pair,
		amount0Desired: amount0Desired,
		amount1Desired: amount1Desired,
		amount0Min:     amount0Min,
		amount1Min:     amount1Min,
		tickLower:      tickLower,
		tickUpper:      tickUpper,
		poolPath:       pl.GetPoolPath(pair.token0, pair.token1, input.fee),
	}, nil
}

// increaseLiquidity increases the liquidity of an existing position.
func (p *positionV1) increaseLiquidity(_ int, rlm realm, params IncreaseLiquidityParams) (uint64, *u256.Uint, *u256.Uint, *u256.Uint, string, error) {
	caller := params.caller
	position := p.mustGetPosition(params.positionId)

	liquidity, amount0, amount1 := p.addLiquidity(
		0,
		rlm,
		AddLiquidityParams{
			poolKey:        position.PoolKey(),
			tickLower:      position.TickLower(),
			tickUpper:      position.TickUpper(),
			amount0Desired: params.amount0Desired,
			amount1Desired: params.amount1Desired,
			amount0Min:     params.amount0Min,
			amount1Min:     params.amount1Min,
			caller:         caller,
		},
	)

	positionKey := computePositionKey(position.TickLower(), position.TickUpper())
	feeGrowthInside0LastX128Str, feeGrowthInside1LastX128Str, err := pl.GetPositionFeeGrowthInsideLastX128(position.PoolKey(), positionKey)
	if err != nil {
		return 0, nil, nil, nil, "", err
	}

	feeGrowth := FeeGrowthInside{
		feeGrowthInside0LastX128: u256.MustFromDecimal(feeGrowthInside0LastX128Str),
		feeGrowthInside1LastX128: u256.MustFromDecimal(feeGrowthInside1LastX128Str),
	}
	tokensOwed0, tokensOwed1 := p.calculateFees(position, feeGrowth)

	posLiquidity := u256.MustFromDecimal(position.Liquidity())
	liquidityAmount, overflow := u256.Zero().AddOverflow(posLiquidity, liquidity)
	if overflow {
		return 0, nil, nil, nil, "", errors.New(errOverflow)
	}

	position.SetTokensOwed0(tokensOwed0)
	position.SetTokensOwed1(tokensOwed1)

	position.SetFeeGrowthInside0LastX128(feeGrowthInside0LastX128Str)
	position.SetFeeGrowthInside1LastX128(feeGrowthInside1LastX128Str)

	position.SetLiquidity(liquidityAmount.ToString())
	position.SetBurned(false)

	err = p.setPosition(0, rlm, params.positionId, *position)
	if err != nil {
		return 0, nil, nil, nil, "", makeErrorWithDetails(
			errPositionDoesNotExist,
			ufmt.Sprintf("cannot increase liquidity for non-existent position(%d)", params.positionId),
		)
	}

	return params.positionId, liquidity, amount0, amount1, position.PoolKey(), nil
}

// validateTokenPath validates token paths are not identical, not conflicting, and in valid format.
func validateTokenPath(token0, token1 string) error {
	if token0 == token1 {
		return errors.New(errInvalidTokenPath)
	}
	if !isValidTokenPath(token0) || !isValidTokenPath(token1) {
		return errors.New(errInvalidTokenPath)
	}
	return nil
}

// isValidTokenPath checks if the token path is registered in the system.
func isValidTokenPath(tokenPath string) bool {
	return common.IsRegistered(tokenPath) == nil
}

// parseAmounts converts amount strings to u256.Uint values.
func parseAmounts(amount0Desired, amount1Desired, amount0Min, amount1Min string) (*u256.Uint, *u256.Uint, *u256.Uint, *u256.Uint) {
	return u256.MustFromDecimal(amount0Desired), u256.MustFromDecimal(amount1Desired), u256.MustFromDecimal(amount0Min), u256.MustFromDecimal(amount1Min)
}

package position

import (
	"chain"

	"gno.land/p/gnoswap/gnsmath/v1"
	u256 "gno.land/p/gnoswap/uint256/v1"
	"gno.land/p/gnoswap/utils/v1"
	ufmt "gno.land/p/nt/ufmt/v0"
	"gno.land/r/gnoswap/access/v1"
	"gno.land/r/gnoswap/common"
	"gno.land/r/gnoswap/emission"
	"gno.land/r/gnoswap/halt/v1"
	pl "gno.land/r/gnoswap/pool"
	pos "gno.land/r/gnoswap/position"
	"gno.land/r/gnoswap/referral/v1"
	"gno.land/r/gnoswap/staker"
)

// Mint creates a new liquidity position NFT.
//
// Parameters:
//   - _: Noncrossing implementation-call discriminator; pass 0.
//   - rlm: Current realm context forwarded unchanged by the position proxy.
//   - token0: token0 contract path for the pool
//   - token1: token1 contract path for the pool
//   - fee: pool fee tier used to select the pool
//   - tickLower: lower tick boundary of the position's range
//   - tickUpper: upper tick boundary of the position's range
//   - amount0Desired: desired token0 amount, supplied as a decimal string
//   - amount1Desired: desired token1 amount, supplied as a decimal string
//   - amount0Min: minimum acceptable token0 amount for slippage protection
//   - amount1Min: minimum acceptable token1 amount for slippage protection
//   - deadline: Unix timestamp after which the transaction is rejected
//   - mintTo: address that receives the newly minted position NFT
//   - referrer: referral value submitted for registration with the caller
//
// Returns:
//   - positionId: newly minted position NFT ID
//   - liquidity: liquidity amount minted for the position
//   - amount0: token0 amount actually deposited into the pool
//   - amount1: token1 amount actually deposited into the pool
//
// Note: Slippage protection via amount0Min/amount1Min.
func (p *positionV1) Mint(
	_ int,
	rlm realm,
	token0 string,
	token1 string,
	fee uint32,
	tickLower int32,
	tickUpper int32,
	amount0Desired string,
	amount1Desired string,
	amount0Min string,
	amount1Min string,
	deadline int64,
	mintTo address,
	referrer string,
) (uint64, string, string, string) {
	access.AssertIsRlmCurrent(0, rlm)

	halt.AssertIsNotHaltedPosition()
	access.AssertIsValidAddress(mintTo)

	previousRealm := rlm.Previous()
	caller := previousRealm.Address()

	assertIsNotMintToStaker(mintTo)
	assertValidNumberString(amount0Desired)
	assertValidNumberString(amount1Desired)
	assertValidNumberString(amount0Min)
	assertValidNumberString(amount1Min)

	// assert that the user has sent the correct amount of native coin
	common.AssertIsNotHandleNativeCoin()
	assertIsNotExpired(deadline)

	actualReferrer := referral.TryRegister(cross(rlm), caller, referrer)

	emission.MintAndDistributeGns(cross(rlm))

	mintInput := MintInput{
		token0:         token0,
		token1:         token1,
		fee:            fee,
		tickLower:      tickLower,
		tickUpper:      tickUpper,
		amount0Desired: amount0Desired,
		amount1Desired: amount1Desired,
		amount0Min:     amount0Min,
		amount1Min:     amount1Min,
		deadline:       deadline,
		mintTo:         mintTo,
		caller:         caller,
	}

	processedInput, err := p.processMintInput(mintInput)
	if err != nil {
		panic(newErrorWithDetail(errInvalidInput, err.Error()))
	}

	// mint liquidity
	params := newMintParams(processedInput, mintInput)
	id, liquidity, amount0, amount1 := p.mint(0, rlm, params)

	pool := mustGetPool(processedInput.poolPath)
	positionLiquidity, err := p.GetPositionLiquidity(id)
	if err != nil {
		panic(err)
	}
	tickCumulative, secondsPerLiquidityCumulativeX128, observationTimestamp, err := currentPoolObservation(processedInput.poolPath)
	if err != nil {
		panic(err)
	}

	chain.Emit(
		"Mint",
		"prevAddr", caller.String(),
		"prevRealm", previousRealm.PkgPath(),
		"tickLower", utils.FormatInt(processedInput.tickLower),
		"tickUpper", utils.FormatInt(processedInput.tickUpper),
		"poolPath", processedInput.poolPath,
		"mintTo", mintTo.String(),
		"caller", caller.String(),
		"lpPositionId", utils.FormatUint(id),
		"liquidityDelta", liquidity.ToString(),
		"amount0", amount0.ToString(),
		"amount1", amount1.ToString(),
		"sqrtPriceX96", pool.Slot0SqrtPriceX96().ToString(),
		"positionLiquidity", positionLiquidity,
		"poolLiquidity", pool.Liquidity().ToString(),
		"token0Balance", utils.FormatInt(pool.BalanceToken0()),
		"token1Balance", utils.FormatInt(pool.BalanceToken1()),
		"tickCumulative", utils.FormatInt(tickCumulative),
		"secondsPerLiquidityCumulativeX128", secondsPerLiquidityCumulativeX128,
		"observationTimestamp", utils.FormatInt(observationTimestamp),
		"referrer", actualReferrer,
	)

	return id, liquidity.ToString(), amount0.ToString(), amount1.ToString()
}

// IncreaseLiquidity increases liquidity of an existing position.
//
// Adds more liquidity to existing NFT position.
// Maintains same price range as original position.
// Calculates optimal token ratio for current price.
//
// Parameters:
//   - _: Noncrossing implementation-call discriminator; pass 0.
//   - rlm: Current realm context forwarded unchanged by the position proxy.
//   - positionId: NFT token ID to increase
//   - amount0DesiredStr: desired token0 amount, supplied as a decimal string
//   - amount1DesiredStr: desired token1 amount, supplied as a decimal string
//   - amount0MinStr: minimum acceptable token0 amount for slippage protection
//   - amount1MinStr: minimum acceptable token1 amount for slippage protection
//   - deadline: Unix timestamp after which the transaction is rejected
//
// Returns:
//   - positionId: same NFT ID
//   - liquidity: liquidity amount added (the delta, not total)
//   - amount0: token0 amount actually deposited
//   - amount1: token1 amount actually deposited
//   - poolPath: pool identifier for the position
//
// Requirements:
//   - Caller must own the position NFT
//   - Sufficient token balances and approvals
func (p *positionV1) IncreaseLiquidity(
	_ int,
	rlm realm,
	positionId uint64,
	amount0DesiredStr string,
	amount1DesiredStr string,
	amount0MinStr string,
	amount1MinStr string,
	deadline int64,
) (uint64, string, string, string, string) {
	access.AssertIsRlmCurrent(0, rlm)

	halt.AssertIsNotHaltedPosition()

	previousRealm := rlm.Previous()
	caller := previousRealm.Address()
	assertIsOwnerForToken(p, positionId, caller)

	assertValidNumberString(amount0DesiredStr)
	assertValidNumberString(amount1DesiredStr)
	assertValidNumberString(amount0MinStr)
	assertValidNumberString(amount1MinStr)
	assertIsNotExpired(deadline)

	emission.MintAndDistributeGns(cross(rlm))

	position := p.mustGetPosition(positionId)
	token0, token1, _ := splitOf(position.PoolKey())

	common.AssertIsNotHandleNativeCoin()

	err := validateTokenPath(token0, token1)
	if err != nil {
		panic(newErrorWithDetail(err.Error(), ufmt.Sprintf("token0(%s), token1(%s)", token0, token1)))
	}

	amount0Desired, amount1Desired, amount0Min, amount1Min := parseAmounts(amount0DesiredStr, amount1DesiredStr, amount0MinStr, amount1MinStr)
	increaseLiquidityParams := IncreaseLiquidityParams{
		positionId:     positionId,
		amount0Desired: amount0Desired,
		amount1Desired: amount1Desired,
		amount0Min:     amount0Min,
		amount1Min:     amount1Min,
		deadline:       deadline,
		caller:         caller,
	}

	_, liquidity, amount0, amount1, poolPath, err := p.increaseLiquidity(0, rlm, increaseLiquidityParams)
	if err != nil {
		panic(err)
	}

	pool := mustGetPool(poolPath)
	positionLiquidity, err := p.GetPositionLiquidity(positionId)
	if err != nil {
		panic(err)
	}
	tickCumulative, secondsPerLiquidityCumulativeX128, observationTimestamp, err := currentPoolObservation(poolPath)
	if err != nil {
		panic(err)
	}
	chain.Emit(
		"IncreaseLiquidity",
		"prevAddr", previousRealm.Address().String(),
		"prevRealm", previousRealm.PkgPath(),
		"poolPath", poolPath,
		"tickLower", utils.FormatInt(position.TickLower()),
		"tickUpper", utils.FormatInt(position.TickUpper()),
		"caller", caller.String(),
		"lpPositionId", utils.FormatUint(positionId),
		"liquidityDelta", liquidity.ToString(),
		"amount0", amount0.ToString(),
		"amount1", amount1.ToString(),
		"sqrtPriceX96", pool.Slot0SqrtPriceX96().ToString(),
		"positionLiquidity", positionLiquidity,
		"poolLiquidity", pool.Liquidity().ToString(),
		"token0Balance", utils.FormatInt(pool.BalanceToken0()),
		"token1Balance", utils.FormatInt(pool.BalanceToken1()),
		"tickCumulative", utils.FormatInt(tickCumulative),
		"secondsPerLiquidityCumulativeX128", secondsPerLiquidityCumulativeX128,
		"observationTimestamp", utils.FormatInt(observationTimestamp),
	)

	return positionId, liquidity.ToString(), amount0.ToString(), amount1.ToString(), poolPath
}

// DecreaseLiquidity decreases liquidity of an existing position.
//
// Removes liquidity but keeps NFT ownership. This is one atomic public
// operation: accrued swap fees are collected first, then liquidity is burned,
// and principal is collected through the pool's fee-free `Collect` path.
//
// Parameters:
//   - _: Noncrossing implementation-call discriminator; pass 0.
//   - rlm: Current realm context forwarded unchanged by the position proxy.
//   - positionId: NFT token ID
//   - liquidityStr: amount of liquidity to remove, supplied as a decimal string
//   - amount0MinStr: minimum token0 principal to receive, for slippage protection
//   - amount1MinStr: minimum token1 principal to receive, for slippage protection
//   - deadline: Unix timestamp after which the transaction is rejected
//
// Returns:
//   - positionId: same NFT ID
//   - liquidity: amount of liquidity removed (the delta)
//   - fee0: token0 fee amount returned net of the withdrawal fee
//   - fee1: token1 fee amount returned net of the withdrawal fee
//   - amount0: token0 principal collected without a withdrawal fee
//   - amount1: token1 principal collected without a withdrawal fee
//   - poolPath: pool identifier
//
// Amount-minimum checks apply to the principal actually collected.
func (p *positionV1) DecreaseLiquidity(
	_ int,
	rlm realm,
	positionId uint64,
	liquidityStr string,
	amount0MinStr string,
	amount1MinStr string,
	deadline int64,
) (uint64, string, string, string, string, string, string) {
	access.AssertIsRlmCurrent(0, rlm)

	halt.AssertIsNotHaltedWithdraw()

	previousRealm := rlm.Previous()
	caller := previousRealm.Address()
	assertIsOwnerForToken(p, positionId, caller)
	assertIsNotExpired(deadline)
	assertValidLiquidityAmount(liquidityStr)

	emission.MintAndDistributeGns(cross(rlm))

	amount0Min := u256.MustFromDecimal(amount0MinStr)
	amount1Min := u256.MustFromDecimal(amount1MinStr)
	decreaseLiquidityParams := DecreaseLiquidityParams{
		positionId: positionId,
		liquidity:  liquidityStr,
		amount0Min: amount0Min,
		amount1Min: amount1Min,
		deadline:   deadline,
		caller:     caller,
	}

	position := p.mustGetPosition(positionId)
	tickLower := position.TickLower()
	tickUpper := position.TickUpper()

	positionId, liquidity, fee0, fee1, amount0, amount1, poolPath, err := p.decreaseLiquidity(0, rlm, decreaseLiquidityParams)
	if err != nil {
		panic(err)
	}

	pool := mustGetPool(poolPath)
	positionLiquidity, err := p.GetPositionLiquidity(positionId)
	if err != nil {
		panic(err)
	}
	tickCumulative, secondsPerLiquidityCumulativeX128, observationTimestamp, err := currentPoolObservation(poolPath)
	if err != nil {
		panic(err)
	}
	chain.Emit(
		"DecreaseLiquidity",
		"prevAddr", previousRealm.Address().String(),
		"prevRealm", previousRealm.PkgPath(),
		"lpPositionId", utils.FormatUint(positionId),
		"poolPath", poolPath,
		"tickLower", utils.FormatInt(tickLower),
		"tickUpper", utils.FormatInt(tickUpper),
		"liquidityDelta", liquidity,
		"feeAmount0", fee0,
		"feeAmount1", fee1,
		"amount0", amount0,
		"amount1", amount1,
		"sqrtPriceX96", pool.Slot0SqrtPriceX96().ToString(),
		"positionLiquidity", positionLiquidity,
		"poolLiquidity", pool.Liquidity().ToString(),
		"token0Balance", utils.FormatInt(pool.BalanceToken0()),
		"token1Balance", utils.FormatInt(pool.BalanceToken1()),
		"tickCumulative", utils.FormatInt(tickCumulative),
		"secondsPerLiquidityCumulativeX128", secondsPerLiquidityCumulativeX128,
		"observationTimestamp", utils.FormatInt(observationTimestamp),
	)

	return positionId, liquidity, fee0, fee1, amount0, amount1, poolPath
}

// CollectFee collects swap fee from the position.
//
// Claims accumulated fees without removing liquidity.
// Useful for active positions earning ongoing fees.
// Applies the configured withdrawal fee to the collected swap fees.
//
// Parameters:
//   - _: Noncrossing implementation-call discriminator; pass 0.
//   - rlm: Current realm context forwarded unchanged by the position proxy.
//   - positionId: NFT token ID whose accrued swap fees are collected
//
// Returns:
//   - positionId: same NFT ID
//   - tokensCollected0: token0 amount sent to caller after the withdrawal fee
//   - tokensCollected1: token1 amount sent to caller after the withdrawal fee
//   - poolPath: pool identifier
//   - totalAmount0: raw token0 amount collected before the withdrawal fee
//   - totalAmount1: raw token1 amount collected before the withdrawal fee
//
// Requirements:
//   - Caller must own an unstaked NFT; a staked position uses its configured operator
//   - If no fees are owed, the fee amounts returned are zero
func (p *positionV1) CollectFee(_ int, rlm realm, positionId uint64) (uint64, string, string, string, string, string) {
	access.AssertIsRlmCurrent(0, rlm)

	halt.AssertIsNotHaltedWithdraw()

	caller := rlm.Previous().Address()
	assertIsOwnerOrOperatorForToken(p, positionId, caller)

	emission.MintAndDistributeGns(cross(rlm))

	return p.collectFee(0, rlm, positionId, caller)
}

// collectFee performs fee collection and withdrawal fee calculation.
func (p *positionV1) collectFee(_ int, rlm realm, positionId uint64, caller address) (uint64, string, string, string, string, string) {
	// verify position
	position := p.mustGetPosition(positionId)
	token0, token1, fee := splitOf(position.PoolKey())

	pl.Burn(
		cross(rlm),
		token0,
		token1,
		fee,
		position.TickLower(),
		position.TickUpper(),
		"0", // burn '0' liquidity to collect fee
		caller,
	)

	currentFeeGrowth, err := p.getCurrentFeeGrowth(position, caller)
	if err != nil {
		panic(newErrorWithDetail(err.Error(), "failed to get current fee growth"))
	}

	tokensOwed0, tokensOwed1 := p.calculateFees(position, currentFeeGrowth)

	position.SetFeeGrowthInside0LastX128(currentFeeGrowth.feeGrowthInside0LastX128.ToString())
	position.SetFeeGrowthInside1LastX128(currentFeeGrowth.feeGrowthInside1LastX128.ToString())

	// Collect the fee. The pool withholds the withdrawal fee and pays the
	// remainder straight to the caller.
	amount0, amount1, fee0Str, fee1Str := pl.CollectSwapFee(
		cross(rlm),
		token0, token1, fee,
		caller,
		position.TickLower(), position.TickUpper(),
		utils.FormatInt(tokensOwed0), utils.FormatInt(tokensOwed1),
	)
	amount0Uint256 := u256.MustFromDecimal(amount0)
	amount1Uint256 := u256.MustFromDecimal(amount1)
	amount0Int64 := gnsmath.SafeConvertToInt64(amount0Uint256)
	amount1Int64 := gnsmath.SafeConvertToInt64(amount1Uint256)

	// sometimes there will be a few less uBase amount than expected due to rounding down in core, but we just subtract the full amount expected
	// instead of the actual amount so we can burn the token
	if tokensOwed0 < amount0Int64 {
		panic(newErrorWithDetail(errUnderflow, "tokensOwed0 - amount0 underflow"))
	}
	position.SetTokensOwed0(gnsmath.SafeSubInt64(tokensOwed0, amount0Int64))

	if tokensOwed1 < amount1Int64 {
		panic(newErrorWithDetail(errUnderflow, "tokensOwed1 - amount1 underflow"))
	}
	position.SetTokensOwed1(gnsmath.SafeSubInt64(tokensOwed1, amount1Int64))
	p.mustUpdatePosition(0, rlm, positionId, *position)

	// The pool already paid these out; recomputing them here only feeds the
	// events and the return value.
	amount0WithoutFeeStr := utils.FormatInt(gnsmath.SafeSubInt64(amount0Int64, utils.SafeParseInt64(fee0Str)))
	amount1WithoutFeeStr := utils.FormatInt(gnsmath.SafeSubInt64(amount1Int64, utils.SafeParseInt64(fee1Str)))

	poolPath := position.PoolKey()

	previousRealm := rlm.Previous()
	chain.Emit(
		"CollectSwapFee",
		"prevAddr", previousRealm.Address().String(),
		"prevRealm", previousRealm.PkgPath(),
		"lpPositionId", utils.FormatUint(positionId),
		"feeAmount0", amount0WithoutFeeStr,
		"feeAmount1", amount1WithoutFeeStr,
		"poolPath", poolPath,
		"poolTier", utils.FormatUint(staker.GetPoolTier(poolPath)),
		"feeGrowthInside0LastX128", position.FeeGrowthInside0LastX128(),
		"feeGrowthInside1LastX128", position.FeeGrowthInside1LastX128(),
	)

	chain.Emit(
		"WithdrawalFee",
		"prevAddr", previousRealm.Address().String(),
		"prevRealm", previousRealm.PkgPath(),
		"lpTokenId", utils.FormatUint(positionId),
		"poolPath", poolPath,
		"feeAmount0", fee0Str,
		"feeAmount1", fee1Str,
		"amount0WithoutFee", amount0WithoutFeeStr,
		"amount1WithoutFee", amount1WithoutFeeStr,
	)

	return positionId, amount0WithoutFeeStr, amount1WithoutFeeStr, position.PoolKey(), amount0, amount1
}

// SetPositionOperator sets an operator for a position.
// Only staker can call this function.
//
// Parameters:
//   - _: Noncrossing implementation-call discriminator; pass 0.
//   - rlm: Current realm context forwarded unchanged by the position proxy.
//   - id: position NFT ID whose operator is changed
//   - operator: valid address to approve, or the empty address to remove the operator
func (p *positionV1) SetPositionOperator(_ int, rlm realm, id uint64, operator address) {
	access.AssertIsRlmCurrent(0, rlm)

	previousRealm := rlm.Previous()
	access.AssertIsStaker(previousRealm.Address())

	assertValidOperatorAddress(operator)

	position := p.mustGetPosition(id)
	prevOperator := position.Operator()
	position.SetOperator(operator)

	p.mustUpdatePosition(0, rlm, id, *position)

	chain.Emit(
		"SetPositionOperator",
		"prevAddr", previousRealm.Address().String(),
		"prevRealm", previousRealm.PkgPath(),
		"lpPositionId", utils.FormatUint(id),
		"prevOperator", prevOperator.String(),
		"newOperator", operator.String(),
	)
}

// getCurrentFeeGrowth retrieves current fee growth values for a position.
func (p *positionV1) getCurrentFeeGrowth(position *pos.Position, owner address) (FeeGrowthInside, error) {
	positionKey := computePositionKey(position.TickLower(), position.TickUpper())
	feeGrowthInside0LastX128, feeGrowthInside1LastX128, err := pl.GetPositionFeeGrowthInsideLastX128(position.PoolKey(), positionKey)
	if err != nil {
		return FeeGrowthInside{}, err
	}

	feeGrowthInside := FeeGrowthInside{
		feeGrowthInside0LastX128: u256.MustFromDecimal(feeGrowthInside0LastX128),
		feeGrowthInside1LastX128: u256.MustFromDecimal(feeGrowthInside1LastX128),
	}

	return feeGrowthInside, nil
}

// computePositionKey generates a compact deterministic key for a liquidity position.
func computePositionKey(tickLower, tickUpper int32) string {
	return pl.EncodePositionKey(tickLower, tickUpper)
}

// calculatePositionBalances computes token balances for a position at current price.
// Returns calculated token0 and token1 balances based on position liquidity and price range.
func calculatePositionBalances(position *pos.Position) (int64, int64) {
	liquidity := u256.MustFromDecimal(position.Liquidity())
	if liquidity.IsZero() {
		return 0, 0
	}

	sqrtPriceX96, err := pl.GetSlot0SqrtPriceX96(position.PoolKey())
	if err != nil {
		panic(err)
	}
	token0Balance, token1Balance := gnsmath.GetAmountsForLiquidity(
		u256.MustFromDecimal(sqrtPriceX96), // currentSqrtPriceX96
		gnsmath.TickMathGetSqrtRatioAtTick(position.TickLower()),
		gnsmath.TickMathGetSqrtRatioAtTick(position.TickUpper()),
		liquidity,
	)

	return gnsmath.SafeConvertToInt64(token0Balance), gnsmath.SafeConvertToInt64(token1Balance)
}

package position

import (
	"chain"
	"strconv"
	"strings"

	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/mdtable/v0"
	ufmt "gno.land/p/nt/ufmt/v0"

	"gno.land/r/gnoswap/halt/v1"
	positionRoot "gno.land/r/gnoswap/position"
)

func (p *positionV1) Render(path string) string {
	if path == "" {
		return p.renderSummary()
	}

	positionID, ok := parsePositionRenderPath(path)
	if !ok {
		return "404\n"
	}

	storedPosition, exists := p.store.GetPosition(positionID)
	if !exists {
		return "404\n"
	}

	return p.renderPositionDetail(positionID, storedPosition)
}

func (p *positionV1) renderSummary() string {
	out := md.H1("Gnoswap Position")
	out += md.Paragraph(
		"Position records remain stored after burning. The record count includes burned " +
			"positions and is not a count of active liquidity positions. Use " +
			md.InlineCode("id/<id>") + " for one stored record, for example " +
			md.Link("id/1", "/r/gnoswap/position:id/1") +
			". The detail route performs one keyed lookup and does not enumerate positions or recompute claimable values.",
	)
	runtimeTable := mdtable.Table{
		Headers: []string{"Field", "Value"},
		Rows: [][]string{
			{"Realm address", md.InlineCode(chain.PackageAddress("gno.land/r/gnoswap/position").String())},
			{"Active implementation", renderPackageLink(positionRoot.GetImplementationPackagePath())},
			{"Position operations halted", ufmt.Sprintf("%t", halt.IsHaltedPosition())},
			{"Withdrawals halted", ufmt.Sprintf("%t", halt.IsHaltedWithdraw())},
		},
	}
	out += md.H2("Runtime") + runtimeTable.String()

	records := mdtable.Table{
		Headers: []string{"Field", "Value"},
		Rows: [][]string{
			{"Stored position records (including burned)", ufmt.Sprintf("%d", p.store.GetPositions().Size())},
			{"Next position ID", ufmt.Sprintf("%d", p.store.GetPositionNextID())},
		},
	}
	return out + md.H2("Stored records") + records.String()
}

func (p *positionV1) renderPositionDetail(positionID uint64, stored positionRoot.Position) string {
	status := "Active"
	if stored.Burned() {
		status = "Burned (record retained)"
	}

	owner := "unavailable"
	ownerAddress, err := p.nftAccessor.OwnerOf(positionIdFrom(positionID))
	if err == nil && ownerAddress != "" {
		owner = ownerAddress.String()
	}

	token0, token1, poolFee, validPoolKey := splitPoolKeyForRender(stored.PoolKey())
	token0Reference := "unavailable (stored pool key is not token0:token1:fee)"
	token1Reference := token0Reference
	if validPoolKey {
		token0Reference = renderPackageLink(token0)
		token1Reference = renderPackageLink(token1)
	}

	out := md.H1(ufmt.Sprintf("Gnoswap Position %d", positionID))
	out += md.Paragraph(
		"This page reads one persisted position record. Stored accounting fields are " +
			"shown as stored; claimable fees and current token balances are recomputed " +
			"values and are intentionally not queried here.",
	)
	identity := mdtable.Table{
		Headers: []string{"Field", "Value"},
		Rows: [][]string{
			{"Position ID", ufmt.Sprintf("%d", positionID)},
			{"Status", status},
			{"Owner", owner},
		},
	}
	out += md.H2("Identity") + identity.String()

	poolAndRange := mdtable.Table{
		Headers: []string{"Field", "Value"},
		Rows: [][]string{
			{"Pool key", md.InlineCode(stored.PoolKey())},
			{"Token 0 reference", token0Reference},
			{"Token 1 reference", token1Reference},
			{"Pool fee (from stored key)", poolFee},
			{"Lower tick (stored)", ufmt.Sprintf("%d", stored.TickLower())},
			{"Upper tick (stored)", ufmt.Sprintf("%d", stored.TickUpper())},
		},
	}
	out += md.H2("Pool and range") + poolAndRange.String()

	accounting := mdtable.Table{
		Headers: []string{"Field", "Value"},
		Rows: [][]string{
			{"Liquidity (stored)", stored.Liquidity()},
			{"Fee growth token 0 inside, last X128 (stored)", stored.FeeGrowthInside0LastX128()},
			{"Fee growth token 1 inside, last X128 (stored)", stored.FeeGrowthInside1LastX128()},
			{"Token 0 owed (stored accounting)", ufmt.Sprintf("%d", stored.TokensOwed0())},
			{"Token 1 owed (stored accounting)", ufmt.Sprintf("%d", stored.TokensOwed1())},
			{"Claimable fees / current token balances", "Not rendered; would require recomputation"},
		},
	}
	return out + md.H2("Stored accounting") + accounting.String()
}

func parsePositionRenderPath(path string) (uint64, bool) {
	const prefix = "id/"
	if len(path) <= len(prefix) || path[:len(prefix)] != prefix {
		return 0, false
	}

	id := path[len(prefix):]
	for i := 0; i < len(id); i++ {
		if id[i] < '0' || id[i] > '9' {
			return 0, false
		}
	}

	positionID, err := strconv.ParseUint(id, 10, 64)
	if err != nil {
		return 0, false
	}

	return positionID, true
}

func splitPoolKeyForRender(poolKey string) (string, string, string, bool) {
	parts := strings.Split(poolKey, ":")
	if len(parts) != 3 || parts[0] == "" || parts[1] == "" || parts[2] == "" {
		return "", "", "", false
	}

	return parts[0], parts[1], parts[2], true
}

func renderPackageLink(path string) string {
	if strings.HasPrefix(path, "gno.land/") {
		destination := strings.TrimPrefix(path, "gno.land")
		// Token references append .SYMBOL; link to the defining realm.
		if separator := strings.Index(destination, "."); separator >= 0 {
			destination = destination[:separator]
		}
		return md.Link(path, destination)
	}

	return md.InlineCode(path)
}

package position

import (
	"chain"

	"gno.land/r/gnoswap/access/v1"

	u256 "gno.land/p/gnoswap/uint256/v1"
	"gno.land/p/gnoswap/utils/v1"
	ufmt "gno.land/p/nt/ufmt/v0"

	"gno.land/r/gnoswap/common"
	"gno.land/r/gnoswap/emission"
	"gno.land/r/gnoswap/halt/v1"
)

// Reposition adjusts the price range and liquidity of an existing position.
//
// Parameters:
//   - _: leading integer discriminator; callers pass 0
//   - rlm: current realm context forwarded from the public wrapper; the implementation validates it as current
//   - positionId: NFT token ID to reposition
//   - tickLower: new lower tick boundary of the position's price range
//   - tickUpper: new upper tick boundary of the position's price range
//   - amount0DesiredStr: desired token0 amount for the new position, represented as a decimal string
//   - amount1DesiredStr: desired token1 amount for the new position, represented as a decimal string
//   - amount0MinStr: minimum acceptable token0 amount for slippage protection
//   - amount1MinStr: minimum acceptable token1 amount for slippage protection
//   - deadline: transaction expiration timestamp
//
// Returns:
//   - positionId: NFT token ID that was repositioned
//   - liquidity: new liquidity amount, represented as a decimal string
//   - tickLower: lower tick boundary applied to the position
//   - tickUpper: upper tick boundary applied to the position
//   - amount0: actual token0 amount added to the new range, represented as a decimal string
//   - amount1: actual token1 amount added to the new range, represented as a decimal string
func (p *positionV1) Reposition(
	_ int,
	rlm realm,
	positionId uint64,
	tickLower int32,
	tickUpper int32,
	amount0DesiredStr string,
	amount1DesiredStr string,
	amount0MinStr string,
	amount1MinStr string,
	deadline int64,
) (uint64, string, int32, int32, string, string) {
	access.AssertIsRlmCurrent(0, rlm)

	halt.AssertIsNotHaltedPosition()

	previousRealm := rlm.Previous()
	caller := previousRealm.Address()
	assertIsOwnerForToken(p, positionId, caller)
	assertIsNotExpired(deadline)

	emission.MintAndDistributeGns(cross(rlm))

	// The position must be clear (zero liquidity and zero tokens owed) before
	// it can be repositioned.
	position := p.mustGetPosition(positionId)

	token0, token1, _ := splitOf(position.PoolKey())
	common.AssertIsNotHandleNativeCoin()

	oldTickLower := position.TickLower()
	oldTickUpper := position.TickUpper()

	if !position.IsClear() {
		panic(newErrorWithDetail(
			errNotClear,
			ufmt.Sprintf(
				"position(%d) isn't clear(liquidity:%s, tokensOwed0:%d, tokensOwed1:%d)",
				positionId,
				position.Liquidity(),
				position.TokensOwed0(),
				position.TokensOwed1(),
			),
		))
	}

	if err := validateTokenPath(token0, token1); err != nil {
		panic(newErrorWithDetail(err.Error(), ufmt.Sprintf("token0(%s), token1(%s)", token0, token1)))
	}

	poolKey := position.PoolKey()

	liquidity, amount0, amount1 := p.addLiquidity(
		0,
		rlm,
		AddLiquidityParams{
			poolKey:        poolKey,
			tickLower:      tickLower,
			tickUpper:      tickUpper,
			amount0Desired: u256.MustFromDecimal(amount0DesiredStr),
			amount1Desired: u256.MustFromDecimal(amount1DesiredStr),
			amount0Min:     u256.MustFromDecimal(amount0MinStr),
			amount1Min:     u256.MustFromDecimal(amount1MinStr),
			caller:         caller,
		},
	)

	// update position tickLower, tickUpper to new value
	// because getCurrentFeeGrowth() uses tickLower, tickUpper
	position.SetTickLower(tickLower)
	position.SetTickUpper(tickUpper)

	currentFeeGrowth, err := p.getCurrentFeeGrowth(position, caller)
	if err != nil {
		panic(newErrorWithDetail(err.Error(), "failed to get current fee growth"))
	}
	position.SetFeeGrowthInside0LastX128(currentFeeGrowth.feeGrowthInside0LastX128.ToString())
	position.SetFeeGrowthInside1LastX128(currentFeeGrowth.feeGrowthInside1LastX128.ToString())

	position.SetLiquidity(liquidity.ToString())

	// Do not reset the fee-growth checkpoints: a full decrease followed by
	// repositioning must not create an unintended unclaimed-fee balance.
	position.SetTokensOwed0(0)
	position.SetTokensOwed1(0)
	position.SetBurned(false)
	p.mustUpdatePosition(0, rlm, positionId, *position)

	pool := mustGetPool(poolKey)
	positionLiquidity, err := p.GetPositionLiquidity(positionId)
	if err != nil {
		panic(err)
	}
	tickCumulative, secondsPerLiquidityCumulativeX128, observationTimestamp, err := currentPoolObservation(poolKey)
	if err != nil {
		panic(err)
	}

	chain.Emit(
		"Reposition",
		"prevAddr", previousRealm.Address().String(),
		"prevRealm", previousRealm.PkgPath(),
		"lpPositionId", utils.FormatUint(positionId),
		"tickLower", utils.FormatInt(tickLower),
		"tickUpper", utils.FormatInt(tickUpper),
		"liquidityDelta", liquidity.ToString(),
		"amount0", amount0.ToString(),
		"amount1", amount1.ToString(),
		"prevTickLower", utils.FormatInt(oldTickLower),
		"prevTickUpper", utils.FormatInt(oldTickUpper),
		"poolPath", poolKey,
		"sqrtPriceX96", pool.Slot0SqrtPriceX96().ToString(),
		"positionLiquidity", positionLiquidity,
		"poolLiquidity", pool.Liquidity().ToString(),
		"token0Balance", utils.FormatInt(pool.BalanceToken0()),
		"token1Balance", utils.FormatInt(pool.BalanceToken1()),
		"tickCumulative", utils.FormatInt(tickCumulative),
		"secondsPerLiquidityCumulativeX128", secondsPerLiquidityCumulativeX128,
		"observationTimestamp", utils.FormatInt(observationTimestamp),
	)

	return positionId, liquidity.ToString(), tickLower, tickUpper, amount0.ToString(), amount1.ToString()
}

package position

import (
	"strconv"
	"strings"

	prabc "gno.land/p/gnoswap/rbac/v1"
	u256 "gno.land/p/gnoswap/uint256/v1"
	"gno.land/p/nt/grc721/v0"
	ufmt "gno.land/p/nt/ufmt/v0"
	"gno.land/r/gnoswap/access/v1"
	pl "gno.land/r/gnoswap/pool"
)

const MAX_UINT256 string = "115792089237316195423570985008687907853269984665640564039457584007913129639935"

func mustGetStakerAddress() address {
	return access.MustGetAddress(prabc.ROLE_STAKER.String())
}

// mustGetPool returns the read-only snapshot for poolPath.
// It panics when poolPath does not identify a pool.
func mustGetPool(poolPath string) *pl.Pool {
	pool, ok := pl.GetPools().Get(poolPath).(*pl.Pool)
	if !ok || pool == nil {
		panic(ufmt.Sprintf("expected poolPath(%s) to exist", poolPath))
	}
	return pool
}

// positionIdFrom converts positionId to grc721.TokenID type
// input: positionId uint64
// output: grc721.TokenID
func positionIdFrom(positionId uint64) grc721.TokenID {
	return grc721.TokenID(strconv.FormatUint(positionId, 10))
}

// exists checks whether positionId exists
// If positionId doesn't exist, return false, otherwise return true
// input: positionId uint64
// output: bool
func (p *positionV1) exists(positionId uint64) bool {
	return p.nftAccessor.Exists(positionIdFrom(positionId))
}

// isOwner checks whether the caller is the owner of the positionId
// If the caller is the owner of the positionId, return true, otherwise return false
// input: positionId uint64, addr std.Address
// output: bool
func (p *positionV1) isOwner(positionId uint64, addr address) bool {
	owner, err := p.nftAccessor.OwnerOf(positionIdFrom(positionId))
	if err != nil {
		return false
	}
	return owner == addr
}

// isOperator checks whether the caller is the approved operator of the positionId
// If the caller is the approved operator of the positionId, return true, otherwise return false
// input: positionId uint64, addr std.Address
// output: bool
func (p *positionV1) isOperator(positionId uint64, addr address) bool {
	operator, err := p.GetPositionOperator(positionId)
	return err == nil && operator == addr
}

// isStaked checks whether positionId is staked
// If positionId is staked, owner of positionId is staker contract
// If positionId is staked, return true, otherwise return false
// input: positionId grc721.TokenID
// output: bool
func (p *positionV1) isStaked(positionId grc721.TokenID) bool {
	exist := p.nftAccessor.Exists(positionId)
	if !exist {
		return false
	}
	owner, err := p.nftAccessor.OwnerOf(positionId)
	if err == nil && owner == mustGetStakerAddress() {
		return true
	}
	return false
}

// isOwnerOrOperator checks whether the caller is the owner or approved operator of the positionId
// If the caller is the owner or approved operator of the positionId, return true, otherwise return false
// input: addr std.Address, positionId uint64
// output: bool
func (p *positionV1) isOwnerOrOperator(positionId uint64, addr address) bool {
	if !addr.IsValid() || !p.exists(positionId) {
		return false
	}

	if p.isStaked(positionIdFrom(positionId)) {
		return p.isOperator(positionId, addr)
	}

	return p.isOwner(positionId, addr)
}

// splitOf divides poolKey into pToken0, pToken1, and pFee
// If poolKey is invalid, it will panic
//
// input: poolKey string
// output:
// - token0Path string
// - token1Path string
// - fee uint32
func splitOf(poolKey string) (string, string, uint32) {
	res := strings.Split(poolKey, ":")
	if len(res) != 3 {
		panic(newErrorWithDetail(errInvalidInput, ufmt.Sprintf("invalid poolKey(%s)", poolKey)))
	}

	pToken0, pToken1, pFeeStr := res[0], res[1], res[2]

	pFee, err := strconv.Atoi(pFeeStr)
	if err != nil {
		panic(newErrorWithDetail(errInvalidInput, ufmt.Sprintf("invalid fee(%s)", pFeeStr)))
	}

	return pToken0, pToken1, uint32(pFee)
}

func isSlippageExceeded(amount0, amount1, amount0Min, amount1Min *u256.Uint) bool {
	return !(amount0.Gte(amount0Min) && amount1.Gte(amount1Min))
}

// currentPoolObservation derives the latest stored observation from the
// Uniswap-V3-aligned Slot0 and observations surfaces.
func currentPoolObservation(poolPath string) (int64, string, int64, error) {
	slot0 := pl.GetSlot0(poolPath)
	observation, err := pl.GetObservationAt(poolPath, slot0.ObservationIndex())
	if err != nil {
		return 0, "", 0, err
	}

	return observation.TickCumulative(), observation.SecondsPerLiquidityCumulativeX128(), observation.BlockTimestamp(), nil
}

package staker

import (
	"math"
	"strconv"
	"strings"
	"time"

	prbac "gno.land/p/gnoswap/rbac/v1"
	ufmt "gno.land/p/nt/ufmt/v0"

	"gno.land/r/gnoswap/access/v1"
)

const (
	TIMESTAMP_90DAYS  = int64(7776000)
	TIMESTAMP_180DAYS = int64(15552000)
	TIMESTAMP_365DAYS = int64(31536000)

	maxIncentiveStartDelay = 7 * 24 * time.Hour

	MAX_UNIX_EPOCH_TIME = 253402300799 // 9999-12-31 23:59:59

	maxUnstakingFee = uint64(1000) // 10%
)

// assertIsValidAmount ensures the amount is non-negative.
func assertIsValidAmount(amount int64) {
	if amount < 0 {
		panic(makeErrorWithDetails(
			errInvalidInput,
			ufmt.Sprintf("amount(%d) must be positive", amount),
		))
	}
}

// assertIsValidRewardAmountFormat ensures the reward amount string is formatted as "tokenPath:amount".
func assertIsValidRewardAmountFormat(rewardAmountStr string) {
	parts := strings.SplitN(rewardAmountStr, ":", 2)
	if len(parts) != 2 {
		panic(makeErrorWithDetails(
			errInvalidInput,
			ufmt.Sprintf("invalid format for SetTokenMinimumRewardAmount params: expected 'tokenPath:amount', got '%s'", rewardAmountStr),
		))
	}
}

// assertIsDepositor ensures the caller is the owner of the deposit.
func assertIsDepositor(s *stakerV1, caller address, positionId uint64) {
	deposit := s.getDeposits().get(positionId)
	if deposit == nil {
		panic(makeErrorWithDetails(
			errDataNotFound,
			ufmt.Sprintf("positionId(%d) not found", positionId),
		))
	}

	if caller != deposit.Owner() {
		panic(makeErrorWithDetails(
			errNoPermission,
			ufmt.Sprintf("caller(%s) is not depositor(%s)", caller.String(), deposit.Owner().String()),
		))
	}
}

// assertIsIncentiveOfDeposit ensures the incentive exists and targets the pool the position is staked
// in, so a caller cannot ask a deposit to collect an incentive that can never pay it.
// assertIsIncentiveOfPool ensures the incentive targets the pool the position is staked in.
func assertIsIncentiveOfPool(s *stakerV1, poolPath string, positionId uint64, incentiveId string) {
	// get panics with errDataNotFound when the incentive does not exist.
	incentive := s.getExternalIncentives().get(incentiveId)

	if incentive.TargetPoolPath() != poolPath {
		panic(makeErrorWithDetails(
			errInvalidInput,
			ufmt.Sprintf(
				"incentiveId(%s) targets pool(%s), but positionId(%d) is staked in pool(%s)",
				incentiveId, incentive.TargetPoolPath(), positionId, poolPath,
			),
		))
	}
}

// assertHasNoExitCheckpoint ensures the position carries no reward from a previous stake.
// Collecting it here would smuggle an unbounded calculation into staking, and leaving it would
// let the next unstake overwrite the checkpoint.
func assertHasNoExitCheckpoint(s *stakerV1, positionId uint64) {
	if s.HasUnstakedPosition(positionId) {
		panic(makeErrorWithDetails(
			errUncollectedPosition,
			ufmt.Sprintf("positionId(%d) cannot be staked while its exit checkpoint owes rewards; collect after emission resumes if emission is halted", positionId),
		))
	}
}

// assertHasNoUncollectedIncentive ensures no unstaked position still owes a reward from this
// incentive, which has not been drawn down from it yet.
func assertHasNoUncollectedIncentive(s *stakerV1, incentiveId string) {
	count := s.uncollectedIncentiveCountOf(incentiveId)
	if count > 0 {
		panic(makeErrorWithDetails(
			errUncollectedPosition,
			ufmt.Sprintf("incentive(%s) is owed to %d unstaked position(s)", incentiveId, count),
		))
	}
}

// assertIsNotStaked ensures the position is not already staked.
func assertIsNotStaked(s *stakerV1, positionId uint64) {
	if s.getDeposits().Has(positionId) {
		panic(makeErrorWithDetails(
			errAlreadyStaked,
			ufmt.Sprintf("positionId(%d) already staked", positionId),
		))
	}
}

// assertIsPoolExists ensures the pool exists.
func assertIsPoolExists(s *stakerV1, poolPath string) {
	if !s.poolAccessor.ExistsPoolPath(poolPath) {
		panic(makeErrorWithDetails(
			errInvalidPoolPath,
			ufmt.Sprintf("pool(%s) does not exist", poolPath),
		))
	}
}

// assertIsValidPoolTier ensures the tier is within valid range.
func assertIsValidPoolTier(tier uint64) {
	if tier >= AllTierCount {
		panic(makeErrorWithDetails(
			errInvalidPoolTier,
			ufmt.Sprintf("tier(%d) must be less than %d", tier, AllTierCount),
		))
	}
}

// assertTier1HasSparePool ensures tier 1 keeps at least one pool after a tier change.
func assertTier1HasSparePool(currentTier, tier1Count uint64) {
	if currentTier == Tier1 && tier1Count == 1 {
		panic(makeErrorWithDetails(errInvalidPoolTier, "tier 1 must have at least one pool"))
	}
}

// assertIsGreaterThanMinimumRewardAmount ensures the reward amount meets minimum requirements.
func assertIsGreaterThanMinimumRewardAmount(s *stakerV1, rewardToken string, rewardAmount int64) {
	minReward := s.getMinimumRewardAmount()

	if minRewardInt64, found := s.store.GetTokenSpecificMinimumRewards()[rewardToken]; found {
		minReward = minRewardInt64
	}

	if rewardAmount < minReward {
		panic(makeErrorWithDetails(
			errInvalidInput,
			ufmt.Sprintf("rewardAmount(%d) is less than minimum required amount(%d)", rewardAmount, minReward),
		))
	}
}

// assertIsAllowedForExternalReward ensures the token is allowed for external rewards.
func assertIsAllowedForExternalReward(s *stakerV1, poolPath, tokenPath string) {
	// Operational stop switch: a denied token can never start a NEW incentive,
	// whether it qualifies as a pool-pair token or through the governance
	// allowlist. Collection of already-created incentives is deliberately
	// unaffected; the delivery guard in deliverExternalIncentiveReward bounds
	// that blast radius instead.
	if contains(s.store.GetDeniedRewardTokens(), tokenPath) {
		panic(makeErrorWithDetails(
			errDeniedRewardToken,
			ufmt.Sprintf("tokenPath(%s) is denied as an external reward token", tokenPath),
		))
	}

	token0, token1, _ := poolPathDivide(poolPath)

	if tokenPath == token0 || tokenPath == token1 {
		return
	}

	allowed := contains(s.store.GetAllowedTokens(), tokenPath)
	if allowed {
		return
	}

	panic(makeErrorWithDetails(
		errNotAllowedForExternalReward,
		ufmt.Sprintf("tokenPath(%s) is not allowed for external reward for poolPath(%s)", tokenPath, poolPath),
	))
}

// assertIsExternalRewardTokenAvailable ensures a pool has no unfinished incentive for the token.
func assertIsExternalRewardTokenAvailable(s *stakerV1, poolPath, tokenPath string, currentTime int64) {
	pool := s.getPools().GetPoolOrNil(poolPath)
	if pool == nil || pool.Incentives() == nil {
		return
	}

	minimumActiveIncentiveStartTime := currentTime - TIMESTAMP_365DAYS
	if minimumActiveIncentiveStartTime < 0 {
		minimumActiveIncentiveStartTime = 0
	}

	pool.Incentives().IterateIncentiveIdsByTime(minimumActiveIncentiveStartTime, math.MaxInt64, func(incentiveID string) bool {
		incentive := s.getExternalIncentives().get(incentiveID)
		if incentive == nil {
			return false
		}

		if incentive.RewardToken() != tokenPath || NewExternalIncentiveResolver(incentive).IsEnded(currentTime) {
			return false
		}

		panic(makeErrorWithDetails(
			errIncentiveAlreadyExists,
			ufmt.Sprintf(
				"rewardToken(%s) already has unfinished incentive(%s) for poolPath(%s)",
				tokenPath,
				incentiveID,
				poolPath,
			),
		))
	})
}

// assertIsValidFeeRate ensures the fee rate is within valid range (0-1000 basis points).
func assertIsValidFeeRate(fee uint64) {
	if fee > maxUnstakingFee {
		panic(makeErrorWithDetails(
			errInvalidUnstakingFee,
			ufmt.Sprintf("fee(%d) must be in range 0 ~ %d", fee, maxUnstakingFee),
		))
	}
}

// assertIsValidIncentiveStartTime ensures the incentive starts at midnight no earlier than 24 hours after creation
// and no later than 7 days after the first eligible midnight.
func assertIsValidIncentiveStartTime(startTimestamp int64) {
	// must be in seconds format, not milliseconds
	// REF: https://stackoverflow.com/a/23982005
	numStr := strconv.Itoa(int(startTimestamp))

	if len(numStr) >= 13 {
		panic(makeErrorWithDetails(
			errInvalidIncentiveStartTime,
			ufmt.Sprintf("startTimestamp(%d) must be in seconds format, not milliseconds", startTimestamp),
		))
	}

	// must be at least 24 hours from now
	minimumStartTimestamp := getMinimumIncentiveStartTimestamp()
	if startTimestamp < minimumStartTimestamp {
		panic(makeErrorWithDetails(
			errInvalidIncentiveStartTime,
			ufmt.Sprintf("startTimestamp(%d) must be at least 24 hours later", startTimestamp),
		))
	}

	maximumStartTimestamp := getMaximumIncentiveStartTimestamp()
	if startTimestamp > maximumStartTimestamp {
		panic(makeErrorWithDetails(
			errInvalidIncentiveStartTime,
			ufmt.Sprintf("startTimestamp(%d) exceeds the maximum start time policy", startTimestamp),
		))
	}

	// must be midnight of the day
	startTime := time.Unix(startTimestamp, 0)
	if !isMidnight(startTime) {
		panic(makeErrorWithDetails(
			errInvalidIncentiveStartTime,
			ufmt.Sprintf("startTime(%d = %s) must be midnight of the day", startTimestamp, startTime.String()),
		))
	}
}

// assertIsAdminGovernanceOrCreator ensures the caller may act on an incentive:
// admin and governance are the protocol-level operators, and the creator is the
// address that funded the incentive in CreateExternalIncentive.
func assertIsAdminGovernanceOrCreator(caller, creator address) {
	if caller == creator {
		return
	}
	if access.IsAuthorized(prbac.ROLE_ADMIN.String(), caller) ||
		access.IsAuthorized(prbac.ROLE_GOVERNANCE.String(), caller) {
		return
	}

	panic(makeErrorWithDetails(
		errNoPermission,
		ufmt.Sprintf(
			"caller(%s) must be admin, governance, or the incentive creator(%s)",
			caller.String(), creator.String(),
		),
	))
}

// assertIsNotStartedIncentive ensures the incentive can still be cancelled, i.e.
// it has not started and nothing has been distributed from it. Only such an
// incentive may be removed outright; anything that already emitted rewards has
// to be finalized through EndExternalIncentive so the refund accounting and the
// penalty balance stay reachable.
func assertIsNotStartedIncentive(incentiveResolver *ExternalIncentiveResolver, currentTime int64) {
	if incentiveResolver.IsStarted(currentTime) {
		panic(makeErrorWithDetails(
			errCannotCancelIncentive,
			ufmt.Sprintf(
				"incentive(%s) already started at %d, current(%d)",
				incentiveResolver.IncentiveId(), incentiveResolver.StartTimestamp(), currentTime,
			),
		))
	}

	if incentiveResolver.Refunded() {
		panic(makeErrorWithDetails(
			errCannotCancelIncentive,
			ufmt.Sprintf("incentive(%s) has already been refunded", incentiveResolver.IncentiveId()),
		))
	}

	// Defensive: a not-yet-started incentive can never have distributed a reward
	// or accrued a warmup penalty. Removing a record that carries either would
	// strand those tokens in the staker, so refuse instead of dropping it.
	if incentiveResolver.DistributedRewardAmount() != 0 || incentiveResolver.AccumulatedPenaltyAmount() != 0 {
		panic(makeErrorWithDetails(
			errCannotCancelIncentive,
			ufmt.Sprintf(
				"incentive(%s) has already accrued rewards: distributed(%d), penalty(%d)",
				incentiveResolver.IncentiveId(),
				incentiveResolver.DistributedRewardAmount(),
				incentiveResolver.AccumulatedPenaltyAmount(),
			),
		))
	}
}

// getMinimumIncentiveStartTimestamp returns after 24 hours from now.
func getMinimumIncentiveStartTimestamp() int64 {
	return time.Now().Add(24 * time.Hour).Unix()
}

// getMaximumIncentiveStartTimestamp returns 7 days after the first midnight that satisfies
// the minimum 24-hour delay.
func getMaximumIncentiveStartTimestamp() int64 {
	minimumStartTimestamp := getMinimumIncentiveStartTimestamp()
	firstEligibleMidnight := time.Unix(minimumStartTimestamp, 0).Truncate(24 * time.Hour)
	if firstEligibleMidnight.Unix() < minimumStartTimestamp {
		firstEligibleMidnight = firstEligibleMidnight.Add(24 * time.Hour)
	}

	return firstEligibleMidnight.Add(maxIncentiveStartDelay).Unix()
}

// assertIsValidIncentiveEndTime ensures the end timestamp is within valid epoch range.
func assertIsValidIncentiveEndTime(endTimestamp int64) {
	if endTimestamp >= MAX_UNIX_EPOCH_TIME {
		panic(makeErrorWithDetails(
			errInvalidInput,
			ufmt.Sprintf("endTimestamp(%d) cannot be later than 253402300799 (9999-12-31 23:59:59)", endTimestamp),
		))
	}
}

// assertIsValidIncentiveDuration ensures the duration is 90, 180, or 365 days.
func assertIsValidIncentiveDuration(externalDuration int64) {
	switch externalDuration {
	case TIMESTAMP_90DAYS, TIMESTAMP_180DAYS, TIMESTAMP_365DAYS:
		return
	}

	panic(makeErrorWithDetails(
		errInvalidIncentiveDuration,
		ufmt.Sprintf("externalDuration(%d) must be 90, 180, 365 days", externalDuration),
	))
}

// AssertIsValidAddress panics if the provided address is invalid.
func assertIsValidAddress(addr address) {
	if addr == "" || !addr.IsValid() {
		panic(makeErrorWithDetails(
			errInvalidAddress,
			ufmt.Sprintf("address(%s) is invalid", addr.String()),
		))
	}
}

// isMidnight checks if a time represents midnight (00:00:00).
func isMidnight(startTime time.Time) bool {
	hour := startTime.Hour()
	minute := startTime.Minute()
	second := startTime.Second()

	return hour == 0 && minute == 0 && second == 0
}

// assertIsPositionOwner validates that the caller has permission to operate the token.
func assertIsPositionOwner(owner, caller address) {
	if owner != caller {
		panic(makeErrorWithDetails(
			errNoPermission,
			ufmt.Sprintf("caller(%s) is not owner of positionId(%s)", caller, owner),
		))
	}
}

package staker

import (
	"time"

	"gno.land/p/gnoswap/gnsmath/v1"
	ufmt "gno.land/p/nt/ufmt/v0"

	sr "gno.land/r/gnoswap/staker"
)

// Reward is a struct for storing reward for a position.
// Internal reward is the GNS reward, external reward is the reward for other incentives.
// Penalties are the amount that is deducted from the reward due to the position's warmup.
type Reward struct {
	Internal        int64
	InternalPenalty int64
	External        map[string]int64 // Incentive ID -> TokenAmount
	ExternalPenalty map[string]int64 // Incentive ID -> TokenAmount
}

// aggregateRewards sums the per-warmup rewards/penalties into a single Reward.
func aggregateRewards(rewards []Reward) Reward {
	internal := int64(0)
	internalPenalty := int64(0)

	rewardLen := len(rewards)
	externalReward := make(map[string]int64, rewardLen)
	externalPenalty := make(map[string]int64, rewardLen)

	for _, reward := range rewards {
		internal = gnsmath.SafeAddInt64(internal, reward.Internal)
		internalPenalty = gnsmath.SafeAddInt64(internalPenalty, reward.InternalPenalty)

		for incentive, amount := range reward.External {
			externalReward[incentive] = gnsmath.SafeAddInt64(externalReward[incentive], amount)
		}

		for incentive, penalty := range reward.ExternalPenalty {
			externalPenalty[incentive] = gnsmath.SafeAddInt64(externalPenalty[incentive], penalty)
		}
	}

	return Reward{
		Internal:        internal,
		InternalPenalty: internalPenalty,
		External:        externalReward,
		ExternalPenalty: externalPenalty,
	}
}

// calculatePositionRewardParam is a struct for calculating position reward
type calculatePositionRewardParam struct {
	// Environmental variables
	CurrentHeight int64
	CurrentTime   int64
	Deposits      *Deposits
	Pools         *Pools
	PoolTier      *PoolTier

	// Position variables
	PositionId uint64

	// Deposit overrides the Deposits lookup for a deposit that is no longer in the tree.
	Deposit *sr.Deposit
	// Exit pins the pool state to the moment the position left the pool; nil while staked.
	Exit *sr.UnstakedPosition
}

// deposit resolves the deposit the calculation runs against.
func (self *calculatePositionRewardParam) deposit() *sr.Deposit {
	if self.Deposit != nil {
		return self.Deposit
	}

	return self.Deposits.get(self.PositionId)
}

// positionRewardUpdate carries the persisted-state changes produced (but not applied) by a calculation.
// They are applied by the update* functions, so that only the collect path mutates state while the
// calculation stays pure.
type positionRewardUpdate struct {
	poolPath    string
	pool        *sr.Pool
	poolExisted bool

	// External incentive ids discovered as newly created since the deposit's last update; they must be
	// added to the deposit's incentive index.
	newExternalIncentiveIds []string
	// Whether the deposit's LastExternalIncentiveUpdatedAt cursor should be advanced to CurrentTime.
	advanceExternalIncentiveCursor bool

	// Incentive ids the calculation actually produced a reward for, in calculation order. The collect
	// path walks this instead of iterating the reward map, so delivery order is deterministic.
	externalIncentiveIds []string
}

// positionRewardContext carries the per-position state that both the internal (GNS emission) and the
// external (incentive) reward calculations need. Resolving it once lets each path be calculated on its
// own without duplicating the deposit/pool/reward-state setup.
type positionRewardContext struct {
	deposit         *sr.Deposit
	depositResolver *DepositResolver
	poolResolver    *PoolResolver
	rewardState     *RewardState
	warmupLen       int

	update positionRewardUpdate
}

// newPositionRewardContext resolves the deposit, its pool and a fresh RewardState WITHOUT mutating
// persisted state. A missing pool is created ephemerally and its persistence is deferred to the
// update path.
func (s *stakerV1) newPositionRewardContext(param *calculatePositionRewardParam) *positionRewardContext {
	deposit := param.deposit()
	poolPath := deposit.TargetPoolPath()

	pool, poolExisted := param.Pools.Get(poolPath)
	if !poolExisted {
		// Read-only: use an ephemeral pool; persistence is deferred to updatePositionReward.
		pool = sr.NewPool(poolPath, param.CurrentTime)
	}
	poolResolver := newPoolResolverWithExit(pool, param.Exit)

	return &positionRewardContext{
		deposit:         deposit,
		depositResolver: NewDepositResolver(deposit),
		poolResolver:    poolResolver,
		rewardState:     poolResolver.RewardStateOf(deposit),
		warmupLen:       len(deposit.Warmups()),
		update: positionRewardUpdate{
			poolPath:    poolPath,
			pool:        pool,
			poolExisted: poolExisted,
		},
	}
}

// newRewards allocates the empty per-warmup reward slice the compute* methods write into.
func (self *positionRewardContext) newRewards() []Reward {
	rewards := make([]Reward, self.warmupLen)
	for i := 0; i < self.warmupLen; i++ {
		rewards[i] = Reward{
			External:        make(map[string]int64),
			ExternalPenalty: make(map[string]int64),
		}
	}

	return rewards
}

// computeInternalRewards writes the GNS emission reward and penalty of each warmup into rewards.
//
// The per-second emission-rate schedule is resolved up-front (resolveInternalRewardSegments) and fed to
// the single internal-reward calculator, so the calculation needs no reward-cache update.
func (self *positionRewardContext) computeInternalRewards(param *calculatePositionRewardParam, rewards []Reward) error {
	lastCollectTime := self.depositResolver.InternalRewardLastCollectTime()

	// Resolve the per-second reward-rate schedule (pure) and calculate internal rewards from it.
	internalSegments, err := self.poolResolver.resolveInternalRewardSegments(param.PoolTier, self.update.poolPath, lastCollectTime, param.CurrentTime)
	if err != nil {
		return err
	}
	calculatedInternalRewards, calculatedInternalPenalties := self.rewardState.calculateInternalReward(internalSegments)

	for i := 0; i < self.warmupLen; i++ {
		rewards[i].Internal = calculatedInternalRewards[i]
		rewards[i].InternalPenalty = calculatedInternalPenalties[i]
	}

	self.rewardState.reset()

	return nil
}

// discoverExternalIncentives records the incentives created since the deposit's last update on the
// update, WITHOUT mutating the deposit. The collect path adds them to the deposit's incentive index.
//
// ExternalRewardLastCollectTime falls back to StakeTime for ids not yet persisted, so a newly-discovered
// incentive yields the same calculation whether or not it is written to the deposit.
func (self *positionRewardContext) discoverExternalIncentives(param *calculatePositionRewardParam) {
	lastExternalIncentiveUpdatedAt := self.depositResolver.LastExternalIncentiveUpdatedAt()
	if lastExternalIncentiveUpdatedAt >= param.CurrentTime {
		return
	}

	// Discover incentives from this pool's own start-time index. Using the
	// local resolver keeps calculation read-only even for an ephemeral pool
	// that has not yet been persisted in param.Pools.
	newIds := make([]string, 0)
	self.poolResolver.IncentivesResolver().IterateIncentiveIdsByTime(lastExternalIncentiveUpdatedAt, param.CurrentTime, func(incentiveId string) bool {
		newIds = append(newIds, incentiveId)
		return false
	})

	self.update.newExternalIncentiveIds = newIds
	self.update.advanceExternalIncentiveCursor = true
}

// externalIncentiveIds returns the deposit's effective incentive-id set: the ids stored on the deposit
// plus the ones discoverExternalIncentives found. Call it after discoverExternalIncentives.
func (self *positionRewardContext) externalIncentiveIds() []string {
	seen := make(map[string]bool)
	incentiveIds := make([]string, 0)

	self.deposit.IterateExternalIncentiveIds(func(incentiveId string) bool {
		if !seen[incentiveId] {
			seen[incentiveId] = true
			incentiveIds = append(incentiveIds, incentiveId)
		}
		return false
	})

	for _, incentiveId := range self.update.newExternalIncentiveIds {
		if !seen[incentiveId] {
			seen[incentiveId] = true
			incentiveIds = append(incentiveIds, incentiveId)
		}
	}

	return incentiveIds
}

// computeExternalReward writes one incentive's external reward and penalty of each warmup into rewards.
// An incentive that does not exist on the pool or has not started yet contributes nothing.
func (self *positionRewardContext) computeExternalReward(param *calculatePositionRewardParam, rewards []Reward, incentiveId string) {
	incentive, ok := self.poolResolver.IncentivesResolver().Get(incentiveId)
	if !ok {
		return
	}

	incentiveResolver := NewExternalIncentiveResolver(incentive)

	// Check if incentive is active during this specific collection period
	if !incentiveResolver.IsStarted(param.CurrentTime) {
		return
	}

	// External incentivized pool.
	// Calculate reward for each warmup using per-incentive lastCollectTime
	externalLastCollectTime := self.depositResolver.ExternalRewardLastCollectTime(incentiveId)
	externalReward, externalPenalty := self.rewardState.calculateExternalReward(externalLastCollectTime, param.CurrentTime, incentive)

	for i := range externalReward {
		if externalReward[i] > 0 || externalPenalty[i] > 0 {
			rewards[i].External[incentiveId] = externalReward[i]
			rewards[i].ExternalPenalty[incentiveId] = externalPenalty[i]
		}
	}

	self.update.externalIncentiveIds = append(self.update.externalIncentiveIds, incentiveId)
	self.rewardState.reset()
}

// computeExternalRewards writes every incentive of the deposit into rewards.
func (self *positionRewardContext) computeExternalRewards(param *calculatePositionRewardParam, rewards []Reward) {
	self.discoverExternalIncentives(param)

	for _, incentiveId := range self.externalIncentiveIds() {
		self.computeExternalReward(param, rewards, incentiveId)
	}
}

// calculateCollectablePositionReward calculates the aggregated position reward WITHOUT mutating any persisted state.
//
// It is the shared, read-only entry point used by the Collectable* view getters.
// This keeps the calculation identical for every caller and guarantees views never write.
func (s *stakerV1) calculateCollectablePositionReward(currentHeight, currentTimestamp int64, positionId uint64) (Reward, error) {
	param := &calculatePositionRewardParam{
		CurrentHeight: currentHeight,
		CurrentTime:   currentTimestamp,
		Deposits:      s.getDeposits(),
		Pools:         s.getPools(),
		PoolTier:      s.getPoolTier(),
		PositionId:    positionId,
	}

	// An unstaked position quotes against its exit checkpoint, at its exit time.
	if checkpoint := s.getUnstakedPositions().get(positionId); checkpoint != nil {
		param.CurrentTime = checkpoint.ExitTime()
		param.Deposit = checkpoint.Deposit()
		param.Exit = checkpoint
	}

	rewards, _, err := s.calculatePositionReward(param)
	if err != nil {
		return Reward{}, err
	}

	return aggregateRewards(rewards), nil
}

// calculatePositionReward computes a position's per-warmup internal AND external rewards WITHOUT
// mutating persisted state. All would-be state changes are returned as a positionRewardUpdate for the
// caller to apply (collect only).
func (s *stakerV1) calculatePositionReward(param *calculatePositionRewardParam) ([]Reward, positionRewardUpdate, error) {
	ctx := s.newPositionRewardContext(param)
	rewards := ctx.newRewards()

	if err := ctx.computeInternalRewards(param, rewards); err != nil {
		return nil, positionRewardUpdate{}, err
	}
	ctx.computeExternalRewards(param, rewards)

	return rewards, ctx.update, nil
}

// calculateExternalPositionRewards computes all of a position's external incentive rewards WITHOUT
// mutating persisted state. Used by the combined collect path while GNS emission is halted.
func (s *stakerV1) calculateExternalPositionRewards(param *calculatePositionRewardParam) ([]Reward, positionRewardUpdate) {
	ctx := s.newPositionRewardContext(param)
	rewards := ctx.newRewards()

	ctx.computeExternalRewards(param, rewards)

	return rewards, ctx.update
}

// calculateInternalPositionReward computes only a position's per-warmup GNS emission rewards, WITHOUT
// mutating persisted state. Used by the emission collect path.
func (s *stakerV1) calculateInternalPositionReward(param *calculatePositionRewardParam) ([]Reward, positionRewardUpdate, error) {
	ctx := s.newPositionRewardContext(param)
	rewards := ctx.newRewards()

	if err := ctx.computeInternalRewards(param, rewards); err != nil {
		return nil, positionRewardUpdate{}, err
	}

	return rewards, ctx.update, nil
}

// calculateExternalPositionReward computes a position's per-warmup reward for one external incentive,
// WITHOUT mutating persisted state. Used by the external incentive collect path.
//
// Incentive discovery still runs over every incentive, so the deposit's incentive index stays complete
// no matter which incentive the caller asked for.
func (s *stakerV1) calculateExternalPositionReward(param *calculatePositionRewardParam, incentiveId string) ([]Reward, positionRewardUpdate) {
	ctx := s.newPositionRewardContext(param)
	rewards := ctx.newRewards()

	ctx.discoverExternalIncentives(param)
	ctx.computeExternalReward(param, rewards, incentiveId)

	return rewards, ctx.update
}

// persistLazyPool persists a pool that calculation created ephemerally because it did not exist yet.
func (s *stakerV1) persistLazyPool(param *calculatePositionRewardParam, updateParams positionRewardUpdate) {
	if !updateParams.poolExisted {
		param.Pools.set(updateParams.poolPath, updateParams.pool)
	}
}

// updateInternalRewardCache advances the reward cache up to CurrentTime (halving boundaries). The
// calculation itself no longer needs this, but downstream unclaimable processing (which reads
// CurrentReward) and off-chain history rely on the cache, so it is advanced on the emission collect path.
func (s *stakerV1) updateInternalRewardCache(param *calculatePositionRewardParam, updateParams positionRewardUpdate) {
	// Always at the current time, never at param.CurrentTime: the cache and the unclaimable
	// tracking it drives are pool-global, and a checkpoint collect would rewind them to its exit
	// timestamp, where the pool may have had no staked liquidity.
	param.PoolTier.cacheRewardForPool(time.Now().Unix(), param.Pools, updateParams.poolPath)
}

// applyExternalIncentiveIndex persists the deposit incentive-index updates discovered during calculation.
func (s *stakerV1) applyExternalIncentiveIndex(param *calculatePositionRewardParam, updateParams positionRewardUpdate) {
	if len(updateParams.newExternalIncentiveIds) == 0 && !updateParams.advanceExternalIncentiveCursor {
		return
	}

	deposit := param.deposit()
	for _, incentiveId := range updateParams.newExternalIncentiveIds {
		deposit.AddExternalIncentiveId(incentiveId)
	}
	if updateParams.advanceExternalIncentiveCursor {
		deposit.SetLastExternalIncentiveUpdatedAt(param.CurrentTime)
	}
}

// updatePositionReward applies the persisted-state changes produced by calculatePositionReward.
// It is called ONLY by the collect path; the Collectable* view getters discard the update.
func (s *stakerV1) updatePositionReward(param *calculatePositionRewardParam, updateParams positionRewardUpdate) {
	s.persistLazyPool(param, updateParams)
	s.updateInternalRewardCache(param, updateParams)
	s.applyExternalIncentiveIndex(param, updateParams)
}

// updateInternalPositionReward applies the state changes belonging to the emission collect path only.
func (s *stakerV1) updateInternalPositionReward(param *calculatePositionRewardParam, updateParams positionRewardUpdate) {
	s.persistLazyPool(param, updateParams)
	s.updateInternalRewardCache(param, updateParams)
}

// updateExternalPositionReward applies the state changes belonging to the external collect path only.
func (s *stakerV1) updateExternalPositionReward(param *calculatePositionRewardParam, updateParams positionRewardUpdate) {
	s.persistLazyPool(param, updateParams)
	s.applyExternalIncentiveIndex(param, updateParams)
}

// internalRewardSegment is a [start, end) span over which the per-second emission reward rate is constant.
type internalRewardSegment struct {
	start           int64
	end             int64
	rewardPerSecond int64
}

// resolveInternalRewardSegments builds the per-second reward-rate schedule over [startTime, endTime]
// WITHOUT mutating state.
//
// Persisted reward-cache entries cover the historical portion: they record tier/count changes and any
// halvings already materialized by past collects, so no un-materialized halving exists strictly between
// two persisted entries. The tail beyond the last persisted entry is split by halvings using the current
// tier ratio/count, which are necessarily constant there (a change would have written a cache entry). The
// tail rate is recomputed with the same calculatePoolReward arithmetic the cache writer uses, so a
// schedule resolved from a fully materialized cache and one resolved from the emission halvings are
// identical.
func (self *PoolResolver) resolveInternalRewardSegments(poolTier *PoolTier, poolPath string, startTime, endTime int64) ([]internalRewardSegment, error) {
	segments := make([]internalRewardSegment, 0)
	if startTime >= endTime {
		return segments, nil
	}

	currentReward := self.CurrentReward(startTime)
	cursor := startTime

	self.RewardCache().Iterate(startTime, endTime, func(key int64, value any) bool {
		reward, ok := value.(int64)
		if !ok {
			panic(ufmt.Sprintf("failed to cast value to int64: %T", value))
		}

		segments = append(segments, internalRewardSegment{start: cursor, end: key, rewardPerSecond: currentReward})
		cursor = key
		currentReward = reward
		return false
	})

	if cursor < endTime {
		var err error
		segments, err = appendInternalRewardTailSegments(segments, poolTier, poolPath, cursor, endTime, currentReward, self.exit)
		if err != nil {
			return nil, err
		}
	}

	return segments, nil
}

// appendInternalRewardTailSegments appends the schedule for the tail [startTime, endTime], where no
// persisted cache entry exists beyond startTime. Over this span tier/count are constant, so the rate
// changes only at halving boundaries.
func appendInternalRewardTailSegments(segments []internalRewardSegment, poolTier *PoolTier, poolPath string, startTime, endTime, baseReward int64, exit *sr.UnstakedPosition) ([]internalRewardSegment, error) {
	// A checkpoint reads the tier context it exited under: this window closed at the exit, and
	// the live lookup is skipped so a checkpoint collect never depends on live tier state.
	var tier, ratio, count uint64
	if exit != nil {
		tier, ratio, count = exit.Tier(), exit.TierRatio(), exit.TierCount()
	} else {
		var err error
		tier, ratio, count, err = poolTier.tierContextOf(poolPath)
		if err != nil {
			return nil, err
		}
	}

	if tier == 0 || tier >= AllTierCount {
		// Not currently tiered: the rate cannot increase; the base is 0 after de-tier.
		return append(segments, internalRewardSegment{start: startTime, end: endTime, rewardPerSecond: baseReward}), nil
	}

	tierRatioInt64 := int64(ratio)
	tierCount := int64(count)

	halvingTimestamps, halvingEmissions, err := poolTier.getHalvingBlocksInRange(startTime, endTime)
	if err != nil {
		return nil, err
	}

	segStart := startTime
	rate := baseReward
	for i, hv := range halvingTimestamps {
		if hv <= segStart {
			// Halving effective at/before the segment start: only switch the rate.
			rate, err = calculatePoolReward(halvingEmissions[i], tierRatioInt64, tierCount)
			if err != nil {
				return nil, err
			}
			continue
		}
		if hv >= endTime {
			break
		}

		segments = append(segments, internalRewardSegment{start: segStart, end: hv, rewardPerSecond: rate})
		rate, err = calculatePoolReward(halvingEmissions[i], tierRatioInt64, tierCount)
		if err != nil {
			return nil, err
		}
		segStart = hv
	}

	return append(segments, internalRewardSegment{start: segStart, end: endTime, rewardPerSecond: rate}), nil
}

// calculates internal unclaimable reward for the pool
func (s *stakerV1) processUnClaimableReward(poolPath string, endTimestamp int64) int64 {
	pool, ok := s.getPools().Get(poolPath)
	if !ok {
		return 0
	}
	poolResolver := NewPoolResolver(pool)

	return poolResolver.processUnclaimableReward(endTimestamp)
}

// update deposit's incentive list with new incentives created since last update
func (s *stakerV1) getExternalIncentiveIdsBy(poolPath string, startTime, endTime int64) []string {
	currentIncentiveIds := make([]string, 0)

	pool, ok := s.getPools().Get(poolPath)
	if !ok {
		return currentIncentiveIds
	}
	poolResolver := NewPoolResolver(pool)

	// Look up the pool's own start-time index instead of a global
	// creation-time index. The index is scoped to this pool's incentives, so
	// discovery cost is bounded by the number of incentives for this pool
	// within the queried range, and no longer grows with the total number of
	// incentives system-wide.
	poolResolver.IncentivesResolver().IterateIncentiveIdsByTime(startTime, endTime, func(incentiveId string) bool {
		currentIncentiveIds = append(currentIncentiveIds, incentiveId)
		return false
	})

	return currentIncentiveIds
}

// getInitialCollectTime determines the initial collection time for an incentive
// by taking the maximum of the deposit's stake time and the incentive's start time.
// This ensures rewards are only calculated from when both conditions are met:
// - The position must be staked (deposit.stakeTime)
// - The incentive must be active (incentive.startTimestamp)
//
// This function is used for lazy initialization when a position collects
// from an incentive for the first time, avoiding the need to iterate through
// all deposits when a new incentive is created.
func getInitialCollectTime(deposit *sr.Deposit, incentive *sr.ExternalIncentive) int64 {
	if deposit.StakeTime() > incentive.StartTimestamp() {
		return deposit.StakeTime()
	}
	return incentive.StartTimestamp()
}

package staker

const (
	GNS_TOKEN_KEY    string = "gno.land/r/gnoswap/gns.GNS"
	WUGNOT_TOKEN_KEY string = "gno.land/r/gnoland/wugnot.wugnot"
)

// package staker manages liquidity mining rewards for GnoSwap positions.
//
// The staker distributes GNS emissions and external incentives to liquidity
// providers based on their position size, price range, and staking duration.
// It supports both internal GNS rewards and external token incentives.
//
// Reward calculations combine elapsed-time rates with tick/range accumulation, and
// collection flows are integrated into the staking lifecycle.
package staker

package staker

import (
	i256 "gno.land/p/gnoswap/int256/v1"
	u256 "gno.land/p/gnoswap/uint256/v1"
	"gno.land/p/gnoswap/utils/v1"
)

type tickCrossEventInfo struct {
	tickID               int32
	stakedLiquidityGross *u256.Uint
	stakedLiquidityDelta *i256.Int
	outsideAccumulation  *u256.Uint
}

// ToString serializes tick-cross information as a compact JSON object for event emission.
// - t: Tick ID
// - slg: Staked Liquidity Gross
// - sld: Staked Liquidity Delta
// - oa: Outside Accumulation
//
// Returns:
//   - json: JSON object string containing the tick ID and the three encoded liquidity/accumulation values.
func (t *tickCrossEventInfo) ToString() string {
	return "{\"t\":" + utils.FormatInt(t.tickID) +
		",\"slg\":\"" + t.stakedLiquidityGross.ToString() + "\"" +
		",\"sld\":\"" + t.stakedLiquidityDelta.ToString() + "\"" +
		",\"oa\":\"" + t.outsideAccumulation.ToString() + "\"}"
}

// NewTickCrossEventInfo captures the values emitted when a swap crosses a tick.
//
// Parameters:
//   - tickID: Tick index crossed during the swap.
//   - stakedLiquidityGross: Total staked liquidity at the crossed tick.
//   - stakedLiquidityDelta: Net staked liquidity change applied at the crossed tick.
//   - outsideAccumulation: Reward-ratio accumulation outside the crossed tick.
//
// Returns:
//   - info: Event payload containing the supplied tick-cross values.
func NewTickCrossEventInfo(tickID int32, stakedLiquidityGross *u256.Uint, stakedLiquidityDelta *i256.Int, outsideAccumulation *u256.Uint) *tickCrossEventInfo {
	return &tickCrossEventInfo{
		tickID:               tickID,
		stakedLiquidityGross: stakedLiquidityGross,
		stakedLiquidityDelta: stakedLiquidityDelta,
		outsideAccumulation:  outsideAccumulation,
	}
}

