// createProposal handles proposal creation logic.
// Validates input data, checks proposer eligibility, and creates proposal object.
func (gv *governanceV1) createProposal(
	_ int, rlm realm,
	proposalType governance.ProposalType,
	config governance.Config,
	maxVotingWeight int64,
	quorumWeight int64,
	snapshotTime int64,
	proposalMetadata *governance.ProposalMetadata,
	proposalData *governance.ProposalData,
	proposerAddress address,
	proposerXGnsBalance int64,
	createdAt int64,
	createdHeight int64,
) (*governance.Proposal, error) {
	// Validate proposal metadata (title and description)
	metadataResolver := NewProposalMetadataResolver(proposalMetadata)
	err := metadataResolver.Validate()
	if err != nil {
		return nil, err
	}

	// Validate proposal data (type-specific validation)
	dataResolver := NewProposalDataResolver(proposalData)
	err = dataResolver.Validate()
	if err != nil {
		return nil, err
	}

	// Check if proposer has enough xGNS balance to create proposal
	if proposerXGnsBalance < config.ProposalCreationThreshold {
		return nil, errors.New(errNotEnoughBalance)
	}

	// Generate unique proposal ID
	proposalID := gv.nextProposalID(0, rlm)

	// Create proposal status with voting schedule and requirements
	proposalStatus := NewProposalStatus(
		config,
		maxVotingWeight,
		proposalType.IsExecutable(),
		createdAt,
		quorumWeight,
	)

	// Get current configuration version for tracking
	configVersion := gv.getCurrentConfigVersion()

	// Create the proposal object with a timestamp anchor for lazy voting-weight lookup
	proposal := governance.NewProposal(
		proposalID,
		proposalStatus,
		proposalMetadata,
		proposalData,
		proposerAddress,
		configVersion,
		snapshotTime,
		createdHeight,
	)

	// Store the proposal in state
	success := gv.addProposal(0, rlm, proposal)
	if !success {
		return nil, errors.New(errDataNotFound)
	}

	return proposal, nil
}

// getVotingWeightSnapshot retrieves the averaged total voting weight for proposal creation.
// It uses two snapshots (current and current - smoothingPeriod) and averages them.
func (gv *governanceV1) getVotingWeightSnapshot(
	current,
	smoothingPeriod int64,
) (int64, int64, error) {
	// Calculate the earlier timestamp by subtracting the smoothing duration
	snapshotTime := current - smoothingPeriod
	if snapshotTime < 0 {
		snapshotTime = 0
	}

	// Get total delegation at the earlier timestamp from staker history
	totalAtSnapshot, ok := gv.stakerAccessor.GetTotalDelegationAmountAtSnapshot(snapshotTime)
	if !ok {
		totalAtSnapshot = 0
	}

	totalAtCurrent, ok := gv.stakerAccessor.GetTotalDelegationAmountAtSnapshot(current)
	if !ok {
		totalAtCurrent = 0
	}

	totalVotingWeight := gnsmath.SafeAddInt64(totalAtSnapshot, totalAtCurrent) / 2
	if totalVotingWeight <= 0 {
		return 0, snapshotTime, errors.New(errNotEnoughVotingWeight)
	}

	return totalVotingWeight, snapshotTime, nil
}

package governance

import (
	"chain"
	"chain/runtime"
	"time"

	"gno.land/r/gnoswap/access/v1"

	gnsmath "gno.land/p/gnoswap/gnsmath/v1"
	"gno.land/p/gnoswap/utils/v1"

	"gno.land/r/gnoswap/emission"

	"gno.land/r/gnoswap/gov/governance"
)

// Vote casts a vote on a proposal.
//
// Records an on-chain vote with weight based on delegated xGNS.
// Uses the proposal's timestamp anchors and configured smoothing duration to
// prevent manipulation. Votes are final and cannot be changed.
//
// Parameters:
//   - _: leading realm-call discriminator; callers pass 0 while threading the realm context
//   - rlm: current realm context; implementation validates it before reading or writing governance state
//   - proposalID: ID of the proposal to vote on
//   - yes: true for yes vote, false for no vote
//
// Vote Weight Calculation:
//   - Based on the voter's delegated xGNS amount
//   - Averages delegation at the stored smoothing timestamp and proposal creation time
//   - Uses Unix timestamp history, not a block-height snapshot
//   - Includes self-delegation and delegations received by the voter
//
// Requirements:
//   - Proposal must be in voting period
//   - Voter must have xGNS delegated at one of the lookup timestamps
//   - Cannot vote twice on same proposal
//   - Voting period is 7 days by default and is configurable
//
// Returns:
//   - voteWeight: voting weight applied to the caller's vote, formatted as a string
func (gv *governanceV1) Vote(_ int, rlm realm, proposalID int64, yes bool) string {
	access.AssertIsRlmCurrent(0, rlm)

	assertIsNotHaltedGovernanceForProposal(gv, proposalID)

	// Get current blockchain state and caller information
	currentHeight := runtime.ChainHeight()
	currentAt := time.Now()

	// Mint and distribute GNS tokens as part of the voting process
	emission.MintAndDistributeGns(cross(rlm))

	// Extract voter address from realm context
	voterRealm := rlm.Previous()
	voter := voterRealm.Address()

	// Process the vote and get updated vote tallies
	userVote, totalYesVoteWeight, totalNoVoteWeight, err := gv.vote(
		0, rlm,
		proposalID,
		voter,
		yes,
		currentHeight,
		currentAt.Unix(),
	)
	if err != nil {
		panic(err)
	}

	// Emit voting event for tracking and transparency
	voteWeight := utils.FormatInt(userVote.VotedWeight())
	voterStr := voter.String()

	chain.Emit(
		"Vote",
		"prevAddr", voterStr,
		"prevPkgPath", voterRealm.PkgPath(),
		"proposalId", utils.FormatInt(proposalID),
		"voter", voterStr,
		"yes", userVote.VotingType(),
		"voteWeight", voteWeight,
		"voteYes", utils.FormatInt(totalYesVoteWeight),
		"voteNo", utils.FormatInt(totalNoVoteWeight),
	)

	return voteWeight
}

// vote handles core voting logic.
func (gv *governanceV1) vote(
	_ int, rlm realm,
	proposalID int64,
	voterAddress address,
	votedYes bool,
	votedHeight,
	votedAt int64,
) (governance.VotingInfo, int64, int64, error) {
	// Retrieve the proposal from storage
	proposal, ok := gv.getProposal(proposalID)
	if !ok {
		return governance.DefaultVotingInfo(), 0, 0, makeErrorWithDetails(errDataNotFound, "not found proposal")
	}

	proposalResolver := NewProposalResolver(proposal)

	// Check if current time is within voting period
	if !proposalResolver.IsVotingPeriod(votedAt) {
		return governance.DefaultVotingInfo(), 0, 0, makeErrorWithDetails(errUnableToVoteOutOfPeriod, "cannot vote out of voting period")
	}

	// Get user's voting weight by averaging timestamp-history values at the
	// proposal's stored smoothing anchor and creation time.
	snapshotTime := proposal.SnapshotTime()
	createdAt := proposal.CreatedAt()

	weightAtSnapshot, ok := gv.stakerAccessor.GetUserDelegationAmountAtSnapshot(voterAddress, snapshotTime)
	if !ok {
		weightAtSnapshot = 0
	}

	weightAtCreated, ok := gv.stakerAccessor.GetUserDelegationAmountAtSnapshot(voterAddress, createdAt)
	if !ok {
		weightAtCreated = 0
	}

	votingWeight := gnsmath.SafeAddInt64(weightAtSnapshot, weightAtCreated) / 2
	if votingWeight <= 0 {
		return governance.DefaultVotingInfo(), 0, 0, makeErrorWithDetails(
			errNotEnoughVotingWeight, "no voting weight at snapshot time")
	}

	userVote, exists := gv.getProposalUserVotingInfo(proposalID, voterAddress)
	if !exists {
		userVote = governance.NewVotingInfo(votingWeight)
	}

	if userVote.IsVoted() {
		return governance.DefaultVotingInfo(), 0, 0, makeErrorWithDetails(errAlreadyVoted, "user has already voted")
	}
	userVote = governance.NewVotedVotingInfo(votingWeight, votedYes, votingWeight, votedHeight, votedAt)

	votingInfosTree, _ := gv.getProposalUserVotingInfos(proposalID)
	if votingInfosTree == nil {
		return governance.DefaultVotingInfo(), 0, 0, makeErrorWithDetails(
			errDataNotFound, "voting infos tree not found for proposal")
	}

	votingInfosTree.Set(voterAddress.String(), userVote)
	err := gv.store.SetProposalVotingInfos(0, rlm, proposalID, votingInfosTree)
	if err != nil {
		return governance.DefaultVotingInfo(), 0, 0, err
	}

	// Update proposal vote tallies
	err = proposalResolver.Vote(votedYes, votingWeight)
	if err != nil {
		return governance.DefaultVotingInfo(), 0, 0, err
	}

	return userVote, proposal.VotingYesWeight(), proposal.VotingNoWeight(), nil
}

package governance

import (
	"strconv"

	"gno.land/r/gnoswap/gov/governance"
)

func init(cur realm) {
	registerGovernanceV1(cur)
}

func registerGovernanceV1(cur realm) {
	governance.RegisterInitializer(cross(cur), func(_ int, rlm realm, governanceStore governance.IGovernanceStore, stakerAccessor governance.GovStakerAccessor) governance.IGovernance {
		// `rlm` here is the governance proxy realm threaded in by
		// governance.RegisterInitializer. Per-version store bootstrap
		// writes therefore pass the proxy's KV-store ACL.
		err := initStoreData(0, rlm, governanceStore)
		if err != nil {
			panic(err)
		}

		return NewGovernanceV1(governanceStore, stakerAccessor)
	})
}

func initStoreData(_ int, rlm realm, governanceStore governance.IGovernanceStore) error {
	// Initialize counters if not already set
	if !governanceStore.HasConfigCounterStoreKey() {
		err := governanceStore.SetConfigCounter(0, rlm, governance.NewCounter())
		if err != nil {
			return err
		}
	}

	if !governanceStore.HasProposalCounterStoreKey() {
		err := governanceStore.SetProposalCounter(0, rlm, governance.NewCounter())
		if err != nil {
			return err
		}
	}

	// Initialize Configs with default configuration if not already set
	if !governanceStore.HasConfigsStoreKey() {
		configs := governance.NewConfigTree()
		counter := governanceStore.GetConfigCounter()
		nextConfigVersion := counter.Next()

		configs.Set(formatConfigKey(nextConfigVersion), governance.NewDefaultConfig())

		err := governanceStore.SetConfigs(0, rlm, configs)
		if err != nil {
			return err
		}
		// Persist the mutated counter so the bumped version survives the
		// boundary into the proxy's KV store.
		if err := governanceStore.SetConfigCounter(0, rlm, counter); err != nil {
			return err
		}
	}

	if !governanceStore.HasProposalsStoreKey() {
		err := governanceStore.SetProposals(0, rlm, governance.NewProposalTree())
		if err != nil {
			return err
		}
	}

	if !governanceStore.HasActiveProposalsBySnapshotStoreKey() {
		if err := governanceStore.SetActiveProposalsBySnapshot(0, rlm, governance.NewProposalTree()); err != nil {
			return err
		}
	}

	if !governanceStore.HasProposalUserVotingInfosStoreKey() {
		err := governanceStore.SetProposalUserVotingInfos(0, rlm, governance.NewProposalUserVotingInfoTree())
		if err != nil {
			return err
		}
	}

	if !governanceStore.HasUserProposalsStoreKey() {
		err := governanceStore.SetUserProposals(0, rlm, governance.NewUserProposalTree())
		if err != nil {
			return err
		}
	}

	return nil
}

func formatConfigKey(version int64) string {
	return strconv.FormatInt(version, 10)
}

package governance

import (
	"gno.land/p/gnoswap/utils/v1"
	bptree "gno.land/p/nt/bptree/v0"
	ufmt "gno.land/p/nt/ufmt/v0"
	"gno.land/r/gnoswap/gov/governance"
)

type governanceV1 struct {
	store          governance.IGovernanceStore
	stakerAccessor governance.GovStakerAccessor
}

// NewGovernanceV1 creates a governance v1 implementation backed by the supplied
// state store and staker voting-weight accessor.
//
// Parameters:
//   - governanceStore: persistence adapter for configuration, proposals, counters, and voting information
//   - stakerAccessor: accessor that supplies delegation snapshots and total xGNS supply for governance decisions
//
// Returns:
//   - governance.IGovernance: governance manager and getter implementation using the supplied dependencies
func NewGovernanceV1(
	governanceStore governance.IGovernanceStore,
	stakerAccessor governance.GovStakerAccessor,
) governance.IGovernance {
	return &governanceV1{
		store:          governanceStore,
		stakerAccessor: stakerAccessor,
	}
}

// Config version methods
func (g *governanceV1) getCurrentConfigVersion() int64 {
	return g.store.GetConfigCounter().Get()
}

// nextConfigVersion increments and persists the config counter. It mutates the
// underlying KV store, so it requires a realm value that resolves to the
// governance proxy realm (the only writer-permitted address).
func (g *governanceV1) nextConfigVersion(_ int, rlm realm) int64 {
	counter := g.store.GetConfigCounter()
	next := counter.Next()
	if err := g.store.SetConfigCounter(0, rlm, counter); err != nil {
		panic(err)
	}
	return next
}

// Proposal ID methods
func (g *governanceV1) getCurrentProposalID() int64 {
	return g.store.GetProposalCounter().Get()
}

// nextProposalID increments and persists the proposal counter. Same realm
// rules as nextConfigVersion.
func (g *governanceV1) nextProposalID(_ int, rlm realm) int64 {
	counter := g.store.GetProposalCounter()
	next := counter.Next()
	if err := g.store.SetProposalCounter(0, rlm, counter); err != nil {
		panic(err)
	}
	return next
}

// Config methods
func (g *governanceV1) getConfig(version int64) (governance.Config, bool) {
	return g.store.GetConfig(version)
}

func (g *governanceV1) setConfig(_ int, rlm realm, version int64, config governance.Config) error {
	return g.store.SetConfig(0, rlm, version, config)
}

func (g *governanceV1) getCurrentConfig() (governance.Config, bool) {
	return g.getConfig(g.getCurrentConfigVersion())
}

// Proposal methods
func (g *governanceV1) getProposal(id int64) (*governance.Proposal, bool) {
	proposal, exists := g.store.GetProposal(id)
	if !exists {
		return nil, false
	}

	return proposal, true
}

func activeProposalSnapshotKey(proposal *governance.Proposal) string {
	return utils.EncodeUint64(uint64(proposal.SnapshotTime())) + utils.EncodeUint64(uint64(proposal.ID()))
}

func (g *governanceV1) addProposal(_ int, rlm realm, proposal *governance.Proposal) bool {
	// Set the proposal (ID already set in proposal)
	err := g.store.SetProposal(0, rlm, proposal.ID(), proposal)
	if err != nil {
		return false
	}

	// Add to the active snapshot index.
	snapshotIndex := g.store.GetActiveProposalsBySnapshot()
	snapshotIndex.Set(activeProposalSnapshotKey(proposal), proposal.ID())
	if err := g.store.SetActiveProposalsBySnapshot(0, rlm, snapshotIndex); err != nil {
		return false
	}

	// Add to user proposals
	err = g.store.AddUserProposal(0, rlm, proposal.Proposer().String(), proposal.ID())
	if err != nil {
		return false
	}

	return true
}

// removeActiveProposal removes a proposal from the active snapshot index.
func (g *governanceV1) removeActiveProposal(_ int, rlm realm, proposal *governance.Proposal) error {
	snapshotIndex := g.store.GetActiveProposalsBySnapshot()
	key := activeProposalSnapshotKey(proposal)
	if !snapshotIndex.Has(key) {
		return makeErrorWithDetails(errDataNotFound, ufmt.Sprintf("active proposal index entry not found, proposalID: %d", proposal.ID()))
	}
	snapshotIndex.Remove(key)

	return g.store.SetActiveProposalsBySnapshot(0, rlm, snapshotIndex)
}

// User proposals methods
func (g *governanceV1) getUserProposals(user string) []*governance.Proposal {
	proposalIDs, exists := g.store.GetUserProposalIDs(user)
	if !exists {
		return []*governance.Proposal{}
	}

	proposals := make([]*governance.Proposal, 0)

	for _, id := range proposalIDs {
		proposal, exists := g.store.GetProposal(id)
		if !exists {
			continue
		}

		proposals = append(proposals, proposal)
	}

	return proposals
}

// hasActiveProposal assumes removeInactiveUserProposals has already pruned stale proposals.
func (g *governanceV1) hasActiveProposal(proposerAddress address) bool {
	proposals := g.getUserProposals(proposerAddress.String())

	return len(proposals) > 0
}

// Remove inactive user proposals
// This function is used to remove inactive proposals from the user proposals list.
// It is used to clean up user's active proposal list when creating a new proposal.
func (g *governanceV1) removeInactiveUserProposals(_ int, rlm realm, proposerAddress address, current int64) error {
	proposals := g.getUserProposals(proposerAddress.String())

	for _, proposal := range proposals {
		proposalResolver := NewProposalResolver(proposal)

		if !proposalResolver.IsActive(current) {
			err := g.store.RemoveUserProposal(0, rlm, proposerAddress.String(), proposal.ID())
			if err != nil {
				return err
			}
		}
	}

	return nil
}

// Proposal voting info methods
func (g *governanceV1) getProposalUserVotingInfos(proposalID int64) (*bptree.BPTree, bool) {
	return g.store.GetProposalVotingInfos(proposalID)
}

func (g *governanceV1) updateProposalUserVotes(_ int, rlm realm, proposal *governance.Proposal, userVotingInfos *bptree.BPTree) error {
	return g.store.SetProposalVotingInfos(0, rlm, proposal.ID(), userVotingInfos)
}

// Helper methods for API
func (g *governanceV1) mustGetProposal(id int64) *governance.Proposal {
	proposal, exists := g.getProposal(id)
	if !exists {
		panic(makeErrorWithDetails(errProposalNotFound, ufmt.Sprintf("proposal(%d) not found", id)))
	}
	return proposal
}

func (g *governanceV1) getProposalUserVotingInfo(proposalID int64, addr address) (governance.VotingInfo, bool) {
	votingInfosTree, exists := g.getProposalUserVotingInfos(proposalID)
	if !exists {
		return governance.DefaultVotingInfo(), false
	}

	votingInfoRaw := votingInfosTree.Get(addr.String())
	if votingInfoRaw == nil {
		return governance.DefaultVotingInfo(), false
	}
	votingInfo, ok := votingInfoRaw.(governance.VotingInfo)
	return votingInfo, ok
}

package governance

import (
	"strings"

	prbac "gno.land/p/gnoswap/rbac/v1"
	ufmt "gno.land/p/nt/ufmt/v0"

	cm "gno.land/r/gnoswap/common"
	cp "gno.land/r/gnoswap/community_pool/v1"
	en "gno.land/r/gnoswap/emission"
	"gno.land/r/gnoswap/rbac/v1"

	"gno.land/r/gnoswap/gov/governance"
	gs "gno.land/r/gnoswap/gov/staker"
	lp "gno.land/r/gnoswap/launchpad"
	pl "gno.land/r/gnoswap/pool"
	pos "gno.land/r/gnoswap/position"
	pf "gno.land/r/gnoswap/protocol_fee"
	rr "gno.land/r/gnoswap/router"
	sr "gno.land/r/gnoswap/staker"

	"gno.land/r/gnoswap/halt/v1"
)

// globalParameterRegistry is initialized once and reused for all validation and execution.
// This provides consistent validation at proposal creation time and execution time.
var globalParameterRegistry *ParameterRegistry

func init() {
	globalParameterRegistry = CreateParameterHandlers()
}

// Package paths
const (
	GNS_TOKEN_KEY       = "gno.land/r/gnoswap/gns.GNS"
	HALT_PATH           = "gno.land/r/gnoswap/halt/v1"
	RBAC_PATH           = "gno.land/r/gnoswap/rbac/v1"
	ACCESS_PATH         = "gno.land/r/gnoswap/access/v1"
	EMISSION_PATH       = "gno.land/r/gnoswap/emission"
	COMMON_PATH         = "gno.land/r/gnoswap/common"
	POOL_PATH           = "gno.land/r/gnoswap/pool"
	POSITION_PATH       = "gno.land/r/gnoswap/position"
	ROUTER_PATH         = "gno.land/r/gnoswap/router"
	STAKER_PATH         = "gno.land/r/gnoswap/staker"
	LAUNCHPAD_PATH      = "gno.land/r/gnoswap/launchpad"
	PROTOCOL_FEE_PATH   = "gno.land/r/gnoswap/protocol_fee"
	COMMUNITY_POOL_PATH = "gno.land/r/gnoswap/community_pool/v1"
	GOV_GOVERNANCE_PATH = "gno.land/r/gnoswap/gov/governance"
	GOV_STAKER_PATH     = "gno.land/r/gnoswap/gov/staker"
)

// ParameterHandler interface defines the contract for parameter execution handlers.
// Each handler is responsible for executing specific parameter changes in the system.
type ParameterHandler interface {
	// Execute processes the parameters and applies the changes to the system.
	// The `_ int, rlm realm` discriminator pair forwards the governance proxy's
	// realm value into the handler so any cross-realm calls inside the closure
	// run under the proxy's identity (the only address with caller-allowlist
	// permission against the targeted /r/ realms).
	//
	// Parameters:
	//   - _: integer discriminator required by the crossing entrypoint; callers use 0
	//   - rlm: current governance proxy realm context forwarded to the handler
	//   - params: serialized parameter values to validate and apply in handler order
	//
	// Returns:
	//   - error: nil when the parameter change succeeds, or an execution/validation error
	Execute(_ int, rlm realm, params []string) error
}

// ParameterHandlerOptions contains the configuration and execution logic for a parameter handler.
// This struct encapsulates all information needed to identify and execute a parameter change.
//
// NOTE: handlerFunc uses `rlm realm` (rather than `cur realm`) as the realm
// parameter name. The v2 preprocessor reserves the `cur` name for the first
// realm-type parameter of top-level crossing function declarations and
// `t.Run` closures only; using it as the realm-parameter name on a
// multi-parameter struct-field function value trips a parser check
// ("only the first realm type argument of a crossing function may have name
// `cur`"). Naming it `rlm` keeps the lowering identical without the syntax
// constraint.
type ParameterHandlerOptions struct {
	pkgPath            string                                   // Package path of the target contract
	function           string                                   // Function name to be called
	paramCount         int                                      // Expected number of parameters
	handlerFunc        func(_ int, rlm realm, _ []string) error // Function that executes the parameter change
	paramValidators    []paramValidator                         // Optional per-parameter validators for proposal-time checks
	compositeValidator compositeValidator                       // Optional cross-parameter validator for static business rules
}

// paramValidator validates a single parameter value and returns an error on failure.
type paramValidator func(string) error

// compositeValidator validates relationships between a handler's parameters.
// It must only enforce deterministic, state-independent rules so that a
// proposal is not rejected merely because on-chain state changes while voting.
type compositeValidator func([]string) error

// NewParameterHandlerOptions creates a new parameter handler with the specified configuration.
//
// Parameters:
//   - pkgPath: package path of the target contract
//   - function: function name to be called
//   - paramCount: expected number of parameters
//   - handlerFunc: callback receiving the discriminator, propagated realm, and serialized parameters to execute the change
//   - paramValidators: optional validators for each parameter (must match paramCount if provided)
//
// Returns:
//   - ParameterHandler: configured parameter handler interface
func NewParameterHandlerOptions(
	pkgPath,
	function string,
	paramCount int,
	handlerFunc func(_ int, rlm realm, _ []string) error,
	paramValidators ...paramValidator,
) ParameterHandler {
	if len(paramValidators) > 0 && len(paramValidators) != paramCount {
		panic(ufmt.Sprintf(
			"invalid validator count for %s:%s: expected %d, got %d",
			pkgPath, function, paramCount, len(paramValidators),
		))
	}

	return &ParameterHandlerOptions{
		pkgPath:         pkgPath,
		function:        function,
		paramCount:      paramCount,
		handlerFunc:     handlerFunc,
		paramValidators: paramValidators,
	}
}

// HandlerKey generates a unique key for this handler based on package path and function name.
//
// Returns:
//   - string: unique identifier for the handler
func (h *ParameterHandlerOptions) HandlerKey() string {
	return makeHandlerKey(h.pkgPath, h.function)
}

// Execute validates parameter count and executes the handler function.
// This method ensures the correct number of parameters are provided before execution.
//
// Parameters:
//   - _: integer discriminator required by the crossing entrypoint; callers use 0
//   - rlm: governance proxy realm threaded into the wrapped handler
//   - params: serialized parameter values to pass to the handler
//
// Returns:
//   - error: parameter-count error or the error returned by the wrapped handler
func (h *ParameterHandlerOptions) Execute(_ int, rlm realm, params []string) error {
	if len(params) != h.paramCount {
		return ufmt.Errorf("expected %d parameters, got %d", h.paramCount, len(params))
	}

	return h.handlerFunc(0, rlm, params)
}

// ValidateParams checks the parameter count and runs configured individual and composite validators without executing the handler.
//
// Parameters:
//   - params: serialized parameter values to validate in handler order
//
// Returns:
//   - error: nil when all configured checks pass, or the first count/type/business-rule validation error
func (h *ParameterHandlerOptions) ValidateParams(params []string) error {
	if len(params) != h.paramCount {
		return ufmt.Errorf(
			"expected %d parameters for %s, got %d",
			h.paramCount, h.HandlerKey(), len(params),
		)
	}

	if len(h.paramValidators) > 0 {
		if len(h.paramValidators) != h.paramCount {
			return ufmt.Errorf(
				"validator count mismatch for %s: expected %d validator(s), got %d",
				h.HandlerKey(), h.paramCount, len(h.paramValidators),
			)
		}

		for i, validator := range h.paramValidators {
			if validator == nil {
				continue
			}

			if err := validator(params[i]); err != nil {
				return ufmt.Errorf("param[%d]: %v", i, err)
			}
		}
	}

	if h.compositeValidator != nil {
		if err := h.compositeValidator(params); err != nil {
			return err
		}
	}

	return nil
}

// ParameterRegistry manages the collection of parameter handlers for governance execution.
// This registry allows proposals to execute parameter changes across different system contracts.
type ParameterRegistry struct {
	handlers map[string]ParameterHandlerOptions // Map storing handler configurations keyed by package:function
}

// Register adds a new parameter handler to the registry.
// Each handler is identified by a unique combination of package path and function name.
//
// Parameters:
//   - handler: parameter handler configuration to register
func (r *ParameterRegistry) Register(handler ParameterHandlerOptions) {
	r.handlers[handler.HandlerKey()] = handler
}

// Handler retrieves a parameter handler by its package:function key.
// This method is used during proposal execution to find the appropriate handler.
//
// Parameters:
//   - key: handler key returned by HandlerKey, in "pkgPath:function" format
//
// Returns:
//   - ParameterHandler: the matching parameter handler
//   - error: error if the key has no registered handler
func (r *ParameterRegistry) Handler(key string) (ParameterHandler, error) {
	// Retrieve handler from registry
	handler, exists := r.handlers[key]
	if !exists {
		return nil, ufmt.Errorf("handler not found for %s", key)
	}

	return &handler, nil
}

// NewParameterRegistry creates a new empty parameter registry.
//
// Returns:
//   - *ParameterRegistry: new registry instance
func NewParameterRegistry() *ParameterRegistry {
	return &ParameterRegistry{handlers: make(map[string]ParameterHandlerOptions)}
}

// makeHandlerKey creates a unique identifier for a handler based on package path and function.
//
// Parameters:
//   - pkgPath: package path of the target contract
//   - function: function name to be called
//
// Returns:
//   - string: unique key in format "pkgPath:function"
func makeHandlerKey(pkgPath, function string) string {
	return pkgPath + ":" + function
}

// CreateParameterHandlers initializes and configures all supported parameter handlers.
// This function defines all the parameter changes that can be executed through governance proposals.
// It covers configuration changes for various system components including pools, staking, fees, etc.
//
// Returns:
//   - *ParameterRegistry: fully configured registry with all supported handlers
func CreateParameterHandlers() *ParameterRegistry {
	registry := NewParameterRegistry()

	// Define all handler configurations for different system components.
	//
	// Each closure receives `(_ int, rlm realm, params []string)` and threads
	// `rlm` into the targeted /r/ realm call. The closure is invoked from
	// ParameterHandlerOptions.Execute which forwards the governance proxy's
	// realm value, so cross-realm calls land on the targeted realm with the
	// governance proxy as the immediate caller.
	handlers := []*ParameterHandlerOptions{
		// Community pool token transfers
		{
			pkgPath:    COMMUNITY_POOL_PATH,
			function:   "TransferToken",
			paramCount: 3,
			paramValidators: []paramValidator{
				stringValidator,  // pkgPath
				addressValidator, // to
				positiveInt64Validator("amount"),
			},
			handlerFunc: func(_ int, rlm realm, params []string) error {
				// Transfer tokens from community pool to specified address
				cp.TransferToken(
					cross(rlm),
					params[0],          // pkgPath
					address(params[1]), // to
					parseNumber(params[2], kindInt64).(int64), // amount
				)

				return nil
			},
		},
		// Emission distribution configuration
		{
			pkgPath:    EMISSION_PATH,
			function:   "SetDistributionStartTime",
			paramCount: 1,
			paramValidators: []paramValidator{
				numberValidator(kindInt64), // start time
			},
			handlerFunc: func(_ int, rlm realm, params []string) error {
				// Set distribution start time
				en.SetDistributionStartTime(cross(rlm), parseInt64(params[0]))

				return nil
			},
		},
		{
			pkgPath:    EMISSION_PATH,
			function:   "ChangeDistributionPct",
			paramCount: 4,
			paramValidators: []paramValidator{
				numberValidator(kindInt64), // liquidityStakerPct
				numberValidator(kindInt64), // devOpsPct
				numberValidator(kindInt64), // communityPoolPct
				numberValidator(kindInt64), // govStakerPct
			},
			compositeValidator: distributionPctCompositeValidator,
			handlerFunc: func(_ int, rlm realm, params []string) error {
				liquidityStakerPct := parseNumber(params[0], kindInt64).(int64)
				devOpsPct := parseNumber(params[1], kindInt64).(int64)
