import (
	gnsmath "gno.land/p/gnoswap/gnsmath/v1"

	"gno.land/r/gnoswap/gov/staker"
)

type LaunchpadProjectDepositsResolver struct {
	*staker.LaunchpadProjectDeposits
}

// NewLaunchpadProjectDepositsResolver wraps launchpad project deposit state.
//
// Parameters:
//   - launchpadProjectDeposits: project deposit state to resolve and mutate
//
// Returns:
//   - *LaunchpadProjectDepositsResolver: resolver retaining the supplied deposit state pointer
func NewLaunchpadProjectDepositsResolver(launchpadProjectDeposits *staker.LaunchpadProjectDeposits) *LaunchpadProjectDepositsResolver {
	return &LaunchpadProjectDepositsResolver{launchpadProjectDeposits}
}

// getLaunchpadProjectDeposit retrieves the deposit amount for a launchpad project.
//
// Parameters:
//   - ownerAddress: project owner's address identifier
//
// Returns:
//   - int64: deposit amount
//   - bool: true if project exists, false otherwise
func (lpdr *LaunchpadProjectDepositsResolver) getLaunchpadProjectDeposit(ownerAddress string) (int64, bool) {
	return lpdr.LaunchpadProjectDeposits.GetDeposit(ownerAddress)
}

// setLaunchpadProjectDeposit sets the deposit amount for a launchpad project.
//
// Parameters:
//   - ownerAddress: project owner's address identifier
//   - deposit: deposit amount to set
//
// Returns:
//   - bool: true if successfully set
func (lpdr *LaunchpadProjectDepositsResolver) setLaunchpadProjectDeposit(ownerAddress string, deposit int64) bool {
	lpdr.LaunchpadProjectDeposits.SetDeposit(ownerAddress, deposit)
	return true
}

// addDeposit adds to the deposit amount for a launchpad project.
// This method ensures the deposit doesn't go negative.
//
// Parameters:
//   - ownerAddress: project owner's address identifier
//   - amount: amount to add to the deposit
func (lpdr *LaunchpadProjectDepositsResolver) addDeposit(ownerAddress string, amount int64) {
	currentDeposit, _ := lpdr.LaunchpadProjectDeposits.GetDeposit(ownerAddress)
	newDeposit := gnsmath.SafeAddInt64(currentDeposit, amount)
	if newDeposit < 0 {
		newDeposit = 0
	}
	lpdr.LaunchpadProjectDeposits.SetDeposit(ownerAddress, newDeposit)
}

// removeDeposit removes from the deposit amount for a launchpad project.
// This method ensures the deposit doesn't go negative.
//
// Parameters:
//   - ownerAddress: project owner's address identifier
//   - amount: amount to remove from the deposit
func (lpdr *LaunchpadProjectDepositsResolver) removeDeposit(ownerAddress string, amount int64) {
	currentDeposit, exists := lpdr.LaunchpadProjectDeposits.GetDeposit(ownerAddress)
	if !exists {
		return
	}
	newDeposit := gnsmath.SafeSubInt64(currentDeposit, amount)
	if newDeposit < 0 {
		newDeposit = 0
	}
	lpdr.LaunchpadProjectDeposits.SetDeposit(ownerAddress, newDeposit)
}

package staker

import (
	"errors"
	"math"

	"gno.land/p/gnoswap/gnsmath/v1"
	u256 "gno.land/p/gnoswap/uint256/v1"

	"gno.land/r/gnoswap/gov/staker"
)

// ProtocolFeeRewardManagerResolver drives the ProtocolFeeRewardManager.
//
// Stake changes only move the epoch, the total stake history and the staker's own
// event list. Fees are folded into a token's accumulator when that token is collected,
// each accrual bucket against the total stake in force during its epoch.
type ProtocolFeeRewardManagerResolver struct {
	*staker.ProtocolFeeRewardManager
}

// NewProtocolFeeRewardManagerResolver wraps the shared protocol-fee reward manager.
//
// Parameters:
//   - manager: Protocol-fee reward state to resolve and mutate.
//
// Returns:
//   - *ProtocolFeeRewardManagerResolver: resolver operating on manager's accounting state.
func NewProtocolFeeRewardManagerResolver(manager *staker.ProtocolFeeRewardManager) *ProtocolFeeRewardManagerResolver {
	return &ProtocolFeeRewardManagerResolver{
		ProtocolFeeRewardManager: manager,
	}
}

// addStake records that rewardID staked amount more from epoch on.
//
// epoch is the accrual epoch protocol_fee just opened for this change, so it must not
// be older than the epoch in force.
func (self *ProtocolFeeRewardManagerResolver) addStake(rewardID string, amount int64, epoch int64) error {
	if amount <= 0 {
		return errors.New(errAmountMustBePositive)
	}
	if epoch < self.GetCurrentEpoch() {
		return errors.New(errInvalidAccrualEpoch)
	}

	currentTotal := self.GetTotalStakedAmount()
	if currentTotal > math.MaxInt64-amount {
		return errors.New(errTotalStakedAmountOverflow)
	}

	rewardState, ok, err := self.GetRewardState(rewardID)
	if err != nil {
		return err
	}
	if !ok {
		rewardState = staker.NewProtocolFeeRewardState()
	}

	resolvedState := NewProtocolFeeRewardStateResolver(rewardState)
	if err := resolvedState.addStake(amount, epoch); err != nil {
		return err
	}

	self.recordTotalStakedAmount(epoch, gnsmath.SafeAddInt64(currentTotal, amount))
	self.SetRewardState(rewardID, rewardState)

	return nil
}

// removeStake records that rewardID staked amount less from epoch on.
func (self *ProtocolFeeRewardManagerResolver) removeStake(rewardID string, amount int64, epoch int64) error {
	if amount < 0 {
		return errors.New(errAmountMustBeNonNegative)
	}
	if epoch < self.GetCurrentEpoch() {
		return errors.New(errInvalidAccrualEpoch)
	}

	updatedTotal := gnsmath.SafeSubInt64(self.GetTotalStakedAmount(), amount)
	if updatedTotal < 0 {
		return errors.New(errRemoveAmountExceedsTotalStaked)
	}

	rewardState, ok, err := self.GetRewardState(rewardID)
	if err != nil {
		return err
	}
	if !ok {
		rewardState = staker.NewProtocolFeeRewardState()
	}

	resolvedState := NewProtocolFeeRewardStateResolver(rewardState)
	if err := resolvedState.removeStake(amount, epoch); err != nil {
		return err
	}

	self.recordTotalStakedAmount(epoch, updatedTotal)
	self.SetRewardState(rewardID, rewardState)

	return nil
}

func (self *ProtocolFeeRewardManagerResolver) recordTotalStakedAmount(epoch int64, totalStakedAmount int64) {
	self.SetCurrentEpoch(epoch)
	self.SetTotalStakedAmount(totalStakedAmount)
	self.SetTotalStakedAmountAt(epoch, totalStakedAmount)
}

// applyAccrualBuckets folds consumed accrual buckets of tokenPath into its accumulator.
//
// epochs and amounts are parallel and in ascending epoch order. Each amount is divided
// by the total stake in force during its epoch; with nothing staked the amount is
// dropped, the same policy the emission accumulator applies. exhausted reports that
// no bucket is left pending, which lets the accumulator mark every closed epoch as
// fully folded.
func (self *ProtocolFeeRewardManagerResolver) applyAccrualBuckets(
	tokenPath string,
	epochs []int64,
	amounts []int64,
	exhausted bool,
	currentTimestamp int64,
) error {
	if len(epochs) != len(amounts) {
		return errors.New(errInvalidAccrualBuckets)
	}

	accumulator, ok := self.GetTokenAccumulator(tokenPath)
	if !ok {
		if len(epochs) == 0 {
			return nil
		}
		accumulator = staker.NewProtocolFeeTokenAccumulator()
		self.SetTokenAccumulator(tokenPath, accumulator)
	}

	currentX128 := accumulator.GetAccumulatedX128PerStake().Clone()
	feeAmount := accumulator.GetProtocolFeeAmount()
	lastEpoch := int64(-1)

	for i, epoch := range epochs {
		if epoch < lastEpoch || epoch > self.GetCurrentEpoch() {
			return errors.New(errInvalidAccrualBuckets)
		}
		lastEpoch = epoch

		amount := amounts[i]
		if amount < 0 {
			return errors.New(errInvalidAccrualBuckets)
		}
		feeAmount = gnsmath.SafeAddInt64(feeAmount, amount)

		totalStakedAmount := self.GetTotalStakedAmountAt(epoch)
		if totalStakedAmount <= 0 || amount == 0 {
			continue
		}

		// Scale the amount by 2^128 before dividing by the total stake. The amount
		// fits in 63 bits, so the product fits in 191 bits and cannot overflow.
		amountX128 := u256.Zero().Lsh(u256.NewUintFromInt64(amount), 128)
		perStakeX128 := u256.Zero().Div(amountX128, u256.NewUintFromInt64(totalStakedAmount))
		currentX128 = u256.Zero().Add(currentX128, perStakeX128)

		accumulator.SetAccumulatedX128PerStakeAt(epoch, currentX128)
	}

	accumulator.SetProtocolFeeAmount(feeAmount)

	// Every epoch before the one in force is closed, so it is fully folded once no bucket
	// is left. Otherwise only the epochs up to the last consumed bucket are complete.
	foldedEpoch := accumulator.GetFoldedEpoch()
	if exhausted {
		foldedEpoch = maxInt64(foldedEpoch, self.GetCurrentEpoch()-1)
	} else if lastEpoch >= 0 {
		foldedEpoch = maxInt64(foldedEpoch, minInt64(lastEpoch, self.GetCurrentEpoch()-1))
	}
	accumulator.SetFoldedEpoch(foldedEpoch)

	self.SetAccumulatedTimestamp(currentTimestamp)

	return nil
}

// accumulatorView returns a read view of tokenPath's accumulator.
//
// With pendingComplete false the view reflects the accumulator exactly as folded so
// far, which is what a collect must settle against. With pendingComplete true the
// given buckets are the whole pending set of the token: they are projected on top, as
// applyAccrualBuckets would fold them, and every closed epoch counts as folded, which
// is what an exhaustive fold would leave behind. A query uses the latter so that it
// reports what a collect would pay even when a previous bounded fold consumed exactly
// its limit and left foldedEpoch behind the epoch in force.
func (self *ProtocolFeeRewardManagerResolver) accumulatorView(tokenPath string, pendingEpochs []int64, pendingAmounts []int64, pendingComplete bool) *protocolFeeAccumulatorView {
	view := &protocolFeeAccumulatorView{
		extraEpochs:  []int64{},
		extraValues:  []*u256.Uint{},
		current:      u256.Zero(),
		firstEpoch:   -1,
		foldedEpoch:  -1,
		currentEpoch: self.GetCurrentEpoch(),
	}

	if accumulator, ok := self.GetTokenAccumulator(tokenPath); ok {
		view.accumulator = accumulator
		view.current = accumulator.GetAccumulatedX128PerStake().Clone()
		view.firstEpoch = accumulator.GetFirstEpoch()
		view.foldedEpoch = accumulator.GetFoldedEpoch()
	}

	if pendingComplete {
		// Projecting the whole pending set folds every closed epoch.
		view.foldedEpoch = maxInt64(view.foldedEpoch, view.currentEpoch-1)
	}

	for i, epoch := range pendingEpochs {
		totalStakedAmount := self.GetTotalStakedAmountAt(epoch)
		if totalStakedAmount <= 0 || pendingAmounts[i] <= 0 {
			continue
		}

		amountX128 := u256.Zero().Lsh(u256.NewUintFromInt64(pendingAmounts[i]), 128)
		perStakeX128 := u256.Zero().Div(amountX128, u256.NewUintFromInt64(totalStakedAmount))
		view.current = u256.Zero().Add(view.current, perStakeX128)
		view.extraEpochs = append(view.extraEpochs, epoch)
		view.extraValues = append(view.extraValues, view.current.Clone())
		if view.firstEpoch < 0 {
			view.firstEpoch = epoch
		}
	}

	return view
}

// claimTokenReward settles tokenPath for rewardID and returns the reward collected.
// See ProtocolFeeRewardStateResolver.claimTokenReward for the maxEvents bound.
func (self *ProtocolFeeRewardManagerResolver) claimTokenReward(rewardID string, tokenPath string, maxEvents int64) (int64, error) {
	rewardState, ok, err := self.GetRewardState(rewardID)
	if err != nil {
		return 0, err
	}
	if !ok {
		return 0, nil
	}

	resolvedState := NewProtocolFeeRewardStateResolver(rewardState)
	reward, err := resolvedState.claimTokenReward(tokenPath, self.accumulatorView(tokenPath, nil, nil, false), maxEvents)
	if err != nil {
		return 0, err
	}

	self.SetRewardState(rewardID, rewardState)

	return reward, nil
}

// claimRewards settles every folded token for rewardID and returns the reward
// collected per token. Its cost grows with the number of tokens that ever collected a
// fee; claimTokenReward is the bounded alternative.
func (self *ProtocolFeeRewardManagerResolver) claimRewards(rewardID string, currentTimestamp int64) (map[string]int64, error) {
	rewards := make(map[string]int64)

	rewardState, ok, err := self.GetRewardState(rewardID)
	if err != nil {
		return nil, err
	}
	if !ok {
		return rewards, nil
	}

	resolvedState := NewProtocolFeeRewardStateResolver(rewardState)
	if !resolvedState.IsClaimable(currentTimestamp) {
		return rewards, nil
	}

	for _, tokenPath := range self.GetTokenPaths() {
		reward, err := resolvedState.claimTokenReward(tokenPath, self.accumulatorView(tokenPath, nil, nil, false), 0)
		if err != nil {
			return nil, err
		}
		rewards[tokenPath] = reward
	}

	resolvedState.SetClaimedTimestamp(currentTimestamp)
	self.SetRewardState(rewardID, rewardState)

	return rewards, nil
}

// GetClaimableRewardAmount returns what collecting tokenPath for rewardID would pay,
// with the given pending buckets projected on top of the accumulator.
// Parameters:
//   - rewardID: Identifier of the staker whose claimable reward is quoted.
//   - tokenPath: Token path whose claimable protocol-fee reward is quoted.
//   - pendingEpochs: Pending bucket epochs projected on the accumulator.
//   - pendingAmounts: Pending fee amounts parallel to pendingEpochs.
//
// Returns:
//   - int64: protocol-fee amount that collecting tokenPath would pay in token base units.
//   - error: nil on success; non-nil when reward-state lookup or projection fails.
func (self *ProtocolFeeRewardManagerResolver) GetClaimableRewardAmount(rewardID string, tokenPath string, pendingEpochs []int64, pendingAmounts []int64) (int64, error) {
	rewardState, ok, err := self.GetRewardState(rewardID)
	if err != nil {
		return 0, err
	}
	if !ok {
		return 0, nil
	}

	resolvedState := NewProtocolFeeRewardStateResolver(rewardState)

	return resolvedState.getClaimableReward(tokenPath, self.accumulatorView(tokenPath, pendingEpochs, pendingAmounts, true)), nil
}

func maxInt64(a, b int64) int64 {
	if a > b {
		return a
	}
	return b
}

func minInt64(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

package staker

import (
	"errors"

	"gno.land/p/gnoswap/consts/v1"
	"gno.land/p/gnoswap/gnsmath/v1"
	u256 "gno.land/p/gnoswap/uint256/v1"

	"gno.land/r/gnoswap/gov/staker"
)

// ProtocolFeeRewardStateResolver settles one staker's protocol fee rewards.
//
// A staker's reward for a token is the sum, over the segments between their stake
// events, of the stake held during the segment times the growth of the token's
// accumulated fee per stake across it. Segments are folded in event order, so the work
// of settling a token is proportional to the staker's own stake changes since the token
// was last settled, never to the number of tokens.
type ProtocolFeeRewardStateResolver struct {
	*staker.ProtocolFeeRewardState
}

// NewProtocolFeeRewardStateResolver wraps one staker's protocol fee reward state
// with settlement operations.
//
// Parameters:
//   - protocolFeeRewardState: staker reward state to resolve and mutate.
//
// Returns:
//   - *ProtocolFeeRewardStateResolver: resolver backed by protocolFeeRewardState.
func NewProtocolFeeRewardStateResolver(protocolFeeRewardState *staker.ProtocolFeeRewardState) *ProtocolFeeRewardStateResolver {
	return &ProtocolFeeRewardStateResolver{
		ProtocolFeeRewardState: protocolFeeRewardState,
	}
}

// protocolFeeAccumulatorView reads a token accumulator as it stands, optionally
// extended in memory with buckets that are still pending on the protocol fee realm.
// The extension lets a query report what a collect would pay without folding anything.
type protocolFeeAccumulatorView struct {
	accumulator *staker.ProtocolFeeTokenAccumulator // nil when the token was never folded
	// extraEpochs and extraValues hold projected history entries, in ascending epoch order
	extraEpochs []int64
	extraValues []*u256.Uint
	// current is the latest accumulated value, projection included
	current *u256.Uint
	// firstEpoch is the first epoch a fee was folded for, projection included, or -1
	firstEpoch int64
	// foldedEpoch is the last epoch whose fees are known to be fully folded, or -1
	foldedEpoch int64
	// currentEpoch is the accrual epoch in force on the manager
	currentEpoch int64
}

// at returns the accumulated value after the fees of the latest known epoch at or
// before epoch.
func (v *protocolFeeAccumulatorView) at(epoch int64) *u256.Uint {
	for i := len(v.extraEpochs) - 1; i >= 0; i-- {
		if v.extraEpochs[i] <= epoch {
			return v.extraValues[i]
		}
	}

	if v.accumulator == nil {
		return u256.Zero()
	}

	return v.accumulator.GetAccumulatedX128PerStakeAt(epoch)
}

// protocolFeeTokenSettlement is the in-memory working copy of a token's settlement
// state. It is written back only on a collect, so queries never touch storage.
type protocolFeeTokenSettlement struct {
	eventCursor         int64
	segmentStakedAmount int64
	segmentStartX128    *u256.Uint
	earnedX128          *u256.Uint
}

// loadTokenSettlement returns the settlement state of tokenPath, initialising it when
// the token was never settled for this staker.
//
// A fresh state skips every stake event at or before the accumulator's first epoch:
// the accumulator was zero throughout, so those segments earned nothing and the open
// segment can start at the last of them. When no fee was folded at all, the skip
// covers every event, but only once every closed epoch is known to be folded: a
// bucket still pending from a closed epoch could later credit one of those events,
// so until then they are settled one by one through settleEvents, which is gated by
// foldedEpoch and yields nothing while the accumulator stays at zero.
func (p *ProtocolFeeRewardStateResolver) loadTokenSettlement(tokenPath string, view *protocolFeeAccumulatorView) *protocolFeeTokenSettlement {
	if tokenState, ok := p.GetTokenState(tokenPath); ok {
		return &protocolFeeTokenSettlement{
			eventCursor:         tokenState.GetEventCursor(),
			segmentStakedAmount: tokenState.GetSegmentStakedAmount(),
			segmentStartX128:    tokenState.GetSegmentStartX128().Clone(),
			earnedX128:          tokenState.GetEarnedX128().Clone(),
		}
	}

	settlement := &protocolFeeTokenSettlement{
		eventCursor:         0,
		segmentStakedAmount: 0,
		segmentStartX128:    u256.Zero(),
		earnedX128:          u256.Zero(),
	}

	eventCount := p.GetStakeEventCount()
	if view.firstEpoch < 0 {
		if view.foldedEpoch >= view.currentEpoch-1 {
			// No fee was ever folded and nothing from a closed epoch is pending, so
			// every recorded event earned nothing.
			settlement.eventCursor = eventCount
			settlement.segmentStakedAmount = p.GetStakedAmount()
		}
		return settlement
	}

	// Stake events are appended in epoch order, so the last event at or before
	// firstEpoch is found by binary search: the lookup costs O(log n) reads no matter
	// how many stake changes the staker made since the token's first fee.
	lo, hi := int64(0), eventCount
	for lo < hi {
		mid := lo + (hi-lo)/2
		event, ok := p.GetStakeEvent(mid)
		if !ok {
			break
		}
		if event.GetEpoch() <= view.firstEpoch {
			lo = mid + 1
		} else {
			hi = mid
		}
	}

	if lo > 0 {
		if event, ok := p.GetStakeEvent(lo - 1); ok {
			settlement.eventCursor = lo
			settlement.segmentStakedAmount = event.GetStakedAmount()
		}
	}

	return settlement
}

// settleEvents folds up to maxEvents pending stake events into the settlement. An
// event can only be folded once the epoch before it is fully folded on the
// accumulator, because the segment it closes ends at that epoch's value. A maxEvents
// of zero or less folds every event it can. Returns true when no event is left pending.
func (p *ProtocolFeeRewardStateResolver) settleEvents(settlement *protocolFeeTokenSettlement, view *protocolFeeAccumulatorView, maxEvents int64) bool {
	eventCount := p.GetStakeEventCount()
	processed := int64(0)

	for settlement.eventCursor < eventCount {
		if maxEvents > 0 && processed >= maxEvents {
			return false
		}

		event, ok := p.GetStakeEvent(settlement.eventCursor)
		if !ok {
			return false
		}
		if event.GetEpoch()-1 > view.foldedEpoch {
			return false
		}

		segmentEndX128 := view.at(event.GetEpoch() - 1)
		settlement.earnedX128 = u256.Zero().Add(
			settlement.earnedX128,
			segmentRewardX128(settlement.segmentStakedAmount, settlement.segmentStartX128, segmentEndX128),
		)
		settlement.segmentStartX128 = segmentEndX128.Clone()
		settlement.segmentStakedAmount = event.GetStakedAmount()
		settlement.eventCursor++
		processed++
	}

	return true
}

// closeOpenSegment folds the open segment up to the accumulator's latest value. It may
// only be called once every stake event is settled, so that the open segment really
// ends at the present.
func closeOpenSegment(settlement *protocolFeeTokenSettlement, view *protocolFeeAccumulatorView) {
	settlement.earnedX128 = u256.Zero().Add(
		settlement.earnedX128,
		segmentRewardX128(settlement.segmentStakedAmount, settlement.segmentStartX128, view.current),
	)
	settlement.segmentStartX128 = view.current.Clone()
}

// takeReward removes the whole-unit part of the earned reward from the settlement and
// returns it. The sub-unit remainder stays earned so that no fee share is lost.
func takeReward(settlement *protocolFeeTokenSettlement) int64 {
	rewardX128 := u256.Zero().Rsh(settlement.earnedX128, 128)
	reward := gnsmath.SafeConvertToInt64(rewardX128)
	settlement.earnedX128 = u256.Zero().Sub(settlement.earnedX128, u256.Zero().Lsh(rewardX128, 128))

	return reward
}

// segmentRewardX128 returns stakedAmount times the accumulator growth across a segment.
func segmentRewardX128(stakedAmount int64, startX128, endX128 *u256.Uint) *u256.Uint {
	if stakedAmount <= 0 || !endX128.Gt(startX128) {
		return u256.Zero()
	}

	growthX128 := u256.Zero().Sub(endX128, startX128)

	return u256.Zero().Mul(growthX128, u256.NewUintFromInt64(stakedAmount))
}

// storeTokenSettlement writes the settlement back to the staker's state.
func (p *ProtocolFeeRewardStateResolver) storeTokenSettlement(tokenPath string, settlement *protocolFeeTokenSettlement) {
	tokenState, ok := p.GetTokenState(tokenPath)
	if !ok {
		tokenState = staker.NewProtocolFeeTokenRewardState(settlement.eventCursor, settlement.segmentStakedAmount, settlement.segmentStartX128)
		tokenState.SetEarnedX128(settlement.earnedX128)
		p.SetTokenState(tokenPath, tokenState)
		return
	}

	tokenState.SetSegment(settlement.eventCursor, settlement.segmentStakedAmount, settlement.segmentStartX128)
	tokenState.SetEarnedX128(settlement.earnedX128)
}

// claimTokenReward settles tokenPath and returns the reward collected.
//
// Up to maxEvents stake events are folded; whatever is settled by then is paid, and
// the rest stays pending for a later collect. A maxEvents of zero or less folds
// everything.
func (p *ProtocolFeeRewardStateResolver) claimTokenReward(tokenPath string, view *protocolFeeAccumulatorView, maxEvents int64) (int64, error) {
	// A token that never collected a fee has nothing to settle; skipping it keeps the
	// staker's state free of an entry per token merely queried.
	if _, ok := p.GetTokenState(tokenPath); !ok && view.firstEpoch < 0 {
		return 0, nil
	}

	settlement := p.loadTokenSettlement(tokenPath, view)

	if p.settleEvents(settlement, view, maxEvents) {
		closeOpenSegment(settlement, view)
	}

	reward := takeReward(settlement)
	p.storeTokenSettlement(tokenPath, settlement)

	if reward > 0 {
		if tokenState, ok := p.GetTokenState(tokenPath); ok {
			tokenState.SetClaimedReward(gnsmath.SafeAddInt64(tokenState.GetClaimedReward(), reward))
		}
	}

	return reward, nil
}

// getClaimableReward returns what a collect of tokenPath would pay right now, without
// changing any state.
func (p *ProtocolFeeRewardStateResolver) getClaimableReward(tokenPath string, view *protocolFeeAccumulatorView) int64 {
	settlement := p.loadTokenSettlement(tokenPath, view)

	if p.settleEvents(settlement, view, 0) {
		closeOpenSegment(settlement, view)
	}

	return gnsmath.SafeConvertToInt64(u256.Zero().Div(settlement.earnedX128, consts.Q128()))
}

// addStake increases the staked amount and records the change from epoch on.
func (p *ProtocolFeeRewardStateResolver) addStake(amount int64, epoch int64) error {
	if amount <= 0 {
		return errors.New(errAmountMustBePositive)
	}

	stakedAmount := gnsmath.SafeAddInt64(p.GetStakedAmount(), amount)
	p.SetStakedAmount(stakedAmount)
	p.AppendStakeEvent(epoch, stakedAmount)

	return nil
}

// removeStake decreases the staked amount and records the change from epoch on.
func (p *ProtocolFeeRewardStateResolver) removeStake(amount int64, epoch int64) error {
	if amount < 0 {
		return errors.New(errAmountMustBeNonNegative)
	}
	if amount > p.GetStakedAmount() {
		return errors.New(errRemoveAmountExceedsStaked)
	}

	stakedAmount := gnsmath.SafeSubInt64(p.GetStakedAmount(), amount)
	p.SetStakedAmount(stakedAmount)
	p.AppendStakeEvent(epoch, stakedAmount)

	return nil
}

// IsClaimable reports whether every token may be collected at once at currentTimestamp.
//
// Parameters:
//   - currentTimestamp: current Unix timestamp used to compare the last collection.
//
// Returns:
//   - bool: true when currentTimestamp is later than the state's claimed timestamp.
func (p *ProtocolFeeRewardStateResolver) IsClaimable(currentTimestamp int64) bool {
	return p.GetClaimedTimestamp() < currentTimestamp
}

package staker

import (
	"strings"

	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/mdtable/v0"
	ufmt "gno.land/p/nt/ufmt/v0"
	"gno.land/r/gnoswap/gov/staker"
)

func (g *govStakerV1) Render(path string) string {
	if path != "" {
		return "404\n"
	}

	implementation := staker.GetImplementationPackagePath()

	out := md.H1("Gnoswap Governance Staker")
	out += md.H2("Staking overview")
	overviewTable := mdtable.Table{
		Headers: []string{"Field", "Value"},
		Rows: [][]string{
			{"Active implementation", md.Link(implementation, strings.TrimPrefix(implementation, "gno.land"))},
			{"Total xGNS supply", ufmt.Sprintf("%d", staker.GetTotalxGnsSupply())},
			{"Total delegated GNS", ufmt.Sprintf("%d", staker.GetTotalDelegated())},
			{"Total locked GNS", ufmt.Sprintf("%d", staker.GetTotalLockedAmount())},
			{"Undelegation lockup period", ufmt.Sprintf("%d", staker.GetUnDelegationLockupPeriod())},
			{"Protocol-fee accumulation timestamp", ufmt.Sprintf("%d", staker.GetProtocolFeeAccumulatedTimestamp())},
		},
	}
	out += overviewTable.String()

	return out
}

package staker

import (
	"chain"
	"chain/runtime"
	"errors"
	"time"

	gnsmath "gno.land/p/gnoswap/gnsmath/v1"
	"gno.land/p/gnoswap/utils/v1"
	"gno.land/r/gnoswap/access/v1"
	"gno.land/r/gnoswap/emission"
	"gno.land/r/gnoswap/gns"

	"gno.land/r/gnoswap/gov/staker"
	"gno.land/r/gnoswap/gov/xgns"
	"gno.land/r/gnoswap/halt/v1"
	"gno.land/r/gnoswap/referral/v1"
)

// Spoofed-realm guards on entry points reject any caller that fabricates a
// realm value distinct from the current crossing frame. The proxy in
// gno.land/r/gnoswap/gov/staker always forwards its own `cur`, so a mismatch
// here means somebody bypassed the proxy and threaded a fake realm directly
// into the implementation.

// Delegate delegates GNS tokens to an address.
//
// Converts GNS to xGNS and assigns voting power.
// Primary mechanism for participating in governance.
// Can delegate to self or any other address.
//
// Parameters:
//
//   - _: Noncrossing implementation-call discriminator; pass 0.
//
//   - rlm: Current realm context forwarded unchanged by the governance-staker proxy.
//
//   - to: Address to receive voting power (can be self)
//
//   - amount: Amount of GNS to stake and delegate
//
//   - referrer: Optional referral address for tracking
//
// Process:
//  1. Transfers GNS from caller
//  2. Mints equivalent xGNS (1:1 ratio)
//  3. Assigns voting power to target address
//  4. Creates delegation snapshot for voting
//
// Requirements:
//   - Minimum 1 GNS delegation
//   - Valid target address
//   - Sufficient GNS balance
//   - Approval for GNS transfer
//
// Returns:
//   - delegatedAmount: amount of GNS delegated and mirrored as xGNS
func (gs *govStakerV1) Delegate(
	_ int,
	rlm realm,
	to address,
	amount int64,
	referrer string,
) int64 {
	access.AssertIsRlmCurrent(0, rlm)

	halt.AssertIsNotHaltedGovStaker()

	prev := rlm.Previous()
	access.AssertIsValidAddress(to)

	assertIsValidDelegateAmount(amount)

	caller := prev.Address()
	from := caller
	currentHeight := runtime.ChainHeight()
	currentTimestamp := time.Now().Unix()

	emission.MintAndDistributeGns(cross(rlm))

	delegation, err := gs.delegate(
		0,
		rlm,
		from,
		to,
		amount,
		currentHeight,
		currentTimestamp,
	)
	if err != nil {
		panic(err)
	}

	if err := gs.increaseTotalDelegatedAmount(0, rlm, amount); err != nil {
		panic(err)
	}
	if err := gs.increaseTotalLockedAmount(0, rlm, amount); err != nil {
		panic(err)
	}

	gns.TransferFrom(cross(rlm), from, rlm.Address(), amount)
	xgns.Mint(cross(rlm), from, amount)

	registeredReferrer := referral.TryRegister(cross(rlm), caller, referrer)

	resolver := NewDelegationResolver(delegation)

	chain.Emit(
		"Delegate",
		"prevAddr", prev.Address().String(),
		"prevRealm", prev.PkgPath(),
		"from", resolver.delegation.DelegateFrom().String(),
		"to", resolver.delegation.DelegateTo().String(),
		"amount", utils.FormatInt(resolver.DelegatedAmount()),
		"totalDelegatedAmount", utils.FormatInt(gs.store.GetTotalDelegatedAmount()),
		"referrer", registeredReferrer,
	)

	return amount
}

// Undelegate undelegates xGNS from the existing delegate.
//
// Initiates withdrawal of staked GNS with lockup period.
// Voting power removed immediately, tokens locked for configurable period.
// Prevents governance attacks through time delay.
//
// Parameters:
//
//   - _: Noncrossing implementation-call discriminator; pass 0.
//
//   - rlm: Current realm context forwarded unchanged by the governance-staker proxy.
//
//   - from: Address currently delegated to
//
//   - amount: Amount of xGNS to undelegate
//
// Process:
//  1. Removes voting power immediately
//  2. Creates withdrawal request with timestamp
//  3. Locks GNS for configurable cooldown period
//
// Requirements:
//   - Must have delegated to target address
//   - Sufficient delegated amount
//
// After lockup period ends, use CollectUndelegatedGns() to claim GNS.
//
// Returns:
//   - undelegatedAmount: amount moved out of active delegation into undelegation lockup
func (gs *govStakerV1) Undelegate(
	_ int,
	rlm realm,
	from address,
	amount int64,
) int64 {
	access.AssertIsRlmCurrent(0, rlm)

	halt.AssertIsNotHaltedWithdraw()

	prev := rlm.Previous()
	caller := prev.Address()
	access.AssertIsValidAddress(from)

	assertIsValidDelegateAmount(amount)

	currentHeight := runtime.ChainHeight()
	currentTimestamp := time.Now().Unix()

	emission.MintAndDistributeGns(cross(rlm))

	unDelegationAmount, err := gs.unDelegate(
		0,
		rlm,
		caller,
		from,
		amount,
		currentHeight,
		currentTimestamp,
	)
	if err != nil {
		panic(err)
	}

	if err := gs.decreaseTotalDelegatedAmount(0, rlm, unDelegationAmount); err != nil {
		panic(err)
	}

	chain.Emit(
		"Undelegate",
		"prevAddr", prev.Address().String(),
		"prevRealm", prev.PkgPath(),
		"from", caller.String(),
		"to", from.String(),
		"amount", utils.FormatInt(unDelegationAmount),
		"totalDelegatedAmount", utils.FormatInt(gs.store.GetTotalDelegatedAmount()),
	)

	return unDelegationAmount
}

// Redelegate redelegates xGNS from an existing delegate to another.
//
// Atomic operation to change delegation target.
// Maintains voting power continuity without unstaking.
// Useful for vote delegation services and DAO coordination.
//
// Parameters:
//
//   - _: Noncrossing implementation-call discriminator; pass 0.
//
//   - rlm: Current realm context forwarded unchanged by the governance-staker proxy.
//
//   - delegatee: Current address delegated to
//
//   - newDelegatee: New address to delegate to
//
//   - amount: Amount of xGNS to redelegate
//
// Process:
//  1. Validates current delegation exists
//  2. Removes voting power from the old delegatee without a lockup
//  3. Assigns the same amount to the new delegatee
//  4. Updates delegation history and reward stake events
//
// Requirements:
//   - Must have active delegation to current delegatee
//   - Both addresses must be valid
//   - Amount must not exceed current delegation
//   - Cannot redelegate to same address
//
// No user-facing lockup period; reward accounting records one removal and one
// addition across the corresponding accrual epochs.
//
// Returns:
//   - redelegatedAmount: amount moved from the current delegatee to the new delegatee
func (gs *govStakerV1) Redelegate(
	_ int,
	rlm realm,
	delegatee,
	newDelegatee address,
	amount int64,
) int64 {
	access.AssertIsRlmCurrent(0, rlm)

	halt.AssertIsNotHaltedGovStaker()

	prev := rlm.Previous()
	caller := prev.Address()
	access.AssertIsValidAddress(delegatee)
	access.AssertIsValidAddress(newDelegatee)

	assertIsValidDelegateAmount(amount)
	assertNoSameDelegatee(delegatee, newDelegatee)

	currentHeight := runtime.ChainHeight()
	currentTimestamp := time.Now().Unix()
	delegator := caller

	emission.MintAndDistributeGns(cross(rlm))

	unDelegationAmount, err := gs.unDelegateWithoutLockup(
		0,
		rlm,
		delegator,
		delegatee,
		amount,
		currentHeight,
		currentTimestamp,
	)
	if err != nil {
		panic(err)
	}

	delegation, err := gs.delegate(
		0,
		rlm,
		delegator,
		newDelegatee,
		unDelegationAmount,
		currentHeight,
		currentTimestamp,
	)
	if err != nil {
		panic(err)
	}

	resolver := NewDelegationResolver(delegation)
	chain.Emit(
		"Redelegate",
		"prevAddr", prev.Address().String(),
		"prevRealm", prev.PkgPath(),
		"from", delegator.String(),
		"previousDelegatee", delegatee.String(),
		"newDelegatee", newDelegatee.String(),
		"amount", utils.FormatInt(resolver.DelegatedAmount()),
	)

	return amount
}

// CollectUndelegatedGns collects undelegated GNS tokens.
// Allows users to collect GNS tokens that completed undelegation lockup period.
// Burns xGNS and returns GNS tokens.
//
// Parameters:
//   - _: Noncrossing implementation-call discriminator; pass 0.
//   - rlm: Current realm context forwarded unchanged by the governance-staker proxy.
//
// Returns:
//   - collectedAmount: amount of undelegated GNS released to the caller after lockup expiry
func (gs *govStakerV1) CollectUndelegatedGns(_ int, rlm realm) int64 {
	access.AssertIsRlmCurrent(0, rlm)

	halt.AssertIsNotHaltedWithdraw()

	prev := rlm.Previous()
	caller := prev.Address()
	currentTime := time.Now().Unix()

	emission.MintAndDistributeGns(cross(rlm))

	collectedAmount, err := gs.collectDelegations(0, rlm, caller, currentTime)
	if err != nil {
		panic(err)
	}

	if collectedAmount == 0 {
		return 0
	}

	if err := gs.decreaseTotalLockedAmount(0, rlm, collectedAmount); err != nil {
		panic(err)
	}

	xgns.Burn(cross(rlm), caller, collectedAmount)
	gns.Transfer(cross(rlm), caller, collectedAmount)

	chain.Emit(
		"CollectUndelegatedGns",
		"prevAddr", prev.Address().String(),
		"prevRealm", prev.PkgPath(),
		"from", prev.Address().String(),
		"to", caller.String(),
		"collectedAmount", utils.FormatInt(collectedAmount),
	)

	return collectedAmount
}

// delegate processes delegation operations.
// Validates delegation amount, creates delegation records, and updates reward tracking.
func (gs *govStakerV1) delegate(
	_ int,
	rlm realm,
	from address,
	to address,
	amount,
	currentHeight,
	currentTimestamp int64,
) (*staker.Delegation, error) {
	delegationID := gs.nextDelegationID()
	delegation := staker.NewDelegation(
		delegationID,
		from,
		to,
		amount,
		currentHeight,
		currentTimestamp,
	)
	delegationResolver := NewDelegationResolver(delegation)
	delegatedAmount := delegationResolver.DelegatedAmount()
	if delegatedAmount < 0 {
		return nil, errors.New(errDelegatedAmountNegative)
	}

	if err := gs.addDelegation(0, rlm, delegationID, delegation); err != nil {
		return nil, err
	}
	gs.addDelegationRecord(0, rlm, to, delegatedAmount, currentTimestamp)
	if err := gs.addStakeEmissionReward(0, rlm, from.String(), amount, currentTimestamp); err != nil {
		return nil, err
	}
	if err := gs.addStakeProtocolFeeReward(0, rlm, from.String(), amount, currentTimestamp); err != nil {
		return nil, err
	}

	return delegation, nil
}

// unDelegate processes undelegation operations with lockup.
// Validates undelegation amount, processes withdrawals, and updates reward tracking.
func (gs *govStakerV1) unDelegate(
	_ int,
	rlm realm,
	delegator,
	delegatee address,
	amount,
	currentHeight,
	currentTimestamp int64,
) (int64, error) {
	delegationIDs := gs.getUserDelegationIDsWithDelegatee(delegator, delegatee)
	if len(delegationIDs) == 0 {
		return 0, nil
	}

	unDelegationAmount := amount
	lockupPeriod := gs.store.GetUnDelegationLockupPeriod()
	totalDelegated := int64(0)
	delegations := make([]*staker.Delegation, 0, len(delegationIDs))

	for _, id := range delegationIDs {
		delegation, exists := gs.store.GetDelegation(id)
		if !exists {
			continue
		}

		totalDelegated = gnsmath.SafeAddInt64(totalDelegated, NewDelegationResolver(delegation).DelegatedAmount())
		delegations = append(delegations, delegation)
	}

	if amount > totalDelegated {
		return 0, errors.New(errNotEnoughDelegated)
	}

	// Process undelegation across multiple delegation records if necessary
	for _, delegation := range delegations {
		resolver := NewDelegationResolver(delegation)
		if resolver.IsEmpty() {
			if err := gs.removeDelegation(0, rlm, delegation.ID()); err != nil {
				return 0, err
			}
			continue
		}

		currentUnDelegationAmount := unDelegationAmount

		if currentUnDelegationAmount > resolver.DelegatedAmount() {
			currentUnDelegationAmount = resolver.DelegatedAmount()
		}

		if currentUnDelegationAmount < 0 {
			return 0, errors.New(errUndelegationAmountNegative)
		}

		if currentUnDelegationAmount == 0 {
			continue
		}

		resolver.UnDelegate(
			currentUnDelegationAmount,
			currentHeight,
			currentTimestamp,
			lockupPeriod,
		)

		if err := gs.setDelegation(0, rlm, delegation.ID(), delegation); err != nil {
			return 0, err
		}
		gs.addDelegationRecord(0, rlm, delegatee, -currentUnDelegationAmount, currentTimestamp)
		if err := gs.removeStakeEmissionReward(0, rlm, delegator.String(), currentUnDelegationAmount, currentTimestamp); err != nil {
			return 0, err
		}
		if err := gs.removeStakeProtocolFeeReward(0, rlm, delegator.String(), currentUnDelegationAmount, currentTimestamp); err != nil {
			return 0, err
		}

		unDelegationAmount = gnsmath.SafeSubInt64(unDelegationAmount, currentUnDelegationAmount)
		if unDelegationAmount <= 0 {
			break
		}
	}

	return amount, nil
}

// unDelegateWithoutLockup processes undelegation without lockup.
// Used for redelegation where tokens are immediately available.
func (gs *govStakerV1) unDelegateWithoutLockup(
	_ int,
	rlm realm,
	delegator,
	delegatee address,
	amount,
	currentHeight,
	currentTime int64,
) (int64, error) {
	delegationIDs := gs.getUserDelegationIDsWithDelegatee(delegator, delegatee)
	if len(delegationIDs) == 0 {
		return 0, errors.New(errNotEnoughDelegated)
	}

	unDelegationAmount := amount
	totalDelegated := int64(0)
	delegations := make([]*staker.Delegation, 0, len(delegationIDs))

	for _, id := range delegationIDs {
		delegation, exists := gs.store.GetDelegation(id)
		if !exists {
			continue
		}

		totalDelegated = gnsmath.SafeAddInt64(totalDelegated, NewDelegationResolver(delegation).DelegatedAmount())
		delegations = append(delegations, delegation)
	}

	if amount > totalDelegated {
		return 0, errors.New(errNotEnoughDelegated)
	}

	// Process undelegation across multiple delegation records if necessary
	for _, delegation := range delegations {
		resolver := NewDelegationResolver(delegation)
		if resolver.IsEmpty() {
			if err := gs.removeDelegation(0, rlm, delegation.ID()); err != nil {
				return 0, err
			}
			continue
		}

		currentUnDelegationAmount := unDelegationAmount

		if currentUnDelegationAmount > resolver.DelegatedAmount() {
			currentUnDelegationAmount = resolver.DelegatedAmount()
		}

		if currentUnDelegationAmount == 0 {
			continue
		}

		resolver.UnDelegateWithoutLockup(
			currentUnDelegationAmount,
			currentHeight,
			currentTime,
		)

		if resolver.IsEmpty() {
			if err := gs.removeDelegation(0, rlm, delegation.ID()); err != nil {
				return 0, err
			}
		} else if err := gs.setDelegation(0, rlm, delegation.ID(), delegation); err != nil {
			return 0, err
		}
		gs.addDelegationRecord(0, rlm, delegatee, -currentUnDelegationAmount, currentTime)
		if err := gs.removeStakeEmissionReward(0, rlm, delegator.String(), currentUnDelegationAmount, currentTime); err != nil {
			return 0, err
		}
		if err := gs.removeStakeProtocolFeeReward(0, rlm, delegator.String(), currentUnDelegationAmount, currentTime); err != nil {
			return 0, err
		}

		unDelegationAmount = gnsmath.SafeSubInt64(unDelegationAmount, currentUnDelegationAmount)
		if unDelegationAmount <= 0 {
			break
		}
	}

	return amount, nil
}

func (gs *govStakerV1) increaseTotalDelegatedAmount(_ int, rlm realm, amount int64) error {
	currentDelegated := gs.store.GetTotalDelegatedAmount()

	if err := gs.store.SetTotalDelegatedAmount(0, rlm, gnsmath.SafeAddInt64(currentDelegated, amount)); err != nil {
		return err
	}

	return nil
}

func (gs *govStakerV1) decreaseTotalDelegatedAmount(_ int, rlm realm, amount int64) error {
	currentDelegated := gs.store.GetTotalDelegatedAmount()

	newDelegated := gnsmath.SafeSubInt64(currentDelegated, amount)
	if newDelegated < 0 {
		newDelegated = 0
	}
	if err := gs.store.SetTotalDelegatedAmount(0, rlm, newDelegated); err != nil {
		return err
	}

	return nil
}

func (gs *govStakerV1) increaseTotalLockedAmount(_ int, rlm realm, amount int64) error {
	currentLocked := gs.store.GetTotalLockedAmount()

	if err := gs.store.SetTotalLockedAmount(0, rlm, gnsmath.SafeAddInt64(currentLocked, amount)); err != nil {
		return err
	}

	return nil
}

func (gs *govStakerV1) decreaseTotalLockedAmount(_ int, rlm realm, amount int64) error {
	currentLocked := gs.store.GetTotalLockedAmount()

	newLocked := gnsmath.SafeSubInt64(currentLocked, amount)
	if newLocked < 0 {
		newLocked = 0
	}
	if err := gs.store.SetTotalLockedAmount(0, rlm, newLocked); err != nil {
		return err
	}

	return nil
}

// collectDelegations processes collection of undelegated tokens.
// Iterates through user delegations and collects available amounts.
func (gs *govStakerV1) collectDelegations(_ int, rlm realm, user address, currentTime int64) (int64, error) {
	totalCollectedAmount := int64(0)

	delegationTree := gs.getUserDelegations(user)

	var err error
	var idsToRemove []int64
	allDelegations := gs.store.GetAllDelegations()

	// Collect from all available delegations
	delegationTree.Iterate("", "", func(delegatee string, value any) bool {
		delegationIDs, ok := value.([]int64)
		if !ok {
			return false
		}

		if len(delegationIDs) == 0 {
			return false
		}
		for _, id := range delegationIDs {
			delegationRaw := allDelegations.Get(utils.FormatInt(id))
			if delegationRaw == nil {
				continue
			}
			delegation, ok := delegationRaw.(*staker.Delegation)
			if !ok {
				continue
			}

			resolver := NewDelegationResolver(delegation)

			collectedAmount, iErr := resolver.processCollection(currentTime)
			if iErr != nil {
				err = iErr
				return true
			}

			// Simple addition since addToCollectedAmount was removed
			totalCollectedAmount = gnsmath.SafeAddInt64(totalCollectedAmount, collectedAmount)

			// Save updated delegation state after collection
			if resolver.IsEmpty() {
				idsToRemove = append(idsToRemove, delegation.ID())
			} else {
				if iErr := gs.setDelegation(0, rlm, delegation.ID(), delegation); iErr != nil {
					err = iErr
					return true
				}
			}
		}

		return false
	})

	if err != nil {
		return totalCollectedAmount, makeErrorWithDetails(errInvalidAmount, err.Error())
	}

	for _, id := range idsToRemove {
		if err := gs.removeDelegation(0, rlm, id); err != nil {
			return totalCollectedAmount, err
		}
	}

	return totalCollectedAmount, nil
}

package staker

import (
	"chain"

	"gno.land/p/gnoswap/utils/v1"
	"gno.land/r/gnoswap/access/v1"
	"gno.land/r/gnoswap/halt/v1"
)

// SetUnDelegationLockupPeriodByAdmin sets the undelegation lockup period.
// This administrative function configures the time period that undelegated tokens
// must wait before they can be collected by users.
//
// The lockup period serves as a security mechanism to:
// - Prevent rapid delegation/undelegation cycles
// - Provide time for governance decisions to take effect
// - Maintain system stability during volatile periods
//
// Parameters:
//   - _: leading realm-call discriminator; callers pass 0 for the forwarded implementation call
//   - rlm: propagated current realm context validated before administrative state updates
//   - period: lockup period in seconds (must be non-negative)
//
// Panics:
//   - if caller is not admin
//   - if period is negative
//
// Note: This change affects all future undelegation operations
func (gs *govStakerV1) SetUnDelegationLockupPeriodByAdmin(_ int, rlm realm, period int64) {
	access.AssertIsRlmCurrent(0, rlm)

	halt.AssertIsNotHaltedGovStaker()

	prev := rlm.Previous()
	caller := prev.Address()
	access.AssertIsAdmin(caller)

	if period < 0 {
		panic("period must be greater than 0")
	}

	gs.setUnDelegationLockupPeriod(0, rlm, period)

	chain.Emit(
		"SetUnDelegationLockupPeriod",
		"prevAddr", prev.Address().String(),
		"prevRealm", prev.PkgPath(),
		"period", utils.FormatInt(period),
	)
}

// CleanStakerDelegationSnapshotByAdmin cleans old delegation history records.
// This administrative function removes delegation history records older than the specified threshold
// to prevent unlimited growth of historical data and optimize storage usage.
//
// The cleanup process:
// 1. Validates the snapshot time is within allowed range
// 2. Checks that no active proposals need data older than the cleanup threshold
// 3. Filters delegation history to keep only records after cutoff time
// 4. Updates the delegation history with filtered records
//
// Parameters:
//   - _: leading realm-call discriminator; callers pass 0 for the forwarded implementation call
//   - rlm: propagated current realm context validated before administrative state updates
//   - snapshotTime: cutoff timestamp (records older than this will be removed)
//   - target: the user address whose delegation history should be cleaned
//
// Panics:
//   - if caller is not admin
//   - if snapshotTime is invalid (negative or too recent)
//   - if active proposals have snapshotTime older than the cleanup threshold
func (gs *govStakerV1) CleanStakerDelegationSnapshotByAdmin(_ int, rlm realm, snapshotTime int64, target address) {
	access.AssertIsRlmCurrent(0, rlm)

	halt.AssertIsNotHaltedGovStaker()

	prev := rlm.Previous()
	caller := prev.Address()
	access.AssertIsAdmin(caller)

	assertIsValidSnapshotTime(snapshotTime)
	assertIsAvailableCleanupSnapshotTime(snapshotTime)

	// Clean total delegation history
	gs.cleanTotalDelegationHistory(0, rlm, snapshotTime)

	// Clean user delegation history
	gs.cleanUserDelegationHistoryForAddress(0, rlm, target, snapshotTime)

	chain.Emit(
		"CleanStakerDelegationSnapshot",
		"prevAddr", prev.Address().String(),
		"prevRealm", prev.PkgPath(),
		"snapshotTime", utils.FormatInt(snapshotTime),
		"target", target.String(),
	)
}

// cleanTotalDelegationHistory removes total delegation history entries older than cutoff time.
// Keeps the most recent entry before cutoff to preserve state continuity.
func (gs *govStakerV1) cleanTotalDelegationHistory(_ int, rlm realm, cutoffTimestamp int64) {
	history := gs.store.GetTotalDelegationHistory()

	// First, find the most recent entry before cutoff to preserve state
	var lastValue any

	hasLastValue := false

	history.ReverseIterate(0, cutoffTimestamp, func(timestamp int64, value any) bool {
		lastValue = value
		hasLastValue = true

		return true // stop after first (most recent)
	})

	// If there was a value before cutoff, set it at cutoff time to preserve continuity
	if hasLastValue && !history.Has(cutoffTimestamp) {
		history.Set(cutoffTimestamp, lastValue)
	}

	// Collect keys to remove (cannot modify tree during iteration)
	var keysToRemove []int64
	history.Iterate(0, cutoffTimestamp, func(timestamp int64, _ any) bool {
		keysToRemove = append(keysToRemove, timestamp)
		return false // continue
	})
	for _, key := range keysToRemove {
		history.Remove(key)
	}

	if err := gs.store.SetTotalDelegationHistory(0, rlm, history); err != nil {
		panic(err)
	}
}

// cleanUserDelegationHistoryForAddress removes user delegation history entries
// older than cutoff time for a single target address.
// Keeps the most recent entry strictly before cutoff
// in place so range-based snapshot lookups continue to resolve correctly.
func (gs *govStakerV1) cleanUserDelegationHistoryForAddress(_ int, rlm realm, target address, cutoffTimestamp int64) {
	if cutoffTimestamp <= 0 {
		return
	}

	history := gs.store.GetUserDelegationHistory()

	addrStr := target.String()
	iterationStartKey, _ := userHistoryKeyRange(addrStr)
	iterationEndKey := makeUserHistoryKey(addrStr, cutoffTimestamp)

	// First, find the most recent entry before cutoff to preserve state
	var lastValue any

	hasLastValue := false

	history.ReverseIterate(iterationStartKey, iterationEndKey, func(key string, value any) bool {
		lastValue = value
		hasLastValue = true

		return true // stop after first (most recent)
	})

	if hasLastValue && !history.Has(iterationEndKey) {
		history.Set(iterationEndKey, lastValue)
	}

	// Collect all keys strictly before preserveKey within this address prefix.
	// Iterate's end is exclusive, so [lo, preserveKey) skips the preserved entry.
	var keysToRemove []string

	history.Iterate(iterationStartKey, iterationEndKey, func(key string, _ any) bool {
		keysToRemove = append(keysToRemove, key)

		return false
	})

	for _, key := range keysToRemove {
		history.Remove(key)
	}

	if err := gs.store.SetUserDelegationHistory(0, rlm, history); err != nil {
		panic(err)
	}
}

package staker

import (
	"chain"
	"time"

	prbac "gno.land/p/gnoswap/rbac/v1"
	"gno.land/p/gnoswap/utils/v1"
	ufmt "gno.land/p/nt/ufmt/v0"

	"gno.land/r/gnoswap/access/v1"
	"gno.land/r/gnoswap/common"
	"gno.land/r/gnoswap/gns"
	"gno.land/r/gnoswap/gov/xgns"
	"gno.land/r/gnoswap/halt/v1"
)

// CollectReward claims all rewards for the caller.
//
// It settles both reward streams:
//  1. GNS emission rewards from the emission accumulator.
//  2. Protocol-fee rewards for every known token path.
//
// Protocol-fee rewards are divided by the total stake in force for each
// accrual epoch and settled across the caller's stake-event segments. They
// are not calculated from one current xGNS/total-xGNS ratio. Q128 fractional
// remainders remain in state for later collection.
//
// The all-token path intentionally grows with the number of known fee tokens.
// Use the token-specific entry point when bounded work is required.
//
// No business parameters are required; the caller's reward ID is used.
// Rewards are transferred directly to the caller.
//
// Parameters:
//   - _: Noncrossing implementation-call discriminator; pass 0.
//   - rlm: Current realm context forwarded by the governance-staker proxy; validated before settlement and transfers.
func (gs *govStakerV1) CollectReward(_ int, rlm realm) {
	access.AssertIsRlmCurrent(0, rlm)

	halt.AssertIsNotHaltedWithdraw()

	prev := rlm.Previous()
	caller := prev.Address()
	from := rlm.Address()
	currentTimestamp := time.Now().Unix()

	emissionReward, protocolFeeRewards, err := gs.claimRewards(0, rlm, caller.String(), currentTimestamp)
	if err != nil {
		panic(err)
	}

	// Transfer emission rewards (GNS tokens) if any
	if emissionReward > 0 {
		gns.Transfer(cross(rlm), caller, emissionReward)

		chain.Emit(
			"CollectEmissionReward",
			"prevAddr", prev.Address().String(),
			"prevRealm", prev.PkgPath(),
			"from", from.String(),
			"to", caller.String(),
			"emissionRewardAmount", utils.FormatInt(emissionReward),
		)
	}

	// Transfer protocol fee rewards for each token type
	for tokenPath, amount := range protocolFeeRewards {
		if amount > 0 {
			err := transferToken(0, rlm, tokenPath, from, caller, amount)
			if err != nil {
				panic(err)
			}

			chain.Emit(
				"CollectProtocolFeeReward",
				"prevAddr", prev.Address().String(),
				"prevRealm", prev.PkgPath(),
				"tokenPath", tokenPath,
				"from", from.String(),
				"to", caller.String(),
				"collectedAmount", utils.FormatInt(amount),
			)
		}
	}
}

// CollectEmissionReward collects accumulated GNS emission rewards only.
//
// Parameters:
//   - _: Noncrossing implementation-call discriminator; pass 0.
//   - rlm: Current realm context forwarded by the governance-staker proxy; validated before settlement and transfer.
func (gs *govStakerV1) CollectEmissionReward(_ int, rlm realm) {
	access.AssertIsRlmCurrent(0, rlm)

	halt.AssertIsNotHaltedWithdraw()

	prev := rlm.Previous()
	caller := prev.Address()
	from := rlm.Address()
	currentTimestamp := time.Now().Unix()

	emissionReward, err := gs.claimRewardsEmissionReward(0, rlm, caller.String(), currentTimestamp)
	if err != nil {
		panic(err)
	}

	if emissionReward > 0 {
		gns.Transfer(cross(rlm), caller, emissionReward)

		chain.Emit(
			"CollectEmissionReward",
			"prevAddr", prev.Address().String(),
			"prevRealm", prev.PkgPath(),
			"from", from.String(),
			"to", caller.String(),
			"emissionRewardAmount", utils.FormatInt(emissionReward),
		)
	}
}

// CollectProtocolFeeReward collects accumulated protocol fee rewards for the provided token path.
//
// Parameters:
//   - _: Noncrossing implementation-call discriminator; pass 0.
//   - rlm: Current realm context forwarded by the governance-staker proxy; validated before settlement and transfer.
//   - tokenPath: registered fee-token path whose reward should be collected
func (gs *govStakerV1) CollectProtocolFeeReward(_ int, rlm realm, tokenPath string) {
	access.AssertIsRlmCurrent(0, rlm)

	halt.AssertIsNotHaltedWithdraw()

	prev := rlm.Previous()
	caller := prev.Address()
	from := rlm.Address()
	currentTimestamp := time.Now().Unix()

	amount, err := gs.claimRewardProtocolFeeRewardByTokenPath(0, rlm, caller.String(), tokenPath, currentTimestamp)
	if err != nil {
		panic(err)
	}

	if amount > 0 {
		err := transferToken(0, rlm, tokenPath, from, caller, amount)
		if err != nil {
			panic(err)
		}

		chain.Emit(
			"CollectProtocolFeeReward",
			"prevAddr", prev.Address().String(),
			"prevRealm", prev.PkgPath(),
			"tokenPath", tokenPath,
			"from", from.String(),
			"to", caller.String(),
			"collectedAmount", utils.FormatInt(amount),
		)
	}
}

// CollectRewardFromLaunchPad collects rewards for launchpad project wallets.
//
// Parameters:
//   - _: Noncrossing implementation-call discriminator; pass 0.
//   - rlm: Current realm context forwarded by the governance-staker proxy; validated before launchpad reward settlement.
//   - to: project wallet address receiving its emission and protocol-fee rewards
//
// Only callable by launchpad contract.
func (gs *govStakerV1) CollectRewardFromLaunchPad(_ int, rlm realm, to address) {
	access.AssertIsRlmCurrent(0, rlm)

	halt.AssertIsNotHaltedWithdraw()

	prev := rlm.Previous()
	caller := prev.Address()
	access.AssertIsLaunchpad(caller)

	from := rlm.Address()
	currentTimestamp := time.Now().Unix()

	launchpadRewardID := gs.makeLaunchpadRewardID(to.String())
	_, exists := gs.getLaunchpadProjectDeposit(launchpadRewardID)
	if !exists {
		panic(makeErrorWithDetails(
			errNoDelegatedAmount,
			ufmt.Sprintf("%s is not project wallet from launchpad", to.String()),
		))
	}

	emissionReward, protocolFeeRewards, err := gs.claimRewardsFromLaunchpad(0, rlm, to.String(), currentTimestamp)
	if err != nil {
		panic(err)
	}

	// Transfer emission rewards (GNS tokens) to project wallet if any
	if emissionReward > 0 {
		gns.Transfer(cross(rlm), to, emissionReward)

		chain.Emit(
			"CollectEmissionFromLaunchPad",
			"prevAddr", prev.Address().String(),
			"prevRealm", prev.PkgPath(),
			"from", from.String(),
			"to", to.String(),
			"emissionRewardAmount", utils.FormatInt(emissionReward),
		)
	}

	// Transfer protocol fee rewards to project wallet for each token type
	for tokenPath, amount := range protocolFeeRewards {
		if amount > 0 {
			err := transferToken(0, rlm, tokenPath, from, to, amount)
			if err != nil {
				panic(err)
			}

			chain.Emit(
				"CollectProtocolFeeFromLaunchPad",
				"prevAddr", prev.Address().String(),
				"prevRealm", prev.PkgPath(),
				"tokenPath", tokenPath,
				"from", from.String(),
				"to", to.String(),
				"collectedAmount", utils.FormatInt(amount),
			)
		}
	}
}

